/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100308-3","meetingId":"h22-c-budget","date":"2010年3月8日","dateIso":"2010-03-08","committee":"予算特別委員会","time":"午前１０時０２分～午後５時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を159件抜き出しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"原委員","kind":"質問","question":"私は、８２ページ、８３ページ、８４ページ、８５ページ、８６ページ、８７ページ、使用料及び手数料のところで、幾つか質問をします。初めに大きいくくりとして、目の部分で、全体的な手数料なんですけれども、ここ数年の累計を見ていただいて、思われることを、どういうふうな形で考えておられるのか。手数料部分、１から５までで、よろしくお願いいたします。","respondent":"金子企画財政課長","answer":"さまざまな変動要素によって変動しておりますが、この経済情勢の中で、今は手数料の額を改定する時期には至っていないと考えていますが、例えば、先ほど申しましたとおり、住民基本台帳カードを４月から半額にするとか、さまざまに細かいところで一つ一つ見直しながら。","id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"全体的に変わっていないと。ちょっと確認を含めてなんですけれども、品川区のホームページの中で、土木手数料、平成１９年６月２０日現在ということになっているので、これは変わっていないかということを１点、確認をさせていただきたいということです。２点です。","respondent":"片田建築課長","answer":"昨今の経済状況の厳しさが、この件数にあらわれているのかなと考えています。","id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"今、ご説明いただいたので納得はできるんですけれども、私のほうで、感覚ではなくて、現実の数字を拾ってまいりました。これはこういう席で言っていいのかどうかわかりませんけれども、実際に構造計算に関しましては、基本的に、２３区は同じだと思うんです。","respondent":"片田建築課長","answer":"適合判定につきましても、都知事が指定しているという状況ですので、どの機関も一定額の判定手数料という状況です。ただ、実際には、各区の申請の状況、それから大きな物件がある、ないとか、そういう状況の中で、このような数字になってきているものと認識しております。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"おっしゃるとおり、品川区の場合には、全体的に優良住宅の件数もかなり多いですし、金額面で大きいのは、要するに高層建物、大規模開発、この辺のいろいろな形での金額等が多いと思うんです。この工作物に関しては、先ほど申し上げたように、中間を受けている、受けていない関係なく、実際には９,６００円という形で出されている。その辺について、ちょっとコメントいただければと思います。","respondent":"片田建築課長","answer":"ただ、そういう実態が、デマンドに合わせて処理しているというようなところもありますので、その結果であると認識しています。","id":"exchange-004"},{"speaker":"原委員","kind":"意見","question":"そうしますと、全体的には、先ほど、民間が受けているというところで数字が下がってきているのは、どうにかならないかと思うんですが、そこら辺についてのお考えを１点。","respondent":"片田建築課長、金子企画財政課長","answer":"特に民間との比較の中では、やはり現在、民間への動向については、なかなか食いとめることが難しいような状況です。ただ、私どもとしましては、この前も申し上げましたが、課すべきものはきちっと課して、徴収すべきものはきちっと徴収していこうと考えております。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、７８ページの区民住宅使用料、９７ページ、住宅・建築物耐震化補助金の区営住宅管理費、そして同じく、地域住宅交付金で、区営住宅管理費ほか８事業、それから１１９ページの区営住宅補助金、区営住宅管理費と、区営住宅に関して質問をします。お願いします。","respondent":"柏原住宅担当課長","answer":"９７ページ、それから１１９ページ等の区営住宅の住宅管理です。９７ページにありますのは、こちらの節にもありますように、耐震化補助金ということで、こちらのほうは、平成２２年度に耐震改修工事を行う住宅の実施設計の委託に使うものです。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"これはいわゆる住宅使用料ですので、家賃のことだと思うんですが、今おっしゃった地域住宅交付金、あるいは、区営住宅補助金というもので、家賃の補助をしながら住んでいらっしゃる方の家賃使用料というところで集められているところだと思うんですが、住んでいらっしゃる方の生活実態調査というのでしょうか、これはどのようなシステムでされているのか。","respondent":"柏原住宅担当課長","answer":"こちらのほうは、それをもとに家賃計算をいたしますので、各世帯に通知をさせていただきまして、住民票であるとか、税証明であるとかいった形で、お住まいの人数であるとか、どんな方がお住まいか、それから、収入の状況はどうかといったところで、定期的に１年に１度。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"１年に１度、その生活実態調査というか、状況を把握していくというところで、使用料というところで、こういうふうに上がってくるんだと、わかりました。ここ二、三年の入居状況というんでしょうか、その推移を、まず教えていただきたい。そして、入居状況に、例えば、入居が多くあったところ、あるいは、少ないところ、そういう地域差がもしあるのであれば、それも教えてください。","respondent":"柏原住宅担当課長","answer":"入居の状況です。ここ３年間で申しますと、平成１９年度に入居された方は７世帯、それから、平成２０年度で７世帯、平成２１年度に関しましては、まだ途中ですけれども、２３世帯が入居されております。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"年によって大分差があるのだなと感じましたし、また、特に偏りはないということでありますけれども、今年度は２３件あったということなので、かなり年によっては差があるということで、状況はわかりました。この状況によって、いわゆる募集件数、大体、１棟当たり１０件だと思うんですが、これの根拠を教えてください。","respondent":"柏原住宅担当課長","answer":"ただ、団地によりまして多い少ないはあるんですけれども、今回、平成２１年度については、もう既に７件ほどいっている団地、それから６件というような形で進んでいる団地もありますので、１０件程度ということでやらせていただいております。","id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"そうなると、ここのところ３年の推移を見てみると、１０件までいかない状況というのはあるわけで、たまたま今回、７件というのがあったわけですけれども、こういった区民の声というのでしょうか、要するに番号をもらったけれども、空き室があったら入るんだとは理解していても、やはり番号をもらうと期待をしてしまうというところで、１０件という数は、何というんでしょうか。","respondent":"柏原住宅担当課長","answer":"１０件より少なくしたらいいのか、増やしたらいいのかというのはなかなか難しいんですけれども、そういった区民の声があるというのは、お聞きしておりますので、その辺も含めながら考えていきたいと考えています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"国庫補助金のうち９６ページの地域住宅交付金について、木造住宅の耐震シェルター、簡易補強について伺いたいと思います。","respondent":"吉川防災整備担当課長","answer":"国の補助制度ですが、国の要綱では、基本的に自治体、区市町村が耐震化支援を行う助成金について、その２分の１を助成するという形になっております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"区市町村が決めるということは、国自身も、いわゆる簡易補強、評点１.０以下についても対象にしているということでよろしいのでしょうか。","respondent":"吉川防災整備担当課長","answer":"区市町村で評点１.０未満のものに助成制度を出している場合は、それも対象になるです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"国の補助金については、市区町村が決めた評点１.０以下の簡易補強、シェルターも含めて対象にしているということですけれども、品川区の現行の住宅改修助成制度は、評点１.０以上と限定しているんですけれども、この理由はなぜなのか。つまり、評点１.０から０.７までの簡易補強を対象としないのか、その理由をご説明いただけますか。","respondent":"吉川防災整備担当課長","answer":"耐震基準、評点１.０未満の改修というのは、基本的には耐震化とはならず、安全なまちづくりにもつながらないということがありますので、現在のところ、助成対象にはしていないです。なお、東京都の補助制度でも、現在、こちらのほうは補助対象にはなっておりません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"実際に、品川区も品川シェルターや、さまざま研究も行っているわけですけれども、耐震化にはつながらないということだけではなくて、命を守るという視点で、評点１.０以下についても対象を検討すべきではないかと思うんですけれども、いかがでしょうか。これについて、改善が必要ではないかと思うんですけれども、いかがでしょうか。","respondent":"吉川防災整備担当課長","answer":"評点１.０未満の改修に、まず助成をすべきではないかというお話ですが、今後の支援制度の範囲につきましては、現在、東京都が評点１.０未満の部分改修への助成制度導入を検討していますので、その動向を踏まえつつ。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"今、東京都が検討しているから、それを見ていきたいとのご説明だったと思うんですけれども、区の主体性がどこにあるのか疑問でなりません。評点１.０以下の、いわゆる命を守る、崩れるのを防ぐといいますか、崩れないようにしていく必要性が、私はあると思うんですけれども、区の主体性はどこにあるのか伺いたいと思います。","respondent":"岩田防災まちづくり事業部長","answer":"命を守るためにやったのに、命が守れなかったのでは、どうしようもないわけです。したがって、ここのところはやっぱり、慎重に対応しなければいけない。では、品川区は何もしないかといったら、そうではありませんで、区長の英断で、命を守る対策も最初から打っているわけです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん慎重な検討は、当然必要だと思いますけれども、先ほど、東京都が検討しているという話がありましたけれども、どういう中身なのか教えていただきたい。実際に、新宿区や墨田区では、そういう方法をやっているとも伺っているんですけれども、その辺はどういう状況なのか、ご説明いただけますでしょうか。","respondent":"吉川防災整備担当課長、片田建築課長","answer":"東京都の検討状況ですが、まだ、検討中で確定はしていないんですけれども、今のところ聞いている範囲では、段階的な部分改修へ助成制度導入。その意味では、将来的に評点１.０にすると。これは、今後、区内業者にも活用していただきたいということで、今、マニュアル化を検討しておりますので、それであれば、１メーカーではなくて、そういうマニュアルに沿った形であれば。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、検討しているそのマニュアル化というものが、どういうものなのかよくわかりませんでしたので、ご説明いただきたいと思うんですけれども、安全を確認するには、耐震診断をして、それに基づいて、初めは評点０.７かもしれないけれども、将来、評点１.１以上にしていこう、いろいろな工夫の中で、簡易補強は十分に可能ではないかと思ったのが、区内の工務店の方に聞いたんですけれども。","respondent":"片田建築課長","answer":"あくまでも、簡易補強評点０.７以上ということについても、必ず耐震診断を基本に置いております。耐震診断を基本に置いて、このような補強をしたら評点０.７以上になってくると、そういうものに対して支援をしてきているという状況です。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ来るかわからないと言われている中で、品川区内での命を守るという視点での簡易補強がなかなか進んでいない実態があります。ぜひ、制度を改善、充実させて進めていただきたいと思います。担当の職員の方も、１人が担当で、先日の本会議では、チームでやっているというお話もありましたけれども、職員体制もしっかりと整えて進める必要があると思いますので、ぜひ改善していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田委員","kind":"提案","question":"できれば、禁煙とは言わずに、国が決めていることですからあれですけれども、分煙をしていただいて、たばこを吸う人にも、吸わない人のためにも配慮をしていただければと思うんですが、お考えをお聞かせください。目黒駅前地区再開発について、これからだと思うので、地域からさまざまな要望が出ていると思うので、その要望をできる限り反映するように区からも働きかけをよろしくお願いします。","respondent":"金子企画財政課長、諸岡商業・観光課長、矢部生活安全担当課長","answer":"ネーミングライツについてのお尋ねですけれども、それは私どもも検討してきた経過がありますが、なかなか区において適切な施設が少ないということで。中小企業センターにおけます、国際友好協会に対して、光熱水費相当分等の負担をいただく分ですけれども、国際友好協会の移転先が決定したのが。それを、中洲のなるべく歩行者が通らないようなところに移設しております。このような形で、分煙を進めていきたいと思います。","id":"exchange-019"},{"speaker":"井桁委員","kind":"質問","question":"私は、７９ページ、５目土木使用料のロケーション・写真撮影等と、１４３ページ、５目雑入の中のリサイクル資源売払収入、しながわ水族館運営費収入について、お伺いしたいと思います。それから、この傾向を見ていますと、回収量も年々減ってきているとは思うんですけれども、そこのあたりとの兼ね合いがやはりあると思うんですが、そこのところをお願いいたします。","respondent":"太田品川区清掃事務所長","answer":"ペットボトルについては、２０円から３２円で推移していたものが、７円という状況での推移が、量というよりも、今申し上げた単価が一番の大きな原因と考えているところです。","id":"exchange-020"},{"speaker":"井桁委員","kind":"質問","question":"それとも、今回が初めてなのか、そのあたりをちょっとお伺いしたいと思います。というのも、このように単価の上下がかなりあるということは、今、やられているリサイクルで、区民から集団回収の際に、たしか１kg当たり６円で買い取りといったことをやられていると思うんですけれども、そのあたりの影響というのは、どのようにお考えでしょうか。","respondent":"太田品川区清掃事務所長","answer":"２点目の集団回収における６円のお話ですが、これは市況の単価とかかわりなく、集団回収を実施していただいている町会、団体の方に対する一種の奨励金的なものですから、これについては平成２２年度も６円ということで変更なく実施する予定です。","id":"exchange-021"},{"speaker":"井桁委員","kind":"質問・要望","question":"このような単価の上下というのは、今までに見たことのない変化だと思うんですけれども、やはり、集団回収の際の支給の金額も変わらず続けていただきたいということと、やはり、これからも柔軟に対応していっていただきたいと考えています。そして、ちょっと気になっていたんですが、回収量が年々減ってきているとは思うんですが、そこらあたりの工夫をお伺いできればと考えています。","respondent":"太田品川区清掃事務所長","answer":"資源の回収量についてですけれども、この間、平成２０年１０月におきましても、分別変更の際に、汚れていない容器包装プラスチックを資源の回収品目として追加いたしましたし、蛍光灯の部分も資源の回収品目に追加しています。","id":"exchange-022"},{"speaker":"井桁委員","kind":"質問・要望","question":"これからもリサイクル、そして有効に活用するということでも、品川区が積極的に取り組んでいることは、今後も、ぜひともアピールしていただきたいと考えています。それから、入館者数がすごく減っているのかなというように、一見してとらえられますけれども、そこらあたり、この大幅減の理由をお聞かせいただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"しかしながら、平成２１年度は少しでも景気が回復するだろうということで、平成１９年度相当分を見込んでいたのですが、実際には、高速道路の１,０００円の話、それから、新型インフルエンザの影響もあり、なかなか伸び悩んだということで、その辺を踏まえながら。","id":"exchange-023"},{"speaker":"井桁委員","kind":"質問・要望","question":"しながわ水族館は平成３年開館で、それ以来順調に来館者数も伸ばしてきているとは思うんですが、このような経済危機というのは、先ほどもあったんですけれども、ランニングコストの面を考えたりとか、今後のことを考えていくと、やはり積極的に来館者数を増やしていくことが大切になってくると思うんですが、目標来館者数と、今後の水族館への意気込みを、ぜひお聞かせいただきたいと考えています。","respondent":"藤田水とみどりの課長","answer":"平成１９年度には６０万２,０００人、平成２０年度については５７万７,０００人ということで、平成２１年度につきましては、平成１９年度相当を見込んでいたわけですが、現在、そこまで伸びないできている、おおむね５３万人ぐらいではないかという数値になっております。","id":"exchange-024"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひとも、平成１７年度の７２万人に届くように、また今後、水族館というのは、修繕等々、かなりのコストがかかってくることも見込まれてくると思いますので、そこのあたりを考えても、先ほど、水とみどりの課長もおっしゃられたように、さまざまな工夫をされていると思いますので、ぜひ頑張っていただきたいと考えています。","respondent":"小野土木管理課長","answer":"品川区を紹介していただけるいい機会ということもございまして、特に番組制作だとか、商業撮影ということではなくて、公園そのものの紹介、あるいは、地域の紹介という場合には、占用料を免除するというふうな仕組みもありますので、そういうところも含めて。","id":"exchange-025"},{"speaker":"渡部委員","kind":"質問・要望","question":"歳入の中で、４９ページに表がありまして、前年との比較が出ています。聞いていくのは、また金曜日に続いて、税金のことを伺っていこうと思います。そのような中で、前年度も９４.４６％という収入率が算定されていたんですが、今回、あまりにも低い９２.２０％というふうに設定した根拠を、まずお示しいただきたい。今、税の相談を４階でも相当受けていると思います。","respondent":"武内税務課長","answer":"委員、ご案内のとおり、４階のほうで納税相談を、毎日実施しているわけですけれども、やはり、こういう納税義務者が増大しているということで、ご案内のとおり、平成１９年度から税源移譲において、住民税が倍額になっている方も当然いらっしゃいます。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"数字のところは理解いたしました。大変な状況が続いているんだなと思います。いろいろな相談を受けて、実際にルールにのっとった支払ができないといった場合に、特別区税、また別のページにもあるんですけれども、諸収入のほうに入るんでしょうか、例えば滞納があった場合に、延滞金が発生すると思います。","respondent":"武内税務課長","answer":"ただ、納め忘れとか、特に理由がない場合につきましては、お支払いいただかないと、先ほど、言ったように、９５％の方は真面目にお支払いいただいているのが現実ですので、そういう部分では、まずそういう交渉をするです。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"先ほども示しました、ファイナンス会社ですと、延滞利息のパーセンテージの付加プラスアルファで、事務手数料を別途２１０円とか、３００円とかがかかるケースがあるんですが、よりわかりやすくするために、収入を増やすとかではなく、例えば、それが何十円であっても、郵送に係る手数料という形での徴収を、私はすべきだと思うんですが、その辺の考え方はいかがでしょうか。","respondent":"武内税務課長","answer":"私が説明したとおり、延滞金につきましては、公平公正さということで、事前の交渉をする際には、これをこのまま放置しますと、このような延滞金が発生しますということで説明させていただきまして、その後、その辺の理由、または担税力を見極めて。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうからは、１１２ページのやさしいまちづくり計画推進費について。２点目には、１３３ページの資源持ち去り防止過料について、３点目には、１４１ページの各種事業参加費負担金の中の水中散歩教室参加費について、お伺いします。初めに、１３３ページの資源持ち去り防止過料について、お伺いします。資源持ち去り防止過料について、こちらの制度を教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"区としてできることがないかということで検討をしてまいりました結果、地方自治法第１４条で、条例の中でルールを定めることによって、そのルールに反した者に対して罰金ですとか、過料を科すことができるという条文を受けまして、平成２０年７月に。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"今、お話しいただきました、５万円の過料ということですが、一つは、昨年は過料を取るようなことがなかったのか。それからもう一つ、パトロール隊が編成をされたとお聞きいたしましたが、朝何時からパトロールをしていただけるのか、その辺をちょっと教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"パトロール隊についてですが、品川地区一帯、荏原地区一帯ということで、２隊編成しています。時間帯は、大体６時半ぐらいに庁舎をスタートして、それぞれ９時過ぎまで、第１回目のパトロールをしています。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"実は、ある方がマンションのところで、違法な新聞の持ち去りで、罵声を浴びせられて、大変怖い思いをしたということでした。この辺は、予定としては、あるのかどうか教えていただきたいと思います。","respondent":"太田品川区清掃事務所長","answer":"どうか、事務所のほうへ、遠慮なくご連絡をいただければと考えております。それから、Ｅメールについては、当然、あります。ホームページ等の中で、修正といいますか、書くようにしていきたいと考えています。","id":"exchange-031"},{"speaker":"山元委員","kind":"確認","question":"私が見たところが、Ｅメールがなかったのかなと思いますけれども。すみません、もう１回、確認なんですが、パトロールを各地域にしてくださるというのは、時間帯は何時からか、もう１回、教えていただいていいですか。","respondent":"太田品川区清掃事務所長","answer":"時間帯は、朝６時半から９時過ぎまで、第１便として回っております。その後、状況に応じて、午前中もう１便回るというようなことでやっております。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"皆さん、品川区のために使っていただきたいと思っているものですから、ぜひ、パトロールのほうを厳重にしていただきたいと思います。次に移らせていただきます。１４１ページの水中散歩教室参加費について、少しお伺いさせていただきたいと思います。これは、実際、一人あたりどのくらいなのかということと、もう一つ、年代的にお幾つぐらいの方たちが多いのか、もしわかれば教えていただきたいと思います。","respondent":"山岡健康課長","answer":"水中散歩教室の参加費ですが、年に大体１０回のコースを３期やっております。大体１０回で、１回当たり５００円、１期５,０００円をいただいているものです。水中散歩ですので、泳ぐということではありません。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"例えば７５歳以上の方は、少し助成をしてくれるとか、そういうことはなく、全員一律５,０００円になるのでしょうか。","respondent":"山岡健康課長","answer":"特に年齢で負担の額を変えるということはやってございませんので、どの年齢の方でも、１回当たり５００円で、１０回のコースでしたら５,０００円お支払いいただくということになっております。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問","question":"もう１点。教室の内容なんですけれども、先ほど、ウォーキングというか、プールの中を歩くと言っておられましたけれども、例えば、コーチではないんですけれども、指導するような方がついているのか、どうか。監視員はいらっしゃるのか、どうか、ちょっと教えていただけますか。","respondent":"山岡健康課長","answer":"当然ですが、指導員、インストラクターがおります。各コース、高齢者も多いということで、１時間ということで、インストラクターのもとでやっている。当然、監視員もつけているところです。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"ある程度年齢がいきますと、とてもひざに負担がかかり、歩くのに大変苦労をしていらっしゃる方がいます。実は、年金暮らしの方にとって、５,０００円というのは大変大きくて、私のほうにも、この辺、少し助成できないかなというお話がありました。今、５,０００円とおっしゃいましたけれども、例えば、回数券でお買いになったら少しおまけとか、そんなような予定はないでしょうか。","respondent":"山岡健康課長","answer":"今のところ、その予定はございません。これは、年齢でというよりも、年齢がそう高くなくても、いろいろとひざに故障を抱えている方とか、これを利用して身体の改善を図るといった方もいらっしゃいますので、特に年齢でどうこうというのは、今のところ、考えていません。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がないので、次に移らせていただきます。やさしいまちづくり計画推進費について、教えていただきたいと思います。内容について、教えていただきたいと思います。","respondent":"松代都市計画課長","answer":"ここに計上しておりますのは、鉄道駅におけますエレベーター、エスカレーター等の設置の計画です。今年度は、京浜急行新馬場駅にエレベーターを３基設置するということでの都の補助金というものです。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"新馬場駅にエレベーターをつけていただきたいという声があちらこちらから、私のもとにも届いておりました。そういう意味では、大変嬉しく思いますけれども、新馬場駅は大変長い駅なので、具体的にどの辺につくのか、教えていただけますでしょうか。","respondent":"松代都市計画課長","answer":"新馬場駅のエレベーターの設置ですけれども、北口に今回、設置をする予定です。","id":"exchange-038"},{"speaker":"山元委員","kind":"意見","question":"ほんとうに、小さい子どもとか、お年寄りは、エスカレーターは大変怖いんですね。そういう意味では、エレベーターに乗って上がることの安心さはありますので、北口ももちろんですけれども、南口のほうも、少しでも早くお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"５８ページの財調について、お伺いします。集会所に関してだけ、こういう大ざっぱな書き方をしているのは、何か根拠があるのか、教えてください。それから、８８ページの国庫負担金で、国民年金事務費なんですけれども、毎年下がっていると思うんですけれども、落ちている理由について、お伺いします。","respondent":"金子企画財政課長、本城国保医療年金課長","answer":"財調に関しましては、前段のところでご説明申し上げましたとおりですが、少し詳しく申し上げますと、財調の原資であります固定資産税は、実は４.７％伸びております。これは、家屋等が増えているというような内容であります。国民年金事務費の国の補助金に関してですが、年金の補助金については、国から示されている算定基礎額に年間平均被保険者数等を乗じて計算されているもので、その関係で、ここ数年の経緯を見ても、若干ずつ減っている状況にはあります。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"年金からいきますけれども、私の質問で、減っていますが、どういう理由ですかと聞いたので、減っていますというと、そのとおりですと言うしかないので、そこをお願いします。それが増えていくというのがわかっているにもかかわらず、この予算が減っていくというのはおかしいと思うんですけれども、その辺について、どうでしょうか。","respondent":"金子企画財政課長、本城国保医療年金課長","answer":"そういう意味では、個別的な課題については、随時、検討してまいりますが、全体的なところとしては、今の段階では、使用料に関して見直す段階ではないと考えているところです。ただ、今、委員からもお話がございましたように、年金事務については、基本的に国の責任で実施するですので、年金に係る国の負担金が低減している関係で、区として持ち出しになるお金も生じているところですので、これについては。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"企画財政課長の前職も、産業振興課長ですよね。この企画の２人がちょうど偶然並んでいますけれども、産業振興課から上がってきているということは、いくら課が変わっても、やっぱりその辺の強さを品川区は出していかないといけないと思うんですけれども、年金はもういいですから、その辺に関して、企画部長でも、企画財政課長でも、答弁していただきたいと思います。","respondent":"金子企画財政課長","answer":"人事異動に関しましては、自分で決めるわけではないので、何とも言いがたいところがありますが、ただ、当然、産業振興というところを経験して企画財政部門というのは、私ども以外にも過去にありましたし、そういう意味では、ある程度、区内の地域経済の知識を蓄積して。","id":"exchange-042"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、６７ページのプラネタリウムの項目、そして、７１ページの天王洲公園の項目で伺っていきます。それから、当然、教育施設という前提の中で、入場料収入も考え方としてあるとは思うんですが、私自身、教育施設という点から、採算性を求めるのではなくて、他のさまざまな効果を求める考えがあると思いますが、その点を、２点目で伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"そのほかに品川区スポーツ協会に登録がありますところで言いますと、野球の団体数が約２００団体で、人数にして５,０００人強です。サッカーの団体数が約７０団体で、２,８００人ぐらいが競技人口というところで把握をしています。","id":"exchange-043"},{"speaker":"渡辺委員","kind":"質問・要望","question":"先に、天王洲公園のところから伺います。競技人口等を把握されているか伺ったのは、これは、ぜひ見直していただきたいと思っています。そういう要望も含めて伺います。ですから、競技団体等を数えていっても、どうしても上限があるという点から、今後の施設の有効利用の点からも、正確な数値が必ず必要になってくると思います。それから、個人の大人の有料入場者もかなり見込めると思います。","respondent":"堀越文化スポーツ振興課長","answer":"こういった幼児もそうですが、私どものプラネタリウムの特色といたしましては、生の声による解説を基本としておりますので、お客様のいろいろな特徴等に応じて対応をしていくことが可能であると思います。","id":"exchange-044"},{"speaker":"稲川委員","kind":"質問","question":"私は、５０ページの特別区民税、６４ページの使用料の中のグラウンド関係、そして、８６ページの開発行為手数料について、お伺いいたします。納税をした方は、基本的に品川区のさまざまなサービスを受ける権利があるか、どうか、私はあると思っているのですが、そこをまず１点、お伺いいたします。","respondent":"武内税務課長","answer":"もちろん、税を払うとか、払わないとかということではなくて、品川区民でありましたら、それぞれ品川区で行っている施策に該当するサービスは、全区民が受給できると考えております。","id":"exchange-045"},{"speaker":"稲川委員","kind":"質問","question":"本題に入りますと、前回も補正予算で、たしかお話があったと思うんですが、特別徴収というのは、会社が個人にかわって税金を納めるということだと思うんですが、例えば、景気が悪くて会社がつぶれてしまったときとか、あとは給料から天引きをされながらも、実は会社が納税をしていなかった場合は、個人に請求がいくのかどうなのか、どういう形で請求がかかるのか、教えてください。","respondent":"武内税務課長","answer":"言われたとおり、経営が困難だとかいう場合でも、運営している場合については、特別徴収義務者という、いわゆる給与支払者、実務的には社長になると思うんですけれども、その方にあくまでも督促が行って、お支払いくださいという交渉をします。","id":"exchange-046"},{"speaker":"稲川委員","kind":"質問","question":"例えば、多分これはあると思うんですけれども、給料から税金が引かれていながら、会社がつぶれてしまいました。つぶれた以上は、個人に請求がきますね。でも、個人の給料から引かれている状況の場合は、個人が二重払いすることになってしまうと思うんですけれども、その辺はいかがですか。","respondent":"武内税務課長","answer":"事前に会社が倒産しましたという連絡が入った時点で、その翌月分からは、個人あてに普通徴収ということで切りかえて、ご本人に請求が行きます。その会社が倒産の届けをしていない部分につきましては、あくまでも特別徴収義務者、会社のほうに納税の交渉はするようになります。","id":"exchange-047"},{"speaker":"稲川委員","kind":"質問","question":"５１ページに、滞納繰越分収入見込額ということで、２５％と書いてあるんですが、５億１,９３０万円というのは、比率だけで構わないんですが、特別徴収のパーセンテージと、普通徴収のパーセンテージの比率を教えてください。","respondent":"武内税務課長","answer":"これにつきましては、特に比率というような分類はしていなくて、滞納になりますと、普通徴収も特別徴収も一括しての数字になります。割合的に言えば、私がこういう書類を見ている感じでは、９割５分ぐらい普通徴収と考えていただければよろしいかと思います。","id":"exchange-048"},{"speaker":"稲川委員","kind":"質問","question":"これに関連してなんですが、１３３ページに、特別区税延滞金、５,２００万円と書いてあるんですが、これは、先ほどの答弁の中にも、１カ月滞納して４.５％、それ以上滞納すると１４.６％とおっしゃっていましたけれども、この５,２００万円は、元金というか、何にかかってこの額なのか、教えてください。","respondent":"武内税務課長","answer":"本税に対しましての延滞金です。本税が終わりますと、まだ延滞金を納付できない方は、当然出てくるんですけれども、その延滞金に対する延滞金はありませんので、これは本税に対して延滞金がかかった分を納付していただくような予算です。","id":"exchange-049"},{"speaker":"稲川委員","kind":"意見","question":"本来、払わなければいけないのは、ここに２０億円余、これにかかっているわけではないわけですよね。この算出の仕方が、ただ漠然と５,２００万円と出ているのですけれども、何の数字を根拠にしているのか。例えば、先ほど、元金と言っていましたけれども、私も説明の仕方がわからないんですけれども、トータルで構わないので、幾らの元金に課税されて、５,２００万円というのが出てきたのか。","respondent":"武内税務課長","answer":"これに対して、納税交渉して納付していただいた際に、延滞金が発生します。その納付していただくときの延滞金というのは、もう全然別のことで、今回、５,０００万円ほどの延滞金の徴収を見込んでいるという数字です。","id":"exchange-050"},{"speaker":"稲川委員","kind":"質問","question":"税金は絶対に払わなければいけないものだと、私は思っているんですが、品川区として、具体的に徴収の仕方について、私も１回、質問したと思うんですが、実際にどういう形なのか。差し押さえをして、どんどん収納していくのかどうなのか。やっぱりこれは払うべきものですから、猶予というのはどのぐらいあって、差し押さえする、スケジュール的なものを、簡潔にお答えください。","respondent":"武内税務課長","answer":"そういう中で、本人から、何の連絡もない場合については、財産調査を行いまして、その際、財産を発見すれば、本人あてに再度納付を促しますけれども、それでも本人が納付しない場合については、差し押さえ等を実行するという手続になります。","id":"exchange-051"},{"speaker":"稲川委員","kind":"質問","question":"特別なことがない限り、積極的に徴収をしていただくようにお願いいたします。続いて６９ページになるんですが、さまざまなグラウンドの使用料があります。そこで、ちょっとお伺いしたいんですが、改めて、全体で構わないので、グラウンドの使用率、１日通しての使用率、午前が多いのか、午後が少ないのか、教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"そのほかに、早朝の利用として枠が少ない部分もありますが、５００件程度というところが、平成２１年度の実績です。","id":"exchange-052"},{"speaker":"稲川委員","kind":"意見","question":"いろいろな形で、グラウンドが取れないという話は、ほかの委員からも出ているんですが、例えば、品川南ふ頭公園だったんですが、１年間、毎回申し込みを入れても取れなかったというケースが実際にあるそうなんです。これは、別にこの１件だけではなくて、結構幅広くあると思うんですが、それに対しての対策はありますか。","respondent":"堀越文化スポーツ振興課長","answer":"７月１日より、これまで抽選のエントリーが区民、区外両方一緒にエントリーできたのですが、区民の方だけが抽選に参加できるような仕組みに変える予定です。","id":"exchange-053"},{"speaker":"稲川委員","kind":"質問","question":"８６ページの開発行為手数料についてなんですが、もう時間がないので、これは場所だけ教えてください、どこが多いのか。","respondent":"柏原住宅担当課長","answer":"こちらは…。","id":"exchange-054"},{"speaker":"宮崎委員","kind":"質問","question":"私は９７ページ、１１７ページ、１１８ページ、再開発事業について伺いたいと思います。そこでちょっと何点か聞きたいんですけれども、西口中地区については、私も以前から質問しておりますけれども、分譲から賃貸へどんどん切りかわっているというのが今の実態だと思います。その後、区のほうは、この実態をどういうふうに認識しているのかということを伺いたい。","respondent":"青木都市開発課長","answer":"１点目、分譲住宅から賃貸住宅に変わっているというご指摘ですけれども、これは確認しております。２点目のご質問のお答えと重なってくるんですけれども、参加組合員という事業者が再開発組合から取得した住宅戸数については、８４８戸です。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところを伺いたいと思います。それから、西口中地区の開発については、１８年間計画してきて、今、たまたま景気が悪くなってこうなっているんだとおっしゃっていますけれども、開発計画そのものは、私は賃貸を想定したものではないと思うんですけれども、今の事態を、再開発の計画としてどういうふうに考えるのかということを、改めて伺いたいと思います。","respondent":"青木都市開発課長","answer":"再開発事業としての計画ですけれども、もともと業務主体に考えた副都心計画ですけれども、やはりある時点から、居住機能もないと土日に寂しいまちなってしまうということも踏まえて、住宅主体の街区についても計画変更で住宅供給も図ってきているものですから、昨今。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"この西口南地区のところで、その説明で伺いたいんですけれども、時間を要したのは、一体何が原因で、問題は何なのかということ。現在はどうなっているのか、見通しについても伺いたいと思います。そして、いわゆる隣が西口中地区で、なかなか販売不振ということなんですけれども、当初の計画から変えようとしているのか、どうなのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"今、申し上げましたように、西口南地区につきましては、事業計画を見直して、最終的な権利変換計画に合意を取りつけるために、細かな見直しをやっておりますけれども、基本的に、住宅と業務ビル。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"確認","question":"今、基本的な計画は変えていない、細かいところなんだということですけれども、ちょっと確認しておきたいんですけれども、そうすると、容積率等、あるいは補助金の額、これは、当初の計画のままでいくということでいいのか、どうなのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"補助金については、事業費が変わってまいりますので、その変更された事業認可がされた時点で、それに応じた補助金の額が確定してまいりますので、現段階で幾らとは言えませんけれども、補助金については変わる可能性があるということを、ご報告申し上げます。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"基本的に、今までおおよそ事業費の２割というのが補助金の額でやっていたんですけれども、その枠が変わっていくということはないのか、どうなのか、伺いたい。西口南地区の場合は、どういうところを想定しているのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"ですので、通常から考えますと、委員ご指摘のような、大崎で、４,０００万円ぐらいで取得できるマンションということになりますと、かなり小さめのものになる現実はあるかと考えています。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"今回の西口中地区が、いまだに６割。これが、竣工してから半年も経とうとしているのに、まだ６割台というのは、ほんとうに異常だと思いますね。そうした計画をそのままいくということは、ほんとうに無謀だと言わざるを得ません。一方では、私は大体５％ぐらいがせいぜい適当なのではないかと思うんです。これをやるとどうなるか、どういうところを想定しているのか、伺いたいと思います。この開発全体で。","respondent":"青木都市開発課長、柏原住宅担当課長","answer":"都市開発では、都市活性化拠点、そういう拠点整備においては、職住のバランスを取るという点で、空室率について考慮しているものではございません。民間の空き室を十分活用していこうというのは、区のほうの施策で考えているところです。","id":"exchange-060"},{"speaker":"山内委員","kind":"質問","question":"例えば、手数料の総務手数料の約３３万円の減というのは、住民基本台帳のカード交付が１,０００円から５００円に下がるという、そういういろいろな考え方もあるとは思うんですけれども、例えば８４ページの土木手数料の約６８４万円の減とか、これはちょっと伺いたいんですが、８２ページの衛生手数料が約３,３５５万円の減となっていますが、この辺はちょっと金額が大きいかなと思うんですけれども。","respondent":"金子企画財政課長、太田品川区清掃事務所長","answer":"そういう意味で、先ほど来、ありますとおり、使用料そのものの見直しは、今、そういう段階ではないとは思いますが、これについてはきちっと徴収してまいりたいと考えております。これは、金曜日に補正をお願いしましたとおり、平成２１年度に入りまして、１１月末までの実績で約１億９,４００万円収入済みでございまして、１２月から３月の見込みで１億４,０００万円弱です。","id":"exchange-061"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。ですので、もちろん実績というものも大事だとは思うんですけれども、やはり１円でも多くかせぐんだというような意気込みで、今後も取り組んでいただきたいということを要望いたします。次は、５６ページの自動車取得税のところで、これは大幅なマイナスなんですが、今、エコ減税とよくやっていますよね。あれは関係あるのか、そこを教えてください。","respondent":"金子企画財政課長","answer":"これは、景気低迷で、自動車の売れ行きが落ちている部分と、減税による減収ということもあります。この減税による部分につきましては、５８ページの地方特例交付金のほうで、国のほうから補てんがあるという構造になってあります。","id":"exchange-062"},{"speaker":"山内委員","kind":"質問・要望","question":"１３６ページの競馬組合配分金について、伺いますけれども、配分金の内容を教えてください。馬券の売上に対しての配分金なのか、それとも物販全部含めた配分金なのか、ちょっとその辺を教えていただきたいと思います。","respondent":"伊勢総務課長","answer":"７,４００万円につきましては、大井競馬場で場外発売している分の売上の１００分の１、これは５号交付金といいまして、その部分を計上したものです。","id":"exchange-063"},{"speaker":"山内委員","kind":"質問","question":"大井競馬だけということですか。今、インターネットで買えますよね、その部分は、大井競馬場で開催される競馬に対しての売上の１００分の１ということなんですか。そういうことでいいんですか。","respondent":"伊勢総務課長","answer":"これにつきましては、それぞれ営業にかかる経費と、利益で配分をしていますけれども、７,４００万円につきましては、大井競馬場でほかの場外発売、例えば浦和、船橋、川崎、あるいはもっと遠いところの発売をしている分の１００分の１です。","id":"exchange-064"},{"speaker":"山内委員","kind":"質問","question":"昨今、競馬の馬券の売上が非常に落ち込んでいるということで、昨日、読売新聞に出ていたんですけれども、川崎競馬は、前年比で１％減と、ほぼ前年並みを維持していると。この辺について、設置区であります品川区も、いろいろな意見を言っていくべきだと思うんですけれども、売上に対して、もう少しこうしていきたいというような部分、今後の取り組みを含めて、何かありましたら、教えてください。","respondent":"伊勢総務課長","answer":"売上増につきましては、特別区競馬組合のほうで、広報、あるいは施設の改修、さまざま手を尽くしておりますけれども、また品川区で、こういうふうにやったらいいということがあれば、積極的に競馬組合のほうに申し入れたいと思っています。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"ファミーユ下神明の今の実態について、総合的に、ちょっとバイクの駐車場について、区のご見解を、まず伺っておきたいと思います。今回の予算編成の流れについて、大まかに、ポイントを教えていただきたいと思います。それから、不正経理の問題です。昨年来、さまざまな国の機関、また地方自治体においても、しばしば不正経理の問題が取り上げられておりますので、確認の意味でお聞きしておきます。","respondent":"柏原住宅担当課長、金子企画財政課長、福田会計管理者","answer":"最初に区民住宅等の駐車場の状況です。区民住宅のほうは、今、７団地で駐車場等を設置しております。ご案内のとおりの経済情勢の中、それからまた社会情勢の中で、緊急経済対策、そして、保育園の待機児対策、そして高齢者の生活支援。今、ご質問にありました、預けですとか、いろいろ手口がありますけれども、あれは複数の職員がかかわっている例がかなり多くあるだろうと思っておりまして。","id":"exchange-066"},{"speaker":"若林委員","kind":"質問・要望","question":"バイクの駐車場の問題です。要するに利用実態として、バイクのとめ場所をこれからどういうふうにしていくかということをお聞きしたいと考えています。ただ、そうしますと、発覚した場合の対応も確認をしておきたいと思います。品川区、自治体としては、もし何かあった場合には、こういう罰則がありますとか、そういう意味でも声かけをしていきますとか、そういうお話をいただきたいと思います。","respondent":"柏原住宅担当課長、金子企画財政課長、福田会計管理者","answer":"お話しいただきました西五反田の都営住宅については、場所があいているということはあるかとは思うんですが、管理の問題であるとか、そういったところでは。ただ、品川区としてはこの数字がどういう意味を持つのかという意味合いで、わかりやすい説明はしていきたいと考えております。それからもう一つは、本人から補てんをさせるという形になります。以上の２点が、もしあった場合についての対応だとご理解をいただきたいと思います。","id":"exchange-067"},{"speaker":"若林委員","kind":"確認","question":"確認です。バイクの駐車場の問題、考えなくちゃいけないと、最後にご答弁がありましたが、これは検討するという意味でしょうか、一言確認をしておきます。","respondent":"柏原住宅担当課長","answer":"自治会等、いろいろ管理している部分もありますので、自治会等とも協議をしていかなくてはならないというところで考えております。","id":"exchange-068"},{"speaker":"市川委員","kind":"質問","question":"ユニバーサルデザイン普及啓発委託についてですけれども、普及啓発委託となっているんですけれども、具体的な事業の内容を教えてください。それから、都からの補助金８００万円は、どういったことに活用するのか、その内訳と、それから委託となっていますので、委託先があるのかなと思うので、ここのところを伺いたいと思います。","respondent":"松代都市計画課長","answer":"ユニバーサルデザインのまちづくりプランの策定経費として計上しております。これまでもすべての人にやさしいまちづくり推進計画というものを策定しまして、その推進に向けてさまざまな具体的な方策を検討するために計上した経費です。","id":"exchange-069"},{"speaker":"市川委員","kind":"質問","question":"８００万円、都から補助があるとなっていますが、内訳と、それから委託先を教えてください。","respondent":"松代都市計画課長","answer":"ユニバーサルデザインの普及啓発事業の具体的な検討としまして、おたがいさま運動等を、今、計画しておりますが、それをより具体的に推進していくようなことを、平成２１年度、いろいろとさまざまな方にヒアリングをして。","id":"exchange-070"},{"speaker":"市川委員","kind":"質問・要望","question":"ユニバーサルデザインというのは、多様な優しさが求められるんですけれども、コンサルタントのほうに委託をするということで、ユニバーサルの対象となるすべての人の声を聞く必要があると思うんですけれども、ここのところをどのように進めていこうとされているのか、その辺を伺いたいと思います。","respondent":"松代都市計画課長","answer":"そういった中で、いろいろとご意見を聞きながら進めていくようにしたいと考えているところです。","id":"exchange-071"},{"speaker":"市川委員","kind":"質問・要望","question":"公募の中に入って、自分の意見を言いたいという方もいらっしゃると思いますので、進めていく上では、間接的な意見の聞き方ではなくて、関心のある人が入るための区民公募の枠をぜひ設けていただきたいと思っているんですけれども、これについては、どのような考えでしょうか。","respondent":"松代都市計画課長","answer":"今後も、そういった意味では、これを進めていく上では欠かせないメンバーだと思っていますし、また広くいろいろな機会をとらえて話を聞きながら、この計画、もしくは実際の推進に当たって、かかわっていただきたいと思って我々も接していますし、接していただけると考えています。","id":"exchange-072"},{"speaker":"市川委員","kind":"質問・要望","question":"障害者就労訓練事業について、伺います。この事業の内容について、お知らせください。それから、先ほども説明の中であったと思うんですが、ちょっと聞き逃してしまったんですけれども、昨年の補助金一覧と比べると、都の補助金が２,６００万円ほど減っているんですけれども、この理由は何なのか、教えてください。","respondent":"高橋障害者福祉課長","answer":"それが総額として、６,８００万円余になっております。内容は、以上です。障害者施策推進包括補助金の減額の理由ですが、一番大きいのが、精神障害者のかもめ第一工房が障害者自立支援法の就労継続支援Ｂ型に移ったことによりまして、東京都からの補助金が大幅に減ったものです。","id":"exchange-073"},{"speaker":"市川委員","kind":"質問・要望","question":"生活者ネットワークとしては、この事業は障害者の就労支援ということでは、区が行うとても大切な事業と思っていますので、都の補助金が減っても、区の財源を使って、昨年並の事業運営をしていこうとしていらっしゃるんだろうなと思うんですけれども、その辺はどうなんでしょうかということを、まず１点、お聞きします。それから、これまで、就労支援の対象が知的障害者に限っているわけですよね。","respondent":"高橋障害者福祉課長","answer":"補助金が減ったですが、かもめ第一工房につきましては、法外の施設から法内の施設に移ったもので、障害者自立支援法の中の給付事業になりましたので、補助金そのものが減ったとしても、給付費の中で十分に対応できていると考えております。","id":"exchange-074"},{"speaker":"市川委員","kind":"確認","question":"今の回答で、対象拡大というのは、順次広げていくように、これから検討されていくというような受けとめ方でよろしいでしょうか。ちょっとそこの確認をさせてください。それから、次の質問ですけれども、雑入の放置自転車等保管料について伺います。昨年度は、新たに戸越公園駅と下神明駅の自転車等駐車場整備を行ったわけですけれども、この目的はどこにあったのか、改めて確認したいと思います。","respondent":"高橋障害者福祉課長、諸石交通安全担当課長","answer":"その方の個人的ケースによって対応させていただいているというのが現状で、それを今後も進めします。下神明駅と戸越公園駅の駐輪場の整備、有料化の目的というご質問ですけれども、基本的には、区内の区営の駐輪場につきましては、平成１３年から順次、整備をした後に有料化をしていくということで進めてきております。","id":"exchange-075"},{"speaker":"市川委員","kind":"質問","question":"この収入予算は、どんな根拠で立てたのか、考え方を伺いたいと思います。それから、違法駐輪はやめましょうというような啓発活動については、どう考えているのか、区のお考えを伺いたいと思います。","respondent":"諸石交通安全担当課長","answer":"たまたま昨年度とほぼ同等の額ということで計上しています。それから、２点目の広報、啓発の関係なんですが、ご質問の趣旨を、もう一度確認をさせていただきたいと思います、すみません。","id":"exchange-076"},{"speaker":"市川委員","kind":"質問","question":"区は、放置自転車をなくすという方向性で、自転車対策をとっているんだと思うんですけれども、そういった違法な駐輪はやめましょうという啓発活動もしていく必要はあるかと思うんですけれども、この辺を、区としてはどのように考えているんですかということです。","respondent":"諸石交通安全担当課長","answer":"したがいまして、今後も、放置自転車はやめましょうという啓発の部分も含めた３本柱で推進していきたいと考えています。","id":"exchange-077"},{"speaker":"市川委員","kind":"質問","question":"予算書を見る限り、どんなに駐輪場の整備を進めても、放置自転車というのはなくならないと、区も考えているのかと思えるんです。ちょっとこの辺は、区はどのようにお考えになっているのか、伺いたいと思います。","respondent":"諸石交通安全担当課長","answer":"したがいまして、放置自転車の撤去という部分については、行政の責任で、通行人の危険や迷惑を排除する、あるいは、火事があったときなどに消防車が入れないというような現象面を排除していくというところでは。","id":"exchange-078"},{"speaker":"市川委員","kind":"質問・要望","question":"駐輪場の整備と、撤去対策というところのバランスを取りながら、ぜひ進めていただきたいということを要望しておきます。それから最後に、しながわ水族館運営費収入について、伺います。そういうところから出てきた問題点というのは、どんなふうに、区は把握しているのか、ちょっとその辺をお聞かせいただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"直接、いろいろな形で説明をしたり、コーナーをごらんになる方の反応を見て、それがよければ、翌年もやっていこうということで行っているもので、こうしたことは継続しながら、今後もよりよい企画を行っていきたいと考えています。","id":"exchange-079"},{"speaker":"阿部委員","kind":"質問","question":"私からは、もう午前中からいろいろ出ていますけれども、まず５１ページの特別区民税について、それから、７６ページの土木使用料、そして、１４２ページの区営住宅について、まずはお伺いしたいと思います。どういった実績が上がっているかということを教えてください。品川区も、そこそこ収入のある外国人の方はいらっしゃると思います。計算、考え方について、教えてください。その辺を教えてください。","respondent":"武内税務課長、小野土木管理課長、柏原住宅担当課長","answer":"外国人の方の納税ですけれども、品川区に外国人の方は多く住んでいまして、納税義務者の２％程度が外国人の方ですけれども、督促状等につきましては。そのほかのものについても、減免率をさげておりますけれども、大きいなものについてはいただくという形になりますので、一応、今回の減額をいたしましても。いろいろメリット、デメリットを研究しながら、なるべくたくさんの方に入っていただけるような形での申し込みを、今、研究していますので。","id":"exchange-080"},{"speaker":"阿部委員","kind":"質問","question":"そういった意味では、今、そういった問題を抱えていらっしゃる区民が確実に債権を回収できることは、その区民にとっても、役所にとっても、とてもメリットが大きいと思いますので、時間というか、お尻が決まっている話なので、できるだけ、より強い態度というか、手厚い策をとられたらいいのではないかと思いますが、いま一度、お考えを伺います。","respondent":"柏原住宅担当課長、武内税務課長","answer":"区営住宅の申し込みの件ですけれども、本年７月にまた平成２２年度の募集が開始されますので、そこまでには何らかの形を出したいと考えています。多重債務の過払い金の相談ケースというのが、幸いなことに、品川区の場合は、年間に数件というふうに、私のほうで聞いておりまして、その辺の中で、過払い金の部分、これは専門的なことも非常に要しますので、職員が対応すると。","id":"exchange-081"},{"speaker":"阿部委員","kind":"質問・要望","question":"わかりました。では、進めていっていただけるということなので、よろしくお願いいたします。数件ということなんですけれども、ひょっとすると、掘り起こしがまだできていない部分があるのかなという気もしました。実際に数件なのか、それとも、区の耳になかなか届きにくいのか、きちんと把握するというところから、発見というところから、力を使っていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"大沢委員","kind":"質問・要望","question":"７７ページの武蔵小山創業支援センター、それから３７６ページの予備費について、お伺いします。武蔵小山商店街のパルムをはじめとした商店街が幾つもあります。そこで、お伺いをする１問目なんですけれども、武蔵小山という土地のイメージといいますか、これについて産業振興的な視点、そしてまた土木行政的な視点、言いかえれば、まちづくりの視点と産業振興の視点と二つあると思うんです。","respondent":"福島ものづくり・経営支援課長、青木都市開発課長","answer":"こちらは、ご存じのように、商店街がかなり多くあるということで、今回、私どもで建設しております武蔵小山の創業支援センターも、商業系、あるいはサービス系を中心とした創業支援ということを行ってまいります。そこにちょうど武蔵小山が当たっているということから言いますと、委員のご指摘のとおり、目黒区の方面からもお客様が集まるというポテンシャルがありまして、まちづくりの視点から言いますと、現在は。","id":"exchange-083"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざまなポテンシャルのある場所だということを伺いましたけれども、ここで本論に入りますが、この創業支援センター、１階のチャレンジショップ、この間、３つ募集をしたと思うんですけれども、それの現在までにわかっている状況をお知らせいただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"こちらにつきましては、今、募集をしたところです。現在のところ、３つの店舗につきまして、２７名の応募がございました。","id":"exchange-084"},{"speaker":"大沢委員","kind":"意見","question":"３つの店舗に関して２７名ということで、もう１回すみません、それはどういうふうになっているのかわからないので、説明してください。","respondent":"福島ものづくり・経営支援課長","answer":"失礼いたしました。１階のチャレンジショップですけれども、３店舗あります。この３店舗を募集したところ、２７名の方が、そこに入りたいという形で応募があったです。","id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、まさに創業支援センターの意にあった、個人でこれから何かを始めようとする方が２７名申し込みをされたということでいいでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"法人もいらっしゃいますけれども、個人がほとんどでございました。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"２７名が申し込んで、２７名のうちの３名の方が、ここでこれから活動されるわけですけれども、その場合に、指導、助言に当たる方は、区の商工相談員でしょうか、それとも、中小企業診断士のような方たちが、それに当たるんでしょうか、教えていただきたい。","respondent":"福島ものづくり・経営支援課長","answer":"こちらは武蔵小山創業支援施設そのものを業務委託いたしますので、その委託先のインキュベーションマネージャーが指導するという形になります。","id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"３店舗が決まります。さっき写真を見て、イメージ図ですから、必ずしも当てはまらないと思いますけれども、この３店舗にかなりお客様が来るとなると、往来も激しくなります。上には保育所も入ってまいります。あそこの土地から言って、ちょうど創業支援センターと補助２６号線のあの歩道との動線といいますか、自転車も予想されるでしょうし、そこら辺のスペースは考えていらっしゃるんですか。","respondent":"福島ものづくり・経営支援課長","answer":"確かに、あそこは人通りがあるかと思います。自転車等で来られる方もいらっしゃるかと思うんですけれども、駐輪場は数少ないということもありますので、特に会議室を利用される場合とか、自転車での来所は避けていただきたいと考えています。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"避けていただきたくても、避けられないで来てしまう方はいらっしゃる。その場合は、駅の駐輪場に誘導されるということでしょうか。そこのところでまた、せっかく先ほどのポテンシャルのある武蔵小山ということで、これから脚光を浴びようする場所で、また駐輪場で、出会い頭に事故を起こしたりしたらつまらないと思うので、そこら辺ちょっと教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"私どもの施設そのものにつきましては、駐輪場が１０台以下ということで、かなり少ないものです。ただ、荷さばき用の駐車スペースですとか、そういうこともありますので、その辺も含めて活用し、十分に留意していきたいと思ってあります。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問","question":"活発にこの創業支援センターが運営されますように、ぜひともお願いしたいと思います。最後に予備費について、一言だけお伺いしたいと思います。例年どおり、今年、去年、一昨年と３億円ということで予備費がとってあります。ただ、今後の経済事情をかんがみると、やはり多少なりとも圧縮していく必要があると思うんですけれども、そこのところはどういうふうにお考えになるでしょうか。","respondent":"金子企画財政課長","answer":"そういう意味で、現在の金額が、今のところは妥当かなと思っています。将来にわたっては、また毎年、検討をしていく必要はあると考えております。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"５１ページの特別区民税と、１３８ページの諸収入、弁償金の中の、特に生活保護費弁償金について、お伺いします。それから、平成２０年度の決算を見たときに、生活保護費弁償金については、不納欠損額と生活保護費収納未済額というのがありまして、その枠組みと、この歳入の中の４,０００万円との関係をお尋ねします。決算ですので、平成２０年度の数字を、私は見たんですが。以上、まずお願いします。","respondent":"武内税務課長、平澤生活福祉課長","answer":"平成２１年度の６月当初賦課の状況からご説明しますと、税の場合、課税標準額の段階別層というのを、ある程度細かく取るんですけれども、時間がかかりますので、２００万円以下、２００万円から７００万円以下。私からは、１３９ページ、生活保護費弁償金について、お答えします。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"私も勉強不足でよくわからないんですけれども、そうすると、本来ならば、戻さなければいけないお金というのは、生活保護費は国からが４分の３で、区の一般財源が４分の１ですが、この欠損というのは、区のほうの一般財源なのでしょうか。","respondent":"平澤生活福祉課長","answer":"失礼いたしました。こちらは、全体の弁償金ですので、これは生活保護費全体から返していただくものです。ですので、内訳ということで言いますと、全体の４,０００万円のうち、おおむね４分の１の１,０００万円ぐらいが区費に相当する分です。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、これは私債権になるんだと思うんですが、放棄が出てくると思うんですが、毎年、生活保護費の弁償金請求権放棄、これは毎年、どのぐらい出るんですか。","respondent":"平澤生活福祉課長","answer":"先ほど申し上げましたとおり、平成２０年度決算で申し上げますと、不納欠損が１,９８０万円です。その前年、平成１９年度が１,５８０万円です。","id":"exchange-093"},{"speaker":"高橋委員","kind":"質問・要望","question":"いろいろな厳しい条件の中で生活されている方がいらっしゃるので、なかなか強制的に回収というのは厳しい面があると思うんですが、受給件数が増えれば、結果的にはこういった額も増えていくと思いますので、公平性の点から、本来、返すべきものなんだということを周知徹底させていただきたいんですが、その際に、ケースワーカー等の人員的な配置の問題や、歳出のほうに専門調査員８人とあるんですが。","respondent":"平澤生活福祉課長","answer":"後段の、実際に債権の回収の方法なんですけれども、当然、今いらっしゃる方につきましては、ケースワーカーも含めて、お返しいただくようなお願いをしていますけれども、何分、生活保護の受給者ということになりますので。","id":"exchange-094"},{"speaker":"山路委員","kind":"質問・要望","question":"私からは、７４ページから７９ページの間にあります電柱について、お伺いいたします。７５ページの上から４行目の電柱等の「等」について、説明していただきたい。特に子どもが出入りするような保育園、幼稚園、そして学校等に電柱が何本ぐらい設置されているのか、わかったら、お知らせいただきたいと思います。","respondent":"太田品川区清掃事務所長、吉岡保育課長、田村庶務課長、冨岡高齢者福祉課長","answer":"７５ページの４行目、衛生使用料、土地建物使用料のことだと思いますが、その中で、電柱等というのがあります。今、子どもの施設での電柱の数というお問い合わせでございました。こちらの電柱等の中には、保育課の部分としては、電柱が１４本入っているものです。具体的には、本柱等の設置が浅間台小学校ほか１７校。ですから、合計１８校。電柱設置が第四日野小学校ほか７校ということです。ただ、電柱等のほうで、ヘルパーステーションの使用料が４４０万円ほどありますので、そのほかの電柱につきましては。","id":"exchange-095"},{"speaker":"山路委員","kind":"質問・要望","question":"この辺について、どのように認識をされているか、どのように技術が開発されてきたかについて、教えていただきたいと思います。","respondent":"工藤環境課長","answer":"電磁波の問題につきましては、我が国をはじめとしまして、世界各国で５０年以上に及び、研究成果が蓄積されております。これらの研究の膨大な科学的知見に基づいて、電波の健康影響について調査が行われておりまして、今、電波防護指針というものが、作成されております。","id":"exchange-096"},{"speaker":"山路委員","kind":"確認","question":"雷とトランスとの関係による人体への影響性、それから、例えば街灯なんかに取りつけられたトランスに関しましての安全性の確保というのは、せっかく区民の安全を守るまちづくりを進めていく中で、確保されているかどうかについて、お伺いいたします。","respondent":"藤橋都市整備下水道課長","answer":"万一落雷したときには、被害を最小限にするための設備を中に組み込んであるという工夫がされていると聞いています。それから、柱体に設置した構造物については、確実に引っかけてボルトで固定して落下の防止にも努めているということです。","id":"exchange-097"},{"speaker":"山路委員","kind":"確認","question":"せっかくの安全安心のまちづくりの中で、一部の新聞でときたま載ります、危惧されているといいますか、電磁波と雷との人体への影響について、確認をさせていただきました。より区民の安全をこれからもよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私は、歳入全般のところで、お伺いしたいと思っています。確認したいのが、事業仕分けの目的、民主党のマニフェストでは、むだ使い、不要不急な事業を根絶するとあるんですけれども、この延長保育事業を担当する保育課、それから英語教育改革総合プラン、学力調査を担当する教育委員会指導課の見解を、まずお伺いします。","respondent":"冠木指導課長、吉岡保育課長","answer":"今、委員のお話にございました、英語教育を進めることについて、それから、学力調査について、お話をしたいと思います。お問い合わせのありました延長保育につきましても、区としては、従来も区民の方の就労支援の上で必要不可欠な事業と考えていますので、引き続き、十分な事業実施をしてまいりたいと考えているところです。","id":"exchange-099"},{"speaker":"伊藤委員","kind":"確認","question":"つまり、現場としては、それぞれの事業はむだではないということで、品川区の税金を投入して、その分多くなっていると確認いただいたわけであります。それから、文部科学省関連では、公立学校施設整備事業費９,７１６万円の一部、これはまだ金額は明確ではないのですが、減額する方向が決まっているということであります。これも同じように、防災まちづくり事業部担当課の見解をお伺いいたします。","respondent":"藤橋都市整備下水道課長","answer":"道路整備におきましても、これまでの個別の補助事業については、原則、廃止され、来年度からは社会資本整備総合交付金という形で新しい交付金制度のもとに、いわゆる住宅、それからまちづくり、道路整備、市街地等の整備が一本化された交付金の中で。","id":"exchange-100"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ぜひ区長にお伺いしたいんですが、新政権、政権交代後の初の予算編成がされた感想と、それから、今後予想される国の事業仕分けについて、言いたいことがあると思いますが、ぜひご発言していただきたいのと、ほかのこととの連携について、ご答弁をお願いいたします。","respondent":"濱野区長","answer":"したがいまして、国の仕分けによってカットされた財源等につきましても、必要に応じて区の財政力の中から捻出をして実施をしていきたい。しかし、これはこのままで結構ですということではございません。","id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問・要望","question":"あえて、もう区長に答弁をいただきましたので求めませんけれども、こういう状況下でありますから、ぜひ、現政権の方向性をしっかりと見極めた上で、十分な行財政運営をしていただきますように、強く要望しておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"菊地委員","kind":"質問","question":"私は、１１４ページにあります都の補助金、特別養護老人ホーム整備費補助金について、お聞きしてまいりたいと思います。延べ床面積が７,０００m2の施設ということですけれども、特別養護老人ホームが８１名で、グループホームが１８名、ショートステイの分が１９名という施設ということですけれども、この三つの施設の居室の部分、それぞれのトータルの床面積を、まずお聞かせ願いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"入所された方が、これも概数と思っていただければいいんですが、６９名です。その他、ほかの施設に入られたり、亡くなった方もおいでになって、それが６６名ということで、合わせて１３５名です。","id":"exchange-103"},{"speaker":"菊地委員","kind":"質問","question":"今、八潮の施設、それぞれ居住部分の床面積をお聞きしましたけれども、生活する施設ですから、居室部分だけではなくて、総合的に皆さんがお使いになる空間はいろいろ必要になるわけです。在宅の暮らしが限界に近づいているという方たちが、毎回の申込みごとに増えているわけですよね。命にかかわる、暮らしにかかわる問題ですから、当然のこと、解消していかなければならないと思います。","respondent":"冨岡高齢者福祉課長","answer":"これは、施設と在宅と両方混ぜた数字ですので、前から申し上げておりますように、要介護４、５ぐらいであれば、一、二回ぐらいの調整会議を頑張っていただければ、１年以内には、ある程度お入りになれるというような形で、今までどおり推移をしてきて、今回も。","id":"exchange-104"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、命にかかわる、急を要する問題という認識があるのかどうか、このようにお聞きしましたけれども、今のお答えでは、ほとんどそういう認識はないというふうに思わざるを得ないんです。そこは、もう一度、ぜひお話を願いたいと思います。６９名が入所された。現実には、５３６名が審査をされたということですから、ほんとうにわずかな方が入所可能になったというだけのことですよね。","respondent":"冨岡高齢者福祉課長","answer":"あるいはそれ以外の方についても、個々のケアマネジメントを通じて、特別養護老人ホーム以外にも、どういうところで生活をされたらいいかということで、全体的な介護のマネジメントの中で対応しているということで、特別養護老人ホームだけではなくて、在宅を含め。","id":"exchange-105"},{"speaker":"菊地委員","kind":"質問","question":"もう一つ具体的な事例でお聞きしますけれども、私の知り合いに、特別養護老人ホームに申し込んで２年になる方で、アパートの２階で暮らしている８５歳になるご婦人がいます。ひとり暮らしで、歩行器で動けるんだったら、特別養護老人ホームへの入所なんていうのはとんでもないということになるのでしょうか。多少高い建物というか、これは十分に可能なのではないでしょうか。そこをもう一度、お聞きします。","respondent":"冨岡高齢者福祉課長","answer":"ケアマネジメントの問題性があれば、個々にいつでも対応しますので、それで特別養護老人ホーム以外でなければ生活ができないのかどうか、そういうことも含めてケアマネジメントをするというのが、基本的な考え方です。","id":"exchange-106"},{"speaker":"菊地委員","kind":"意見","question":"高齢者人口比で、特別養護老人ホームのベッド数、１.０％にも満たない整備率ですよね。１.０％にも満たないところは、多分、平成２２年度までベッドをつくれば加算をするという制度になっていますけれども、ほんとうに、少ない整備率なんですよ。やっぱりここをしっかり考えるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"川西委員","kind":"質問","question":"６５ページからの使用料に関して、基本的なところでお伺いをしたいと思います。全面委託して、運営は任せているということなのか、どうかということです。もう一つは、ここは創業関係者のみの保育室ということも説明されたことがありますし、一般の一時保育的なものも対象にするということもご説明いただいたこともありまして、この開設に当たって、どこまで方針ができているのか、伺います。","respondent":"久保田行財政改革担当課長、諸石交通安全担当課長、福島ものづくり・経営支援課長","answer":"指定管理の利用料金制のことですけれども、利用料金制の導入につきましては、指定管理者の自立的な経営や経営努力が見込まれるというような施設については。ただし、駐輪場の使用料につきましては、すべて区の歳入ということでやっております。私からは、７７ページの武蔵小山創業支援センターについてです。","id":"exchange-108"},{"speaker":"川西委員","kind":"質問・要望","question":"減免のことですけれども、それぞれ条例ができていまして、そこで明記されているんですが、その条例をつくる基本の区の考え方は、どこで見たらいいのか、伺います。それから、今の区の施設、いろいろ用途に応じて区民サービスを持っておりますが、減免対象にならない施設というのはどこだか教えていただきたい。","respondent":"久保田行財政改革担当課長","answer":"基本的な考え方ですけれども、各施設の設置条例のところに書いてあります。","id":"exchange-109"},{"speaker":"川西委員","kind":"質問","question":"先にこの件から片づけますが、健康センターは、減額の対象になっていないように思いますが、この辺はいかがでしょうか。","respondent":"山岡健康課長","answer":"確かに、健康センターは、条例では、区長が認める場合という条項がありますけれども、現在のところは、減免対象になっているものはございません。","id":"exchange-110"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、健康センターは、何ゆえにそういうことになっているのか。今、わかっている範囲でお答えいただきたいし、健康センターの使用目的、区民の健康増進のための提供施設としてあるわけですから、そういう点については、区民の健康管理のために提供しようという考え方からすると、入っていないのはなぜでしょうか。ちょっとよくわからないので、１回、伺いたいと思います。","respondent":"山岡健康課長","answer":"特に健康づくりということで絞って貸し出しをしているわけではございませんので、現在のところでは、特にこの団体に優遇するといったようなことは、制度として設けているわけではございません。現在のところは、そういうところです。","id":"exchange-111"},{"speaker":"川西委員","kind":"質問・要望","question":"要望ですけれども、１年がかりで検討し整理していただきまして、来年度予算ぐらいまでには、できたら、これからもずっと減免対象にしないのかどうかも含めて、考え方をまとめていただきたいと強く要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"私は、１３０ページの基金繰入金、それに関連して、国、都支出金全般についての考え方をお聞きしたいと思います。それから、時間があれば、使用料について、若干確認をさせていただきたいと思います。なぜ基金がたまるのかが、よくわからないんです。なるべく今まで培ってきた健全財政を守っていただきたいからこそ、非常に心配している部分がありますので、それをまず確認させていただきたいと思います。","respondent":"金子企画財政課長","answer":"やはり、ここの２年がピークになっておりまして、これ以降若干暫減していきますが、どうしてもこの基金のピークに対応して、ある程度補てんをしていかなければならないという考え方に基づいて、補てんをしているものであります。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"基金がどんどん崩されていって、しかも、どういう事業がどれぐらい廃止されて、品川区としてやらなければいけない事業がどれだけあるものか、非常にこれから真剣に考えていかないと、ほんとうに住民サービスの中で、何に重きを置いてやっていかなければいけないかという決断をしなければいけない年になるのではないかなと思いますが、その動向に対して、品川区の考え方をお聞きしたいと思います。","respondent":"金子企画財政課長","answer":"一方で、当然、区内経済の活性化というものも図らなければなりませんので、これはこれで何らかの財源対策を考えながら実施していくと。こういったことをバランスを取りながら実施していきたいと考えているところです。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"去年、今年の維持で、行政サービスができるかというと、そうでもない。そうなると、区民の皆様には了解をしていただきながら、ここのところは自粛していきますよというのは、今年していくことが必要な時期になるかもしれないと考えていますので、それについてのお考えを、一つお聞きしたいと思います。国、都の政策で、品川区はどれだけやっていかなければいけないのかということを、お聞きしたいと思います。","respondent":"金子企画財政課長","answer":"主に二つのお尋ねかと思います。前段のお話で、あまり仮定の話を、ここできちっと答弁するというのは難しいところがあるとは思いますけれども、そういう意味では、この経済情勢が続いていけば、そういうようなことも想定は可能かなと考えているところです。","id":"exchange-115"},{"speaker":"松澤委員","kind":"確認","question":"歳入のほうの使用料及び手数料、６５ページの１項使用料、区民斎場使用料と、平塚橋会館葬祭利用、それから、８４ページ、手数料のほうの建築確認手数料に関連して、お聞きしたいと思います。６５ページの区民斎場使用料ですけれども、なぎさ会館。何で減っているのかということ、またこの利用率を増やす努力を行っているのかどうか、その辺についてお聞きしたいと思います。","respondent":"梶戸籍住民課長","answer":"なぎさ会館の使用件数です。予算書のほうで３４０件となっているものでございまして、昨年度の予算書は３８０件でございました。これは、あくまでも歳入という形ですので、実態に合わせまして、より近い数字ということで３４０件にしたものです。","id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かに、平成１６年、臨海斎場ができましたから、それで使用が減っているのかと。今、お話がありましたように、少しでも住民の方が利用しやすいように改善をしていきながら、利用率を高めていっていただきたいと要望しておきます。平塚橋会館、葬儀利用１回、これも科目存置なんでしょうけれども、これの葬儀の利用というのが、どれぐらいあるのか、ちょっとお教えいただきたいと思います。","respondent":"中山地域活動課長","answer":"平塚橋会館の葬祭利用の実績ですけれども、平成１７年度に１件があり、平成１８年度以降、今年度まで実績ゼロです。","id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"平塚橋会館は、過去のいきさつから、荏原地域で葬祭場がないのでつくりたいという思いの中で、地元との話し合いの中で骨葬ということで行いました。今年度を入れると５年間、おそらく今年度も使用されないのではないか、５年間も利用されないのだったら、やはりこの辺は考えなくてはいけないのではないかと思いますが、ちょっとどんな意見でしょうか。","respondent":"中山地域活動課長","answer":"ちょっとご質問からはずれるかもしれませんけれども、平塚橋会館の利用そのものは、従前、区民集会所としての利用は低かった部分が、現在、４０％ぐらいまで一定上がっております。ただ、葬祭については、ご説明申し上げたとおり、この４年間ないという状況です。","id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"町会会館でも葬儀ができるんですけれども、これも減っているんですね。もうほとんどの会館、聞くと、年に１回しかないというような話も聞きます。その辺のことは理解しているんでしょうか。ちょっと、その点もお聞きしたいと思います。","respondent":"中山地域活動課長","answer":"したがって、ご質問にあったような葬祭にかかわる情勢に応じた利用は、葬祭補助の中でもきっちりと支援はしていきたいと、区としては考えているところです。","id":"exchange-119"},{"speaker":"松澤委員","kind":"確認","question":"建築確認の手数料、２４５件。午前中にも、原委員のほうから質問がありましたけれども、毎年減っている。直近では、２割程度しか区のほうにきていないというようなお話を伺いました。これは、民間参入したときに、私たちもいろいろ質問しましたけれども、区のほうでも何とか頑張るんだというような決意のほどがよく聞かれたんですが、今現在、どのような気持ちでおられるのかということを聞きたいと思います。","respondent":"片田建築課長","answer":"そんな中で、一定の状況できておりますけれども、区のほうとしてはやはり、いろいろな制度のＰＲをしながら、増やしていきたいと思っています。ただ、現実問題として、なかなか難しいところがありますので、いろいろなＰＲをしていきたいと考えています。","id":"exchange-120"},{"speaker":"松澤委員","kind":"確認","question":"民間のほうが、確認申請が出しやすくて、易しいとか、区のほうが厳しいとか、そのような指摘はないのでしょうか。","respondent":"片田建築課長","answer":"確かに、建築基準法は全国一律の法律ですので、どちらが易しいとか、どちらが厳しいとかいったことがあっては困ることなんです。ただ、現実、私が認識しているのは、民間のほうが、若干解釈が多少ばらけてきているのかなと。","id":"exchange-121"},{"speaker":"松澤委員","kind":"確認","question":"直近の建築紛争の例を、ちょっと出します。マンションを建てる。建築確認申請を出すときに、その私道を利用して、自分たちのマンションを建てたい。要するに、裏に駐車場をつくって、隣の私道を利用して大通りに出たいという確認申請が出ました。それとも、品川区のことですから、しっかりと先に話し合いをしてから確認申請を下ろすという形をとるのか、その辺を聞きたいと思います。","respondent":"片田建築課長","answer":"ただ、区のほうは、やはり区民からの信託を受けているわけですから、いろいろ状況、住民のご意見があれば、きちっと事業者に伝えた中で調整させていただいているというところもありますので、そういうことを、区のほうが厳しいと言われたら。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"私は今回のトラブルを見て、建築確認申請は、やっぱり区が受けなくてはいけないと思ったんです。民間の場合は、先に確認申請を出してしまって、近隣の私道の持ち主と協議をして建てなさいよと。でも、確認申請が下りてしまっていますから、建築主は、私道を利用させろ、建てさせろの一点張りになるわけです。この点、しっかりと区のほうの主導で確認申請が取れるような形で頑張っていただきたいなと思います。","respondent":"片田建築課長","answer":"委員からそういうことをおっしゃっていただくと、大変ありがたいことですけれども、区のほうとしても、適正な審査に心がけていきたいと思いますし、また、その審査が区民にご理解いただけるようなことで考えていきたいと思いますので、よろしくお願いしたいと思います。","id":"exchange-123"},{"speaker":"堺委員","kind":"質問・要望","question":"私からは、７４ページにあります、高齢者等住宅使用料につきまして、時間内で確認をさせていただきたいと思います。７５ページの説明欄には、建設型が１００戸で、４,８２９万７,０００円、そして、借上型が１２３戸で５,６２９万３,０００円、このように計上されてあります。","respondent":"永尾高齢者いきがい課長","answer":"ただし、登録をしてから転居や死亡、施設の入所等がありまして、そういう理由から辞退をされる方が１７人ありますので、登録者で、未入居の方は１９人という状況になっております。","id":"exchange-124"},{"speaker":"堺委員","kind":"確認","question":"入居状況は、わかりました。ちょっと確認をしておきたいのは、借上型の高齢者住宅は、家主と区との契約だろうと思うんですけれども、借上げの期間は、現時点ではどうなっているのか。区民住宅は、たしか区とオーナーで２０年間でしたか、こういう契約だったと思うんですが、高齢者住宅の場合は、借上期間がどうなっているのか、ちょっと参考までに教えていただけますか。","respondent":"永尾高齢者いきがい課長","answer":"借上げの期間ですが、やはり高齢者住宅も２０年を基本としておりますが、７棟あるうちの６棟は、現在、契約期間２０年、１棟については、平成２０年５月にその契約が一度切れておりまして、そのときに家主と話し合いをして、１０年継続の契約をしています。","id":"exchange-125"},{"speaker":"堺委員","kind":"質問","question":"平成２２年度のプレス発表資料等によりますと、今後、ひとり暮らし高齢者や高齢者世帯の増が見込まれる中で、できる限り地域で暮らし続けたいというニーズはさらに強まることが予想される。その辺のところは、どのようになっていくのか、現時点の考え方で結構でありますから、お示しいただけますでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"今までの立ち退き等の対応ということで整備をしてまいりました高齢者住宅の家賃の設定の仕方と、今回の高齢者向け優良賃貸住宅制度を使いました新しいタイプの住宅の制度につきましては、家賃の設定の仕方が違っております。","id":"exchange-126"},{"speaker":"堺委員","kind":"質問","question":"確かに、プレス発表資料等でも、平成２２年度が実施設計、平成２３年度の竣工ですから、使用料等の設定については、これからになっていくのかなと思いますので、今の段階ではなかなか発言しにくいんだろうと思いますけれども、今、お話がございましたような高齢者向け優良賃貸住宅、家賃の助成等も活用して、というご説明を頂戴しましたので、この辺につきましては、既存の高齢者住宅も。","respondent":"冨岡高齢者福祉課長","answer":"具体的には、ではどういうふうにしていったらいいのかですけれども、今までの高齢者住宅とは、建物の制度的な部分も違いますので、独自の設定の仕方ということで、高齢者住宅という面に関して言えば、西大井の原小学校跡の施設の高齢者住宅の部分に近い考え方なのかなと。","id":"exchange-127"},{"speaker":"堺委員","kind":"質問・要望","question":"新たにできる住宅の、いわゆる民間型、いわゆる借上型と呼んでいいんでしょうか、この整備事業者、プレス発表資料では、そのような表現の仕方がありますので、これを使いますと、この整備事業者との間の借上期間が、今後どうなるのか。新たにこの高齢者住宅が設置された段階では、この経費について、どのようにかかってくるのか、参考までに教えていただけますか。","respondent":"冨岡高齢者福祉課長","answer":"区は、高齢者住宅施策で支援をしていきながら、必要に応じて財政的な支援も、というところで対応する予定です。","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"私は、まず、歳入全般についてお聞きしたいのと、９１ページの国庫負担金の中の学校改築推進経費について、お聞きしたいと思います。年度末におきまして、品川区が歳入より歳出が増えた場合、財政上の処理は、どこの予算で調整するのか、まず、教えてください。","respondent":"金子企画財政課長","answer":"もしそういうようなことが発生した場合には、当然のことながら、議会に諮るべきものでありますので、時間のいとまがあれば、臨時会をお願いして、補正予算を組むなど、そういった対応になるかなと考えています。","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"そのときに、補正を組むにしても、予算はどこから持ってくるのでしょうか。","respondent":"金子企画財政課長","answer":"その場合は、さまざまな財源対策が考えられますので、場合によっては基金を取り崩す場合もあるでしょうし、何らかの形での剰余金を当て込むことが処理として可能であれば、そういったこともあり得るかなと考えております。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"今回、歳入の中で、繰越金２４億円と、先ほどもお話がありましたが、予備費３億円というのがあります。先ほど、何か不測の事態に備えて、予備費のほうからお金を持ってくるというようなお話もありましたが、それは間違いないんですか。繰越金というのは、使えないんですか。","respondent":"金子企画財政課長","answer":"予備費は、本来、補正予算で対応すべきところを、ものの本によりますと、金額の少ないものまでいちいち議会に諮る必要がないと認める場合には、予備費を執行するとなっておりまして、例えば、先ほども申しましたが、災害等によりまして緊急に発生したもの等々、予備費自体は。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"すべては見ていませんが、毎年２４億円という金額で計上されております。いわば、最後に最終的に残ったお金を繰越金というふうにするのが、私は筋だと思うんですが、また、金額も２４億円ということがありますが、この辺も、何か法的に、こういうふうにしなきゃいけない、また、金額もこのぐらい出さなきゃいけないということがあるんでしょうか。","respondent":"金子企画財政課長","answer":"そういう意味では、必要があれば、繰越金についていじる場合があるとは思いますけれども、単年度の黒字を目指すとなると、当然、繰越金は年々プラスになっていくという意味で、結果的に、このようなものになっていると考えるべきものだと思います。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"要は、区の事業というのは、赤字を出さないように組んでいく、持っていく。どうしようもなかったら、また、議会に諮って補正等で組んでいく。ならば、繰越金を、あらかじめ当初予算で出しておかなくても差し支えないわけですよ。何でここで出すのか。要は、残ったお金が繰越金ですよね。これは、一般的に、私はそう思うんですが、何かその辺ちょっと理屈が合わないと思うんですが、いかがでしょうか。","respondent":"金子企画財政課長","answer":"予算上の繰越金といいますのは、一番大きな性格的なところでは、前年度からの繰越しをこれだけ見込んでいるということですから、そういう意味では、前年度０円のものを、わざわざ２４億円計上するわけではなくて、繰越しが２４億円と見込まれるので。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"我々は、あくまで繰越金というのは、一般の会社でもそうですけれども、このように当初予算として載せて、そして使えなくなる、固定費みたいになるという感覚は違うのかなと思ったもので、お聞きしました。例えば、教育費負担金は約３億円、教育費補助金は約７億円ぐらい。そうすると、一体国の負担金の割合は何％ぐらいなんですか。ほとんど、各地方自治体でやらなきゃいけないのでしょうか。","respondent":"田村庶務課長","answer":"学校改築に当たっての財政負担ですが、やはり、学校が建設年度がかなり古くて、ほぼ一斉に、時期的にも一緒だということと、学校は、耐震診断の結果も、避難所ですから、やはり手を入れざるを得ないということで、その辺も地域バランスも含めまして。","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"約１割ぐらいだというお話を、今聞きました。でも、何か区民にとっても納得できないのではないかなと。まして１割というのは、私はちょっと論外だと思うんですが、各地方自治体皆さんそうだという話を、今聞きましたが、では、そのかわりに、何か区に対して別途、すみませんがこっちはお金出せませんけれども、こちらのほうで融通しますから勘弁してくださいというようなことはあるんですか。","respondent":"田村庶務課長","answer":"それ以外ということになりますと、義務教育に係る給与負担というので３分の１を国が負担ということになります。","id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"８８ページの国庫負担金について、お尋ねします。国庫負担金はいろいろ出てきますけれども、この数字は、いろいろ事業をやったことを国に申請すれば、そのまま出てくるものでしょうか。それから、すこやか児童手当も、まだ細目はわからないので、繰越明許にしていますと、そんなものはみんなここに載っているんですけれども、このあたりの数字は、どういうふうに考えるんでしょうか。","respondent":"金子企画財政課長","answer":"あまり見込みが低いようなものについては計上しておりませんけれども、基本的には、これまでの形で計上させていただいているものです。","id":"exchange-136"},{"speaker":"須藤委員","kind":"質問","question":"今までの経緯を見て、今回はつくりましたという理解でいいんですか。というのは、先ほど来、政権が変わっていろいろ変わってきていると。ですから、今までの流れが異なる可能性があると思うんですけれども、そのあたりは、それで踏んでいていいのでしょうか。","respondent":"金子企画財政課長","answer":"既存の要綱が適用になっている部分については、当然、そのルールにのっとって計上するというふうになりますし、ないものについては、ある程度情報を、都なりからいただいているものについては、それを計上する、そうでないものは計上しないというような考え方です。","id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"ちょっと細かくなってしまうんですけれども、３分の１とか、割り切れないような数字があるとき、都で３分の１、国で３分の１、区で３分の１というときは、割り切れないときは、どこがどういうふうにするんですか。端数は、区が持つんですかね。","respondent":"金子企画財政課長","answer":"基本的には、大体１,０００円単位で少ないほうに切られて補助金が支給されるというような形が多いものです。","id":"exchange-138"},{"speaker":"須藤委員","kind":"意見","question":"いわゆる都とか、国とかで負担があるのは、そのあたりがきちんと、品川区は品川区で財政的に持っていってもらえればと思うんですけれども、細かいところで、すこやか児童手当、被用者、非被用者、特例給付、特例給付と四つの項目に分かれているんですが、この辺の意味合いがわかりますか。","respondent":"安井子育て支援課長","answer":"特例給付がもう１本あるんですけれども、３歳以上の方について、従来どおり３分の１、３分の１、３分の１というふうに、それぞれ分かれているということで、児童手当制度自体が、もう過去に何度も制度改正が行われたので。","id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"数値がそのときの児童手当が２億４,３１９万６,０００円となっているんですけれども、このあたりは、この３分の１だと、ここに出ている２億４,３１９万６,０００円が３分の１だと７億２,９５８万８,０００円という数字で、この数字になってこないんですけれども、それでさっき、どこか余分のところから取るのかという話なんですけれども、いわゆる出で出た数字と。","respondent":"安井子育て支援課長","answer":"こちらについては、基本的には、歳出のほうは１,０００円切り上げとか、歳入のほうは、逆に１,０００円切り捨てというような形で、若干差がありまして、そこら辺で調整させていただいていることになっているかと思います。","id":"exchange-140"},{"speaker":"須藤委員","kind":"質問","question":"私は逆に、ここのところの数値に児童手当を２億４,３１９万７,０００円としておけば、この数字に合ってくるんですよね。それが大きくなったら、どういうふうに考えるのかと思うんですけれども、いかがでしょうか。","respondent":"金子企画財政課長","answer":"先ほど、子育て支援課長が申し上げたとおり、歳入の基本的な端数処理の考え方は切り捨てであります。歳出のほうの端数処理の基本的な考え方は、切り上げであります。","id":"exchange-141"},{"speaker":"土井委員","kind":"質問","question":"私は、８３ページにあります住民基本台帳カード交付に関連をして一つ、それから、国庫負担金、国庫補助金、都負担金、都補助金にかかわって、ちょっとお聞きしたいことが二つぐらいあります。したがって、住民基本台帳カードは、住民票交付の場合と、身分証明書としての使い方だと思うんですが、それはいかがなのでしょうか。もっと普及させたいということで５００円にするのか。","respondent":"梶戸籍住民課長","answer":"ただいまの住民基本台帳カードについてのお尋ねにつきまして、お答えします。何点かございまして、品川区における住民基本台帳カード交付数という形です。","id":"exchange-142"},{"speaker":"土井委員","kind":"質問・要望","question":"今、お話がありましたけれども、これを５００円にするのは、原価が下がったからだけのように聞こえるので、そうではないのかどうかということをお伺いしているんです。厚生労働省の資料なんかをたまたまもらうと、もっと自由勝手に使えるはずだから、あなたのところでこれは出してもらいなさいなんて、平気でおっしゃる役人がいらっしゃったりするものですから、ちょっとその辺をお伺いしたいと考えています。","respondent":"原情報システム課長、金子企画財政課長","answer":"平成１９年度からイータックスということで、税の電子申請の流れもありますので、今回の５００円といった形の中で、こういったものを普及していただきたいと考えているところです。起債の後年度負担になるということからの考え方ですけれども、ストレートなお答えではないかもしれませんが、起債そのものは一定のルールが決まっておりまして、例えば今回、学校の建設費で起債をしていますが、これは、国庫負担。","id":"exchange-143"},{"speaker":"土井委員","kind":"質問・要望","question":"それで問題は、どこを見たら、その細かいのがわかるんですか。さらに、区民の皆さんが、さまざまな形のものを聞いてこられて、これも補助が出るはずではないかとすがりつくように来られる場合もあるわけですから、そういうときにどう答えるかという意味も含めて、やっぱり知っておかなきゃいけないだろうという意味でお聞きしましたので、よろしくお願いしたい。それから、区債との関係、基金との関係です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"南委員","kind":"質問","question":"保育園の運営費というか、全般に補助金の関係で伺いたいので、ページ数はあちこち飛びますので、言わないで、よろしくお願いいたします。私立保育園の運営に関してなので、そこでいいんですけれども、園運営については、保護者が負担される保育料と、さまざまな補助金で運営していくと思っているんですけれども、そのほかに収入はあるのか、どうか。その辺の区としての見解、どうなのか、ちょっと伺います。","respondent":"吉岡保育課長","answer":"国と都の補助金の総額ですけれども、国庫補助金につきましては９２ページに載ってありますが、６節次世代育成支援対策交付金、５,６７６万円というのが、国庫補助金としての科目は節一つだけですので、これが全体額になろうかと思います。","id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、合計額をちょっと伺ったので、切り分けられないというお話なんですけれども、ぜひとも、園運営の認識も含めて伺いたいので、ぜひそこは示していただきたいと思います。","respondent":"吉岡保育課長","answer":"ところが実際のところ、負担の割合で申しますと、私立保育園分につきましても、区の持ち出しが、おおよそ事業費全体の５４％、国庫の分が２２％、都が１０％ということで、大もとの徴収金基準額によって徴収をした保育料以外の部分の構成が、国２分の１、都４分の１。","id":"exchange-146"},{"speaker":"南委員","kind":"質問","question":"わかりました。私は改めて、私立保育園の位置づけといいますか、品川区の保育行政についての位置づけを、どういうふうにとらえておられるか、それもちょっと伺いたいと思います。そこのところも、ちょっとあわせて伺いたいと思います。","respondent":"吉岡保育課長","answer":"私立保育園の位置づけですけれども、区内の私立保育園１０園について、当然、公立保育園とともに、区内の区民の方々の就労の支援をし、子育てを支援する重要な役割を担っていただいていると考えておりますので、これからも、区立保育園、私立保育園、それぞれの分野におきまして。","id":"exchange-147"},{"speaker":"南委員","kind":"質問","question":"当然なご答弁だと思います。しかしながら、現実的な保育園の運営というのは相当厳しいという状況が、私はあると思って、見ているんです。その辺での考え方というんですか、どういうふうな対策をとってきておられるのか、その辺について、改めて伺いたいと思います。","respondent":"吉岡保育課長","answer":"こちらにつきましては、今、委員からもお話がありましたけれども、１０時間保育の加算ですとか、実は、東京都の補助基準というのがございまして、そちらは非常に細かい項目を、ちょっとうろ覚えですけれども、二十数項目あったと思うんですが。","id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"品川区として独自の補助をしていくという確認でいいんですよね。ちょっとそこを、改めて、後でご答弁いただきたいんです。だから、どこに何が組まれているのかというのを、今申し上げた三つの助成のところで、どういうふうになっているのか、ちょっと教えていただき、そして、きちんと園運営ができるようにということを、改めてその立場でお願いしたいと思います。","respondent":"吉岡保育課長","answer":"繰り返しになりますけれども、園の運営をするのに、基本的にどのぐらいの経費がかかるのかということを、標準的な保育園の経費をもとに算定をいたしまして、その標準的な算定をした経費と国の支弁額との相差について、不足分を補助をするという考え方になってありますので。","id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますと、時間がないのであれですけれども、例えば教材費が、今までは２万円ついていたのが、新年度は１万８,０００円になる。したがって、掛ける子どもの人数ですから、保育園の園運営にとっては、大きな不安材料になってくるんです。こういうことを、やっぱりやめるべきだと思うので、重要だという位置づけであれば、きちんと経営できるように、ぜひ計らっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"武内委員","kind":"質問","question":"私は４点、お願いします。それから、７５ページの高齢者住宅については、先ほど、堺委員のほうからの質問で、幾つかお聞かせいただいたんですが、借上型のほうの更新について、１棟については、大家と話し合って１０年にしたということですが、残りの６棟については、更新するのか、どうか、これを教えてください。これを教えてください。","respondent":"堀越文化スポーツ振興課長、永尾高齢者いきがい課長、柏原住宅担当課長、金子企画財政課長","answer":"昨年ですと、例えば美術工芸室等というような中身で、この予算書の編成上の扱いで中に含めて表記をしていた部分を。そのときの状況で左右されることがかなりたくさんありますので、今のところ、どのぐらいの継続にするのか、やめるのか、その辺については。そうしたところ、まだ１世帯ですけれども、入れたという状況がありますので、平成２２年度、同じような形で。委員、ご指摘のとおり、平成２０年度の補正予算で計上しましたけれども、当初予算で計上したのはここ数年はございませんで。","id":"exchange-151"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった面から言えば、例えば高齢者住宅についても、たしか、これは逆で単身ばかりが多い、夫婦のところも２カ所か、３カ所かあったような気もするんですけれども、そういった面で言えば、今度、更新のときに、例えば考え方として、ひとり暮らしが増えているとはいえ、高齢者夫婦世帯もいらっしゃるのではないかと思いますので、そういう入居の要件緩和というか、要件の拡充というんですか。","respondent":"柏原住宅担当課長、金子企画財政課長","answer":"区営住宅につきましては、先ほどもご答弁申し上げましたとおりに、単身者の枠を広げさせていただいて、今後も募集していきたいです。７月の募集がありますので、そのときにあわせまして、やっていきたいと考えています。そういう意味では、あまり先まで見通してもあれですけれども、長期基本計画、あるいは実施計画のところで、大体４００億円前後まで落ちる見込みの計算はしております。","id":"exchange-152"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった中で、歳出のほうになってしまうのであれなんですけれども、平成２２年度予算のほうで、公共施設、区有施設の跡地活用検討とか、公共施設の有効活用プランといったものを策定するということになっていますので、おそらく、こういった中で、公共施設整備基金の活用だとか、義務教育施設整備基金の活用なんかが、ある程度、数年後まで見通していけるのかなと思うんですが。","respondent":"永尾高齢者いきがい課長、金子企画財政課長","answer":"単身世帯のところに世帯入居も増やしたらどうかというご意見ですが、現在、ひとり暮らしの高齢者がどんどん増えておりまして、そちらのほうの対応も迫っておりますので、今のところは。当然、公共施設の今後の耐用年数が近づいてまいる施設が多うあります。そういう意味では、それも含めて、今後の基金に関しては、きちっした運用の見込みを立てて、運営していきたいと考えています。","id":"exchange-153"},{"speaker":"武内委員","kind":"質問・要望","question":"高齢者のほうにつきましては、今の段階では、継続すらも確定していないわけなので、あれですけれども、ぜひ、そういったこともひとつ検討していただきたいと思います。要望です。それから、基金につきましても、おそらくそういった計画が策定される中で、あらあら使途が明確になってくるんだと思います。","respondent":"金子企画財政課長","answer":"これからの検討になりますので、そういうものについては、できるだけ早くつくってご提供できるようにしたいと考えています。","id":"exchange-154"},{"speaker":"鈴木委員","kind":"質問","question":"先に、区営住宅のほうをお聞きしていきたいと思います。今もお話があったんですけれども、去年の予算書と比べると、やっぱり区営住宅の使用料のところで、５００万円ぐらい使用料が違っていたので、何かと思っていたところで、この前、建設委員会でお話があったと聞いたんですが、使用料基準が変わったと聞いているんですが、そこら辺のところで、この点から先に教えていただけますか。","respondent":"柏原住宅担当課長","answer":"品川区もそういう措置をとったんですけれども、平成２２年度予定どおり、施行令にあわせた形で収入基準を見直していくというところによりまして、家賃が少し上がる部分が出てきた。","id":"exchange-155"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。負担が軽くなるようにやっていくんでしょうけれども、５年、７年という中でのばしていって、トラブルが発生してくると思うのと、基準が下がったことによって退去しなければいけなくなってくる人が出てくることはないのでしょうか。その辺をちょっと教えてください。利用者の応分負担は、どのぐらいを基準に考えて、区のほうとしては算定しているんでしょうか。","respondent":"柏原住宅担当課長、堀越文化スポーツ振興課長","answer":"家賃が若干大きく上がるような方については、指定管理者、我々も付いて、直接お手紙をお持ちしまして、ご説明をさせていただいているところです。今のところ、特に大きなトラブルは聞いてございません。整備についても、多大な費用がかかりますので、いろいろなランニングコストの部分ですとか、近隣の他自治体の使用料等の設定等も考えまして、このような形で使用料を設定しています。","id":"exchange-156"},{"speaker":"鈴木委員","kind":"質問","question":"住宅のほうはわかりました。その辺の作業に遺漏のないように、よろしくお願いしたいと思います。これは私の単純計算ですから、もっといろいろな計算方式をやれば、もっと低いと言われるかもしれないんですが、ここから何を考えたかというと、少年野球の関係を考えたときに、これは歳出になってしまうから、あまりそっちに入りませんけれども、今年、鮫洲運動公園の改修があります。","respondent":"藤橋都市整備下水道課長","answer":"鮫洲運動公園につきましては、来年度に改修工事を行う計画ですので、歳入に当たっては平成２３年度になるかと考えております。","id":"exchange-157"},{"speaker":"鈴木委員","kind":"質問","question":"健全育成という意味を考えたときに、現状では、それこそ地域の方が一生懸命やっていただいて、無料で使っている部分、それを施設が変わっていったときに、どういうふうに考えるのか、その考え方を教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、子供の森公園野球場ですとか、しながわ区民公園の少年野球場も、青少年健全育成という面からも、非常に使用料を低廉に設定して、いただいているというところもありますので、そういった他施設等とのバランスも踏まえながら、十分に考えていきたいと思っています。","id":"exchange-158"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私も、要するに、健全育成という意味のところで、その辺、せっかくやっていただいているところで、負担をなるべく軽くしてほしいという思いがありますので、よく調整をしていただきたいと思います。品川区として、事業の見直しを、今回、影響が出た部分があるのかということが１点。事務事業を見直しする点で、そこら辺をどうとらえていくか、ちょっと時間が短くて申しわけありませんが、お答えください。","respondent":"金子企画財政課長","answer":"そういう意味では、歳出につきましても、先ほど来出ていますとおり、将来をかなり見据えたところで、歳出もそれに見合った形で考えていきたい。一方で、経済対策も実施していきたいと考えています。","id":"exchange-159"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861914?Template=document&Id=930#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":114485,"voices":399}},{"id":"h22-20100309-3","meetingId":"h22-c-budget","date":"2010年3月9日","dateIso":"2010-03-09","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を147件抜き出しています。","topics":[{"id":"topic-01","title":"平成２２年度品川区一般会計予算","agenda":"平成２２年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問","question":"昨年度、平成２１年はかなり大々的に国際交流のことがうたわれていたと思うんですが、平成２２年度、今年の施政方針に、何度か読み返したんですが、国際交流、国際都市というような記載がされていないんですが、そこの中で、区としての国際交流、また国際都市を目指すということをどのようにお考えなのかなということを１点ちょっとお伺いしたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"ご質問の国際交流ですけれども、今まで３都市との国際交流を市民活動ということで推進してまいりましたけれども、今後につきましては、地域の国際交流ということで、昨年度もお示しをしていましたけれども、地域の国際交流のほうを進めていくという形で。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"ということは、これからも先ほど答弁にありました、地道にということなんですけれども、しっかりと前向きにといいますか、さらに進めていくようなお気持ちというのはきっとあると思うんですけれども、そこのあたりのやはり意気込みというのを再度ちょっと確認をさせていただきたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"意気込みですけれども、これまでも続けてまいりました友好・姉妹都市、それから地域の国際化、これに関しては今後とも力を入れていきたいと、基本構想の一つの中に国際化というのも入れてありますので、もちろん進めていくという考えでおります。","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"それと同時に、地域に住んでいる方の区民まつりでの交流なども今活発にされていると思うんですけれども、そこのあたりの今後の展開というのを、この２点をお伺いしたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"地域での国際交流の今後の考え方ですけども、地域と在住外国人の交流の促進ということで、在住外国人と日本人との交流の場面ですとか、地域でのいろんなイベントに外国人の方が参加していただけるような方法で今後進めていきたいというふうに考えております。","id":"exchange-003"},{"speaker":"井桁委員","kind":"質問・要望","question":"参加をしていただくとあったんですけれども、今現在そういった調べというのはなかなか難しいかと思うんですけれども、在住の方にやはり参加を促すＰＲなり声かけなりというのはかなり必要になってくると思うんですが、促すための何か工夫というのを今後お考えであれば、お聞かせいただきたいと考えています。","respondent":"秋山協働・国際担当課長","answer":"例えば区民まつり等で積極的に町会にかかわる例もありますので、町会の方を通じてということもありますし、また参加を促すということで、なかなか外国人の方、それぞれのコミュニティがあるところもありますので。","id":"exchange-004"},{"speaker":"井桁委員","kind":"質問・要望","question":"強く押していくことも必要ですし、あと門戸を開いていくことも必要だと思います。今後ともさらに品川区でもぜひそのコミュニティに飛び込んでいって、地域の皆様との交流に一役買っていただきたいなと考えています。この質問は以上です。次に１６３ページ、ちょっと短くなってしまったんですけど、イメージアップ運動、今年減になっているんですが、これは理由があれば教えていただきたいと考えています。","respondent":"中川原広報広聴課長","answer":"今年度は基本デザインの見直しということで、運動が開始しましてから２０年近くたっておりますので、イメージアップの運動の道具をリニューアルしたということで、その分のお金が減っているところです。","id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"そこで、この計画、いわゆる単純に平成１９年に改正をされて、今、平成２２年、この間、２年間、努力義務ということであって、なぜ今回だったのかな、一日も早くこういうのは策定されたほうがよかったのでないかなという素朴な疑問とともに、これまで品川区がこの配偶者暴力対策に努められた、これまでの対応と、それから今回策定に当たってくださる動機と、そして今後のスケジュール。","respondent":"中山人権啓発課長","answer":"今回この基本計画を策定するに当たりまして、今まで区のほうで対応してきたことを改めまして基本計画ということでまとめていきたいと考えています。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"とてもよくわかりました。そこで、適切な施設においての配偶者暴力相談支援センターの機能を果たすというところでは、先ほどのご説明によりますと、区民相談あるいは子育て支援相談、これまで従前やられていたことを一つの施設という形でされるんでしょうか。それとも、このままの体制で、いわゆる横断的にコーディネーターの方などがいて、相談窓口というふうになるんでしょうか。お答えください。","respondent":"中山人権啓発課長","answer":"そういった流れの中でできるだけこの相談支援センターの機能を果たしていきたいというふうに考えております。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"この相談、暴力を受けたＤＶの考え方として、身体的な暴力が主ですが、精神的なこの暴力というのもあるかと思うんですね。こういった精神的な暴力を受けていらっしゃる方も中にはいらっしゃるので、そういった方のご相談もぜひ受けていただけるような体制をお願いしたいと思うんですが、いかがでしょうか。","respondent":"中山人権啓発課長","answer":"こうした傷ついた心をお持ちの方に誠意を持って相談に乗って、安心して生活を続けられるか、それとも次のステップを踏まれるかといったところを相談に乗っていければというふうに考えております。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"１６６ページにあります企画調整費のところから、区有施設、それから跡地活用の検討経費について、関連して事務事業評価についても少しお聞きをしたいというふうに思います。どのように導き出すのかというのをお聞かせ願いたいんです。区民の皆さんが抱くごく一般的なニーズ、要求がありますよね。これをどうやって行政需要とするのか、その根本的なところをちょっとお聞かせ願いたい。","respondent":"久保田行財政改革担当課長","answer":"私のほうから跡地に関係しましてお答えします。行政需要についてですけれども、私ども昨年策定いたしました品川区長期基本計画というものが当面１０年間の行政計画ということで、私どもが精力的に進めていかなければならないといった行政需要のものだというふうに考えております。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点目でお聞きをしたのは、住民要望というのが行政需要にどういうふうに取り入れられるのかということなんです。ですから、行政需要というもののそもそもの考え方というところをお聞きしたんです。そのときに、当然住民の要望がどういうふうに取り入れられるかということもあるんでしょうけれども、不満を持つということは十分考えられるわけですよね。","respondent":"久保田行財政改革担当課長","answer":"東品川の清掃作業所の活用ですけれども、現時点ではやはり清掃の用途指定というものがかかってありますので、既存施設の中でどういった活用が図れるかということを検討してございまして、今はまずは粗大ごみの中継所として活用していくと。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問・要望","question":"それぞれ個別の施設なり跡地活用に関しては、現状でもいろんな形で区民の皆さんから要望が上がってきているわけです。ですから、単純に長期基本計画の中で、ここの行政需要を定義しているんだということには私はならないんではないかなというふうに思うんですね。区としては、では基本的に行政需要というのは、今充実をしているというふうに考えているんでしょうかね、その辺をお聞かせを願いたいんです。","respondent":"久保田行財政改革担当課長","answer":"ただ、策定後もいろいろな社会情勢の変化等もありますので、この長期基本計画を１本の大きな柱としてそれぞれ柔軟に対応していきたいというふうに考えているところでございまして、例えば特別養護老人ホームにつきましても。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"結局、行政需要は満たしているという最後のお話ですよね。要は住民の持つ本当に命と暮らしにかかわる分野で、現状の声は聞きませんよと言っているのと同じことではないかなというふうに思うんですね、今の答弁というのは。どうやって今現実に挙がっている住民の要望、ニーズというのをとらえるのかというところをもう一度お聞かせ願えますか。","respondent":"久保田行財政改革担当課長","answer":"例えば先ほどもご説明しましたけれども、待機児童の解消につきましても、そういった切実な問題がありますので、私どもとしましては、緊急にやらなければいけないという課題で、平成２２年度緊急課題として取り組むといったものですし、経済対策につきましても。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"区民の暮らしと福祉の増進というのが最大の行政の役割であるわけですから、緊急的な課題としてしっかりと区民の要望に沿って位置づけるということがまず大前提なんではないかと思うんですね。東品川の清掃作業所についても、こうした見地からやっぱりしっかりとどんな活用が必要なのかということを考えていくべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"稲川委員","kind":"質問","question":"１６９ページ、地域コミュニティ活性化助成金について、１７３ページの荏原町安全安心ステーションの運営経費について、１８７ページの初期消火体制強化費の中の街頭消火器格納箱等補修、１９９ページの外国人登録費についてお伺いをいたします。お願いします。","respondent":"中山地域活動課長","answer":"この地域コミュニティ活性化助成金ですけれども、新たに町会の果たす地域コミュニティの活動を一層支援するために本年度から実施した事業です。","id":"exchange-014"},{"speaker":"稲川委員","kind":"質問","question":"規模に応じてということは、町会の規模に応じてという解釈ですね。例えば、防災倉庫を持たない町会・自治会があると思うんですが、この町会の防災倉庫を購入するときの助成制度というのを、今はないと思うんですが、今後検討するお考えがあるかどうか、これは防災課になってしまうか、どっちかわからないんですが、ご答弁をお願いします。","respondent":"中山防災課長","answer":"現在はいわゆる資機材倉庫を建てるための土地を私どもで提供しているです。上物につきましては、町会費で建てていただくというのが原則です。今のところ補助は考えてございません。","id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"続きまして、１７３ページの荏原町安全安心ステーションの運営経費についてお伺いをいたします。先ほどもございまして、竣工予定が３月予定ということでございましたが、うわさによると４月という話もあちらこちらで聞いているんですが、実際にいつ竣工するのか、具体的な日程がわかれば教えてください。それとあと運営体制が今までと変わるのか変わらないのか、その２点、お伺いします。","respondent":"藤橋都市整備下水道課長","answer":"この工事につきましては、東京急行電鉄株式会社と締結した協定に基づき、今東急電鉄が実施しているものでございまして、今後屋根、床、内装の工事を行い、３月３１日までには完了させる予定で現在進めておりますが、天候の影響を受ける作業が続きますので。","id":"exchange-016"},{"speaker":"稲川委員","kind":"質問・要望","question":"私が聞いた話ですけれども、地域の方が本当にこのステーションの運営についてはやりがいを持って取り組んでいるということをよくお伺いします。続きまして、１８７ページの初期消火体制について、消火器の格納箱補修についてお伺いいたします。そして、関連はすると思うんですが、区内に街頭消火器というんですか、何カ所設置しているのか教えてください。","respondent":"中山防災課長","answer":"それが１,１２６万７,０００円ということで、場所につきましては、これはそれが出てきた時点でこれに対応するということで、予測です。大体これぐらい毎年出ているということで予算を計上しているものです。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"今日までで５,７２１カ所ということで、なぜ強調しているのかよく私わからないんですが。５,７２１カ所なんですが、品川区は非常に広いエリアでございまして、実際に具体的に荏原、品川、大井、大崎地域、地域別を見たときに、どの地域に何カ所かという、その詳細がわかれば教えてください。","respondent":"中山防災課長","answer":"これの消火器の設置の根拠ですけれども、昭和４７年度に東京都のほうで要綱ができまして、それに従いまして事業開始年度が昭和４７年、約３５年ぐらい前から設置しているものです。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"今日現在のということで、ありがとうあります。荏原地区が２,０４９本ということで、非常に多い本数が設置されている。次は、貯水槽の維持管理なんですが、品川区内に何カ所ぐらいあるのか。先ほどの消火器も含めて今後、消火器、貯水槽、あとは消火栓ですね、この必要性が非常に私はあると考えているんですが、今後そういった増設のお考えがあるかどうか、お伺いします。","respondent":"中山防災課長","answer":"減っていればそれを補充するということでやってあります。それから、消火栓の増については私どもの範疇ではございませんので、お答えすることができません。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"消火栓は消防署になるのかな。こういった消火器、あと貯水槽がある場所、これは品川区の地域の人たちに周知する必要性があると思うんですが、一つ地図に落として、ここに消火器がありますよといった地図の作成というのはされているかどうか、される思いがあるのか教えてください。","respondent":"中山防災課長","answer":"ただ、今年度防災地図の情報感知システムというものを入れまして、要するに街頭消火器を管理するときの防災地図情報等を住宅地図のデータの利用と合わせましてわかりやすくするということでシステムを入れますので。","id":"exchange-020"},{"speaker":"稲川委員","kind":"意見","question":"その辺、区民全員が共有できるような情報提供をしてください。時間がなくなってしまいましたが、１９９ページの外国人登録費についてなんですが、今度改正入管法ができて、３年以内に施行しなければいけないというところなんですが、品川区としてはどういう形で進めていくのか、お願いします。","respondent":"梶戸籍住民課長","answer":"ただいまのご質問です。品川区としてどのような形ということなんですが、入管法等の改正法の施行日ですけれども、公布後３年以内の政令で定める日ですので、これは全国一斉です。つまり、政令で定める日ですので、最長で……。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"提案","question":"お願いします。そういった中で、この世論調査の調査項目はどのように選定されていくのかが１点聞きたいこと。というのは、いろんな各講座がある、料理教室も体操教室もある中で、いろんな民間も含めてある中で、品川区らしさという中で、品川区の人材にしろ、テーマにしろ、そんな特色を出していってもいいんじゃないかという提案があったので、この辺について何かお考えがあれば教えてください。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長","answer":"ただ、区役所としては、調査は世論調査だけではありませんで、その間にいろんなアンケート調査とか、所管の戸別調査も行っておりますので、世論調査は昭和４９年からこの方法を積み上げまして。文化振興事業団におきましては、しながわアーティスト展等で、品川で活動されている方のご紹介をしているという部分もありますし、メイプルセンターにおきましては、シルバー大学で講師を務めていらっしゃる方。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"確認","question":"これはやはり、その方その方の立場によって感じ方が違うと思いますが、デザインの方針というか、変化、現状に対しての評価をどのようにされているのかを伺いたいのと、やはりインターネットを頼るというか、インターネットの比率が高い世帯が増えている中で、意見交換のやりとりも、メールというものの比重が高い方が増えていると思います。それと文化振興のところはまた改めてお願いします。","respondent":"中川原広報広聴課長","answer":"ただし、この４月にもう一回そういったことも含めてアンケートも繰り返して、障害者の方にもご意見を聞いて、ちょっとトップページはリニューアルをしようかと考えています。ご意見をいただければと思います。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問・要望","question":"私のほうは、１７１ページの八潮南小学校跡区民活動交流施設活用経費、それに伴って１７７ページの八潮多目的広場について質問します。初めに、１８３ページの区民斎場運営費についてお伺いさせていただきたいと思います。昨年の平成２１年度にも同じように載っているわけですけれども、毎年補修工事というんですかね、行われているというのはどういうことなのか教えていただきたいと思います。","respondent":"梶戸籍住民課長","answer":"なぎさ会館のご質問です。そこの中の維持補修費というものは、建物ですので、例えば小破修理、いわゆる壁の壊れたところを直したりとか、そういったものをしています。","id":"exchange-024"},{"speaker":"山元委員","kind":"質問","question":"すみません、その下の維持用消耗品等というのは、細かくて申しわけないんですが、その消耗品というのはどういうことを指しているのか教えていただけますか。","respondent":"梶戸籍住民課長","answer":"消耗品費のほうは、細かく申しますと、例えば紙とか、ペーパーとか、書類作成とか、そういった細々したものです。","id":"exchange-025"},{"speaker":"山元委員","kind":"質問","question":"ご高齢の方が実は手すりがなくて上がりづらいという苦情が私のところにも来ております。確かに壁を伝わって歩いていらっしゃるとか、そういう方がいらっしゃるんですが、その辺は区としてはどのように思っていらっしゃるのか、また何か対策を考えていらっしゃるか教えていただけますか。","respondent":"梶戸籍住民課長","answer":"それ以外の場所につきましても、今後の改修とか日々やっていく中で、区民の声をお聞きしながら改善するものは改善していきたいと、検討してまいりたいと思います。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"一歩間違いますと大変な事故につながるかなと思いますので、その辺もご検討いただきたいと思います。それに伴ってと言っていいのか、実は畳というのは正座をしなければいけなくて、その辺もできればいすのようにはならないのかなと思っているんですが、その辺はいかがでしょうか。","respondent":"梶戸籍住民課長","answer":"ただし、足の悪い方のためには、和室ですけれども、座いす等を購入して置いたりしていますので、そこらのところについては利用者の声を聞きながら、また何らかの対策が、すぐできるものは検討をしてまいりたいと思います。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"気持ちよく帰っていただくためにもいろいろ考えていただきたいと思いますので、どうか要望としてよろしくお願いいたします。１７１ページの八潮南小学校跡の区民活動交流施設活用経費について質問します。今回プレスにも発表されました。","respondent":"堀越文化スポーツ振興課長","answer":"工事に入りますので、その間工事ヤードとして校庭を使わない部分ですとか、そういった施設の改修にかからない部分については、地域の方々に今までどおりスポーツ等にご利用いただくという形で説明をいたしまして、その工事の期間についてもご利用いただくと。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"本当に地元のメンバーは待ちに待って楽しみにしているわけですけれども、実はちょっと気になるのが喫茶コーナーというのがございまして、ここに地域住民団体で運営ということで、何かこれは具体的に何か予定をされているものがあるのでしょうか。","respondent":"秋山協働・国際担当課長","answer":"この喫茶コーナーですけれども、今年度の協働事業提案制度というのを私どもで運用しておりまして、その中で運営をやっていただける団体がいらっしゃらないかということで募集をさせていただいて、公募の団体がございましたので。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"もう一つお聞きしたいんですけれども、この中には地域活動交流室ができるようなんですけれども、それ以外に、例えば八潮以外の地域のメンバーがお借りしたいとかというのは、ちょっと具体的になってしまうんですが、使用するのは可能なのでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"ただ、運営に必要な車両の用意ということと、それから八潮南中学校跡、特別養護老人ホーム側の必要な台数等もありますので、できる限り公共交通機関等をご利用いただきたいというふうに考えてあります。詳細についてはこれから検討します。","id":"exchange-030"},{"speaker":"山元委員","kind":"意見","question":"遠くの方も使えるのかなと思いますと、大変楽しみにしております。平成２３年２月にオープンということで、イベントの予定なんですが、まだ考えていらっしゃらないかもしれないんですが、それでも何かイベント内容というか、何かお考えになっていらっしゃいますか。","respondent":"堀越文化スポーツ振興課長","answer":"地域の方々にご参加いただきながらイベントをやりたいというふうに考えていまして、具体的には、これから検討させていただきたいと考えています。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"八潮には太鼓とか高校生たちのバンドとかがありますので、ぜひ使っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問・要望","question":"１６１ページの町会回覧板用統合ちらしと先ほどもありましたが、１７３ページ、荏原町安全安心ステーション事業でお伺いします。１６１ページの町会回覧板用統合ちらしです。１月区民委員会のほうでも報告がございました。逆にまた、いわゆる回覧板のとじしろの部分と言ったら変なんですが、その辺のご要望もさせていただいたんですが、実際１月にも１回回覧板として回して、２月、３月になりました。","respondent":"中川原広報広聴課長","answer":"１月にモデル実施いたしました統合ちらしですが、地域活動課のほうに町会・自治会のご意見を集約していただきましたところ、まずは秋の区政協力委員会のご要望を速やかに実現したということについて、よかったという、まずはやってくれてありがとうということでした。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"要は、例えば今、区として先導して、このような統合ちらしをつくりますということになりまして、これを機に、例えばいろいろ発行されている発行元にせめて書き方はいろいろあるんでしょうが、用紙のサイズの統一、いわゆる回覧板はこのようなフォーマットでやっていただくと、実は各町会に回る回覧板が読みやすくなるというような呼びかけをぜひしていただきたいと思うんですが、いかがでしょうか。","respondent":"中山地域活動課長","answer":"さらにご質問にはありませんでしたけど、他の官公署、警察、消防等もいろんなものを出して、その結果、非常に多いということがありますので、これはまず庁内からそのようなフォーマットの統合ちらしに合わせて。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"その防犯カメラですとか、警察に直接つながるような電話というんですか、ボタンを押したら電話がかかるとかという仕組みも引き継がれていくのでしょうか。今まで２年余仮設置をしていた中で、このような有効なことが、実はこれがあったことによってこのような有効なことがあったとか、もしくは課題としてこういうことが残ったというようなところがあれば教えていただけますでしょうか。","respondent":"矢部生活安全担当課長","answer":"そうしたことが、やはり地域の活性化にもつながっているんだと私は認識しております。","id":"exchange-035"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは質の違うものだというのは認識しておりますが、例えば、今後品川区内から私の地域にもいわゆる自主防災ですとか自主防犯の意識の強い方々がいらっしゃって、うちの地域にも一つ駅前に交番もないことだし、このような安全安心ステーションを設けたいというような相談があった場合、区としてはどのように対応されていくでしょうか。","respondent":"矢部生活安全担当課長","answer":"新ステーションがほかのところにも設置できるかというご質問だと思います。非常にステーションになりますと、用地の関係、それから維持管理の関係がありますので、なかなかご要望にこたえることはちょっと現時点では難しいというふうに考えております。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問・要望","question":"現時点で難しい、いろんな問題があると思いますが、例えば本当に何か土地があきました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田委員","kind":"質問・要望","question":"私のほうからは１５５ページ、地域と在住外国人との交流促進について、１８５ページ、五反田地区教育総合施設建設について、それと１８７ページ、中学校消火ポンプ配備についてお伺いをします。地域と在住外国人との交流促進なんですが、先ほどもほかの委員からも質問があったので１点だけ、この交流促進の目的と目標がありましたら、お知らせをください。","respondent":"秋山協働・国際担当課長、堀越文化スポーツ振興課長、佐藤防災安全担当課長","answer":"今年度恒例の懇談会ですとか研修会等をやっておりますけども、引き続き来年度も実行していきたいというふうに考えております。このうち管理用の駐車場等もありますので、コインパーキングで今想定しておりますのは８台の部分についてそういう形での運営を今予定しています。それで、訓練日程については、学校側と消防署、または消防団で夏休み中に訓練を実施するように調整しております。","id":"exchange-038"},{"speaker":"石田委員","kind":"質問・要望","question":"地域の人たちの要望もあったので、ぜひその方向で進めていただければと思います。中学校消火ポンプなんですが、例えば今後の展開として全校に配備されたときに、全校対抗で消火ポンプの総合大会などというのも今後の展開としてはおもしろいのかなと思うので、その辺のご検討、もしお考えがあったらお知らせください。これは要望で終わります。何点か質問しましたが、お答えをよろしくお願いします。","respondent":"佐藤防災安全担当課長","answer":"中学校に対しミニポンプを配備していきますが、現時点において全中学校の総合大会ということについては、検討もしていない段階です。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"それで、そもそも論なんですけども、先ほど稲川委員のほうからも出たかと思うんですけれども、町会の件数ですね、これはちょっと違っていたら教えていただきたいんですけれども、１３地区の２０３町会というようなことだったように記憶しているんですけれども、そこのところの数の問題を確認します。","respondent":"中山地域活動課長","answer":"おそらくご質問は、この予算の中に環境整備等助成に２０５町会と書いてある。これは予算の関係上、町会が逆に減る場合もあるんですが、増える場合もある、こういうことで余裕を持っていると、こういうことですので、２０３町会が現在の数です。","id":"exchange-040"},{"speaker":"原委員","kind":"質問・要望","question":"質問が一つ減りました。それで、まずそもそも論からいたしまして、町会と区の関係、逆にもっとストレートに、区にとって町会は何なんだという基本的なというか、位置づけという考えですかね、その辺をお教えいただきたい。そこをお願いいたします。","respondent":"中山地域活動課長","answer":"ただ、もう一点、区政との関係というご質問からしますと、新しい長期基本計画の中でも区民の方との協働というのは大きな柱ですけれども、その中のいわゆる老舗と申しますか。","id":"exchange-041"},{"speaker":"原委員","kind":"質問・要望","question":"ではもう少し細かく入っていきますと、先ほどの一つ質問が減った、ここはわかったんですが、１３地区というここですね、２カ所出てきているんですけど、これは地域という解釈でよろしいんですかね。それで一番上だけが「等」という形がついているものですから、その辺のところをちょっとお教えいただければと思うんですけど。","respondent":"中山地域活動課長","answer":"１３地区、いわゆるコミュニティの一つの区の中のブロックということですが、用語とすれば、１３地区という言い方をしています。","id":"exchange-042"},{"speaker":"原委員","kind":"質問・要望","question":"要するに項目だけの問題なのか、これを逆に言うと、今まである中の分類で、その中に増やしていく可能性があるかというようなことをお教えいただければというのと、それでそれに関連してなんですけれども、いろいろと区のほうではアドバイザーの派遣ですとかをやっていただいているんですけれども、具体的には今まで品川区大分土地が下がったというものの、まだ土地は高いものですから。","respondent":"中山地域活動課長","answer":"最後に、助成期間の扱いも今まで１回助成すると１０年間、次の助成までは利用できないということでしたが、これは修繕等も対応できるように５年に期間を分けていく、この３点を改善するというふうに考えておるものです。","id":"exchange-043"},{"speaker":"原委員","kind":"意見","question":"非常によくわかりました。各地域センターでは、町会長会議とかをやっていらっしゃるというようなことも聞いているんですけれども、その辺のコミュニケーションの関係をちょっとお教えいただければと、どういう状況でとか、現実に則した形の具体的なお話をちょうだいできればと思うんですけど。","respondent":"中山地域活動課長","answer":"各２０３の町会・自治会長は区政協力委員というお顔もお持ちいただいて、区長から委嘱をしているわけですけれども、この方々との区政協力委員会というのは、年に３回あります。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"もっときちんとした対策をとるべきだという思いで質問したいと思います。したがって、この教育の問題について、どういう対策をとろうとしているのか、とっているのか、そのあたりも伺いたいと思います。この間の情勢の発展、核兵器廃絶に向ける情勢がずっと広がっているというここのところの認識というのは、区はどういうふうに持っておられるのか、そこから伺いたいと思います。","respondent":"山岡健康課長、伊勢総務課長","answer":"受動喫煙防止につきましての区における考え方等々は、これからこの通知をもとにどの程度のことを、どの時期までにやるのかという点を含めて検討してまいりたいというふうに思っております。品川区といたしましても、昭和６０年に全会一致で制定いたしました非核平和都市品川宣言を全世界に送りまして、核兵器廃絶と恒久平和確立を訴えておりまして、それ以降も明確に核実験の中止等を訴えており。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"来年度は４７９万円です。５年前には４５４万円、そのあたりからずっと金額的には増えていない。同じような取り組みは島根県でも千葉県でも栃木県でも、全国幾つもの自治体が、もちろん広島、長崎、そして焼津市、こういうところも同様ですけども、ずっとそうやって区民の方々の活動を支援する、そういう立場に立っているんですけれども、品川区はそういう点でどういう事業をやっているんでしょうか。","respondent":"冠木指導課長、荒井生活衛生課長、伊勢総務課長","answer":"小中学校における喫煙防止のための教育ですけれども、すべての小学校で保健の授業であるとか。東京都におきましては、将来的にはすべての飲食店においても全面禁煙を行うべきだとはしておりますが、当面都内の飲食店につきましては。非核平和都市品川宣言事業ですが、品川区は自主的、主体的に判断しまして。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"それから分煙のほうですけれども、確かに今経済状況が悪いので、とりわけ困難な部分はよく私もわかります。しかし、すべての人の健康に関することですので、やっぱり何らかの対策を早急にとるということが経済活動を支えながらも健康を守ると、そこが大事なので、そこは外さないで、ぜひ具体的な検討を進めてもらいたいという要望をしたいと思います。","respondent":"伊勢総務課長","answer":"区民との関係、支援の関係ですけども、平和の運動をやっている方、いろんな考えの方があります。主義主張も違います。","id":"exchange-047"},{"speaker":"南委員","kind":"意見","question":"さまざまな主義主張があるのは当たり前だと思うんですよね。それがあるから支援しないということには、私は公共団体としてはならないというふうに思うんです。核兵器廃絶をさせると、そこの１点でとらえるべきだというふうに思います。ぜひ姿勢を改めるべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"何点かまとめて、１６３ページの区民相談室、来年度より社会保険労務士の協力をいただいた区民相談が行われるというふうに伺っております。特に何ができるのかできないのか、ほかの各資格を持った方との相談もありますので、どういうことが区民の皆さんにとって相談ができるのか、周知の方法についても十分に行っていただきたいという意味でお話を伺いたいと思います。それから、２１１ページの監査委員です。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長、鷹倉監査委員事務局長","answer":"もう一点は、この間全区的な調査をしましたところ、１万２,０００点のサインが設置されていたんですが。シルバー大学ですが、事務事業評価といたしまして内容の見直しですけれども、科目の中で健康の科目を少し増設したりですとか。そういうものが確実になくなっていくことが望まれると、このように事務局としては考えてあります。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"それからイメージアップのほうはわかりました。その中で、６０歳以上の高齢者が対象ですが、例えば６０代の高齢者の方、また７０代の高齢者の方、また男女の比率とか、また男女それぞれのいわゆるシルバー大学の目的に沿った事業に参加をしていく中で、やはりニーズというものが随分と変わってきているんだろうなというふうにお話を伺いながら感じております。","respondent":"中川原広報広聴課長、堀越文化スポーツ振興課長、鷹倉監査委員事務局長","answer":"社会保険労務士相談の周知ですが、広報紙で毎月１日に出しています定例の相談案内、それから区民相談室で発行しております相談室のパンフレット。職員だけでの対応というご質問ですけれども、こちらにつきましては、シルバー大学の企画委員会という形で、学生の皆様によるいろいろな講座の運営。一番大事なのは、縦系列でそれが受け継がれていくこと、それぞれ部局は異動してしまいますので、その当事者がいなくなっても、それが伝わって。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味で、これはどうなんでしょうか。一方では、やはり仲よしクラブ的なところで楽しみに来ていらっしゃる方もいる。そういう意味では、そういったものを総合的にコーディネートして、また区内のさまざまな地域センター、シルバーセンター等場所をとりながら、さまざまな講師を呼ぶという、これに対しての外部的な委託のあり方について一言、検討するかどうかお聞かせいただきたい。","respondent":"堀越文化スポーツ振興課長","answer":"いろんな民間のコーディネートという部分も運営に当たっていろんな部分、さまざまな部分を研究していきながら運営を図っていきたいと、このように考えております。","id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"私から１５９ページのマウントしながわについて伺います。５５９万円を今回予算が計上されていますが、その使途についてお伺いをしたいと思います。それから、里山、品川区が無料でいただいたといういわゆる資産でありますけれども、それについて、やはりさまざまな税金等の問題がかかってくるかと思うんですけれども、この里山についての固定資産税等はどうなっているのか、この辺を伺いたいと思います。","respondent":"中山地域活動課長、工藤環境課長","answer":"今月１８日にもその検討会をやっていくという予定です。私ども環境課のほうでも今年度からマウントしながわ活用事業、地域活動課と共同で事業を実施したものです。","id":"exchange-052"},{"speaker":"山内委員","kind":"質問・要望","question":"やはりいまいちそういうところをもう少し明確にしていくべきではないかというところも踏まえて、少し見直しをしていくことも大事なのかなというところを感じておりますので、今後の自然体験を含めたいろんなさまざまな活用ということであれば、もう少し具体的に何かビジョンを見せていくということが必要なのかなというところをちょっと要望させていただきたいと思います。","respondent":"伊勢危機管理室長","answer":"危機管理対策本部を置く場合ですけれども、たまたま要綱を設置してからちょうど５年目になるんですけれども、一番最初に置いたのが新型インフルエンザの関係でございました。","id":"exchange-053"},{"speaker":"山内委員","kind":"質問","question":"本部というのはどういう形で設置をされて、それが解除されるんですか。例えばこの前の津波のとき、これはあくまでも例なんですけれども、警報から注意報、注意報から解除、解除されたら本部はなくなるのか。本部の考え方。","respondent":"中山防災課長","answer":"日曜日、２月２８日ですけども、津波に関する水防関係の本部は、防災まちづくり事業部が中心となって、水防本部を立ち上げます。この日は午後０時に６０名体制で水防本部、私どものほうで本部を立ち上げて、警報が解除されればそのまま解散となります。","id":"exchange-054"},{"speaker":"山内委員","kind":"質問","question":"はい、わかりました。この前はたまたま津波ということで、品川はゲリラ豪雨等で目黒川と立会川のそういう水害ということも考えられるので、ちょっとその考え方を伺いました。最後になりましたが、非核平和都市品川宣言の事業について伺いますけれども、使節団を派遣している、それから資料コーナーを設けているということでありますけれども、１２月に我が会派で広島市の平和記念資料館に行ってまいりました。","respondent":"伊勢総務課長","answer":"展示コーナーにつきましては、ずっとこのところやっているわけですけども、必要に応じて歴史館にある四百数十枚のパネルだとか、あるいは場合によると過去あまりさかのぼってそこまで把握していないんですけれども。","id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"１５５ページ、職員福利厚生費、決算特別委員会でも伺いましたけれども、役所の食堂の件がどういうふうに改善されたか教えてください。次に１７１ページの青少年育成ですけれども、以前にも伺いましたけど、青少年の対策の地区委員会と、青少年委員の所管はまだ別々になっているのか教えてください。","respondent":"榎本人事課長、中山地域活動課長、堀越文化スポーツ振興課長、梶戸籍住民課長","answer":"実際にはホームページで公募しまして、１５社から応募ありまして、その後実際に現場の説明をした後、６社が辞退しましたので。結婚サポート事業における記念証の実施の背景ということですけれども、まず文字どおりこれは区の結婚サポート事業に参加されて。国民体育大会、平成２５年に品川区も会場の一つとして東京の国民体育大会が開催されますが、その準備に充てているもので、所管につきましては。","id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"食堂の件ですけれども、プロポーザル４社ということですけど、決算のときも伺いましたけれども、味ということを何回も繰り返しはしていただいたと思いますが、４社のプロポーザルのときに担当課長としてちゃんと試食はしたんでしょうかお尋ねします。これが、お免状をもらうということが婚活にサポートになると本当に考えているんでしょうかお伺いします。","respondent":"榎本人事課長、中山地域活動課長、小林青少年育成課長、久保田行財政改革担当課長","answer":"食堂のプロポーザルの件ですけれども、実際には４社残った中で、全部食べ比べるというわけにはいかないので、書類でもってメニューの豊富さを見た後。そういう意味では、地域センターを所管している我々のほうで当面事業をやっていくわけですけれども。地区委員会の位置づけにつきましては、今ご説明のあったところですが、来年度から青少年委員につきましては。それで、オリンピック招致活動の中で、オリンピックムーブメント事業という形でスポーツ教室等を開かせていただきましたけども。","id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"婚活に関しては、決算でどのぐらいの数が出たかというのをまたずっと追っていきたいと思いますので、よろしくお願いします。最後に食堂なんですけれども、今度の食堂は本当に期待していいでしょうか、その辺を最後にお願いします。","respondent":"榎本人事課長","answer":"私が視察してきた関係からいくと、大丈夫だと考えています。","id":"exchange-058"},{"speaker":"阿部委員","kind":"質問","question":"結婚サポート事業、これは私もやっぱりなぜ行政がというのが全然理解できないんですけれども、そこは両目をつぶったとしても、せめて区内業者を使えないだろうかというのが１点と、それからこの記念証というんですか、これはやっぱりサポート事業を使った方のみというよりは、むしろ区民で結婚された方で希望された方がいらしたらフレームは要らないですから。","respondent":"阿部経理課長、中山地域活動課長、久保田行財政改革担当課長、早津選挙管理委員会事務局長","answer":"この下の３段目の維持用消耗品等という中に含まれておりまして、予算額としては４２０万円です。それで、証明書をすべての婚姻の方にというご提案ですけれども、基本的には全体の婚姻をねぎらうとなると。最初の区有施設跡地活用等検討経費ですけれども、こちらは１年間の中で跡地活用を突発的に出てきた場合とか。お尋ねのように翌日開票のほうが経費が安いことは事実ですが、翌日、つまり平日ということになりますと、人材、職員の確保。","id":"exchange-059"},{"speaker":"阿部委員","kind":"質問","question":"車で来られた方には駐車場の、一部かもしれませんけど負担する。今どうしろとは言いませんが、これは少し矛盾がないかなと常々思っております。もしお考えがあれば教えてください。共通プロジェクトのほうですが、地デジのほうは１世帯当たり７,０００円かかるものなんですかね。それから、翌日開票より即日開票のほうがいいという理由は幾つかお伺いしました。うなずいていらっしゃいますし。","respondent":"阿部経理課長、早津選挙管理委員会事務局長","answer":"さまざまな事情で車で来られる方がおります。区役所に来なければ完結しない事務ですので、駐車場のある一定時間の無料というのは当然のことだというふうに思っております。選挙の即日開票は、２３区の一部を除いてはほとんど即日開票でやっているのが実態です。","id":"exchange-060"},{"speaker":"山路委員","kind":"質問・要望","question":"第１点目ですが、航空写真について、防災センターの２階、３階に掲示されまして、私もときたま見させていただいているんですが、またＷＥＢ写真館にもおさめてありまして、非常に時の移り変わりを感じているものですが、この航空写真は、どれぐらいの高さで、どういう形で写真を撮られているのか、まず教えていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"航空写真につきましては、昭和４７年から隔年ごとに撮影をしてまいります。これはお正月の時期に都内から車が少し減った、空気のきれいになった時期を選びまして、ヘリコプターを飛ばしまして撮影しているものです。","id":"exchange-061"},{"speaker":"山路委員","kind":"質問","question":"観光目的もあったかと思うんですが、それを見て非常に私も感動して、新たな文化・歴史の発見がこういう形であるのかなということを感じたんです。私は地域のしか出ませんので、地域のことだけしかわからないんですけど、上空で全体を撮ったら非常に区外へのアピール、あるいは区内の状況とか、にぎやかな新たな品川の魅力が出てくると思いますが、この新しい企画についてどのようにお考えでしょうか。","respondent":"中川原広報広聴課長","answer":"そういった意味では、今民放とかＮＨＫでも空から日本を見る番組とか、ぶらりと行って、「ブラタモリ」というんですかね、ああいう番組で、見なれたところを再発見していくというのは非常にすばらしい手法だと考えています。","id":"exchange-062"},{"speaker":"山路委員","kind":"質問・要望","question":"大変うれしい答弁をいただきました。今回品川区で助成をしていただいて、非常に喜んでいらっしゃる方が多いわけですが、私がここで要望したいことは、助成とともに新たな仕組みとして民間の融資制度、区が利子補給、信用金庫とか、そういう形での支援は考えられないか、これについてお伺いいたします。","respondent":"秋山協働・国際担当課長","answer":"特にＮＰＯに関しましては、私どもが聞いている範囲では、融資というよりも助成制度を活用していきたいということで、なかなか返済の能力ですとか、それから融資をするに当たっての資力の分析ですとか、そういうところがかかわってくるかと思いますので。","id":"exchange-063"},{"speaker":"山路委員","kind":"質問・要望","question":"現状ではそうではないかと私も思っておりました。こういうできる範囲での新しい支援対策も今後必要になってくると思いますので、これは研究していただきたいことを要望しておきます。","respondent":"中山地域活動課長","answer":"平成２２年度が５年に１回の国勢調査ですが、大規模調査といいまして、１０年に一度その調査項目の多い年になりますので、その調査項目が、これは詳しくまだ帳票レベルでは我々も目にしておりませんが、詳しい調査になるというふうに聞いております。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域コミュニティ活性化助成金についてお伺いをいたしますが、地域活動課の資料によりますと、５月に交付予定額の内示、６月から９月の間に助成金の申請、決定と、それと請求という流れで来ております。５月、もう来月、再来月と迫っておりますけれども、この地域コミュニティ助成金について、各町会にどのような周知をされているのかまず聞かせていただきたいと思います。","respondent":"中山地域活動課長","answer":"地域コミュニティ活性化助成は、先ほどもご質問がありましたが、平成２１年度から実施しておりますので、昨年度の段階で新たな事業を開始するということで、最初、品川区町会連合会の総会で連合町会長にご説明した後。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"町会長を通じてということですけれども、地域に実際フィードバックされるのは町会長を通じて、町会の役員会なり総会で発表されるという流れになってこようかと思うんですけれども、やはり町会長に直に説明をされて、町会長から一般区民の方といいますか、町会の役員の方になかなかそれが周知できないということは、こういう制度があるということを知らない方が出てくるおそれもあるんですけれども。","respondent":"中山地域活動課長","answer":"これも基本的には地域センターを通じてご説明しておりますが、場合によっては直接本庁の地域活動課、地域運営係のほうに問い合わせがあり、答えているということもあります。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"先ほど町会長に地域センターを通じてということで、そこの場合、添付資料、地域活動課からいただいた資料と、ならびに交付要綱、そして申請書の１、２、３、４、５、６という書式が１冊になって手元にありますけれども、まさにこのような形で町会長にお配りをし、説明をされているわけでしょうか。","respondent":"中山地域活動課長","answer":"基本的には町会長の会議で要綱、書式を含めてご説明をするというのを基本にしております。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、先ほどの周知の方法ですけれども、これは広報しながわとかそういうのは、すみません、ちょっと私勉強不足でそこのところを承知していなんですけれども、広報しながわあるいは区のホームページ等々を通じても、それは周知をされていたということでいいでしょうか。","respondent":"中山地域活動課長","answer":"基本的に町会への幅広い助成という形になっておりますので、広報紙等一般への広報はしてございません。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"副会長なり、町会長がそのニーズを吸い上げてということで、どうもそこのところには町会長と一般の、何か幾つも事業がありますけれども、それについて事業をやりたい、自分たちが行動を起こしたいというようなところがある方がつながらない場合があるんですけれども、そこのところの対策はどのように立てていらっしゃいますでしょうか。","respondent":"中山地域活動課長","answer":"確かに制度を今年度から立ち上げたという点で言えば、中には町会あるいは役員の中でも詳しく趣旨であるとか実務がわからないという部分があろうかとも思いますので、今のご質問の趣旨を踏まえまして丁寧な説明。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問","question":"あくまでもお金のことですから、きちんとした書類を出してということは重々承知をしておりますけれども、この事業はニーズがあり、終わって検証するという流れの中でもうちょっと書式というか、書類というか、簡素化できるような余地というのはあるんでしょうか。","respondent":"中山地域活動課長","answer":"ただ、じゃあ大もとの申請書そのものがわかりやすいのか、工夫する余地がないのかということについては、きちんとまた声を聞きながら改善できる、簡素化できる部分があれば心がけていきたいというふうに考えております。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"ぜひともこの助成については平成２１年度からでしょうけれども、前年度のを踏まえて検証検討して、より充実した制度になるようにお願いをしたいと思います。では次に移ります。地区委員会のことでお伺いをしたいと思います。ちなみに地区委員の方たち、対象者は子どもたちですから、３６５日と言えば３６５日なんですけれども、実質、地区委員の方たちは、活動を何日ぐらい年間でやるんでしょうか。","respondent":"中山地域活動課長","answer":"単純に言うと、各地区で１０ぐらいの事業、毎月のように何らかの事業をやっている。事業をやるに当たっては事前の打ち合わせがあったり、いろんなまた調整を考えると、かなり毎週のように何らかの役割を果たされているということは、想像できる部分です。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"１２０以上の事業を地区委員の方たちが担われているということを今、ご答弁いただきましたけれども、やはりその活動する中で、１２０以上あるわけですから、その中にはやはり対象になる子どもたちとの活動の中で、いろんな事故があったり、事件があったりするわけでして、そこの事故に対してどのようなセーフティネットというか、地区委員の方たちのお守りとして。","respondent":"中山地域活動課長","answer":"いわゆる地区委員会、地域活動ということでボランティアとしての保険に加入していただくというか、区のほうで委員会活動についてボランティア保険の加入の対象にしているです。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"ボランティア保険ということですが、そのボランティア保険を仮に使う場合に、事故を起こすほうと起こされた方の間の交渉を取り持つような方というのは、どのような方が、行政が入ってやるんでしょうか。それともどのような形で、示談なり事件を処理していくのでしょうか。","respondent":"中山地域活動課長","answer":"地区委員会事業において、具体的に地区委員と対象になる方とのトラブルで行政が間に入ったという事例は、私自身の経験としてはございませんけれども、ただこれはあくまでも区が委嘱をし、お願いしている事業ですので。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"そういう恐怖におびえながらも、あえてご自身の地区委員としての活動を遂行していっているわけですけれども、不安を払拭するために何か区のほうでお考えになっていることがあれば教えてください。","respondent":"中山地域活動課長","answer":"そういう流れの中で今、ご質問があったような、例えば仮に事故があった場合にどういう対処をすべきなのか、あるいは防ぐためにそもそもどうすべきかみたいなこともこれから例えば、そういう新しい方の研修の場面等でも考えていく余地があるのかなというふうに考えております。","id":"exchange-074"},{"speaker":"大沢委員","kind":"提案","question":"それで私一つご提案申し上げたいんですけれども、先ほどもお話をさせていただきました会計処理についてはアドバイザーを派遣するということです。区でも今区民相談等々で法律、いろんな部分でかかわっている方がいらっしゃるのは承知をしておりますけれども、弁護士の活用というのはできないんでしょうか。クレーム対応のために細分化した地域でもいいんですけれども、１人顧問を置くような形をとる。","respondent":"中山地域活動課長、伊勢総務課長","answer":"これは事例に則して、いずれにしても委員のご不安のないような対応はしっかりしていきたいというふうに考えております。訟務員が区にいらっしゃるわけですけれども、訴訟だけではなくて、所管でそういう法律問題、こういうことにつきましては日常から相談に乗っていただいているところです。","id":"exchange-075"},{"speaker":"大沢委員","kind":"意見","question":"うちの区はハンドボールをということで、ハンドボールを担う。ちょっとまとめます。平成２５年に国民体育大会がありますけれども、その間に２年、３年ありますけれども、その中でどういうふうにハンドボールをアピールしていくか、宣伝していくかということは必要だと思うんですけども、そこのところをどういうふうに段取りを立てていくか。","respondent":"堀越文化スポーツ振興課長","answer":"国民体育大会の種目のハンドボールのことですけれども、まずいろいろ東京都と調整がありまして、ハンドボールの種目に内定をいただいているというところでございまして、東京国民体育大会、多摩中心部に開催をする予定です。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひともハンドボールを開催するということで、開催をするからには、何かしらやはりハンドボール、スポーツ協会をはじめ、スポーツにかかわっている方、ないしは数少ないながらもハンドボールをやってプレーしている方たちの協力をもらうわけですので、そこらのところをしっかりと意思の疎通というか、段取りをきちんと立てながら、ハンドボールがいざ開催となったときに。","respondent":"堀越文化スポーツ振興課長","answer":"地域のスポーツ振興、いろいろハンドボールだけに限らず、トップレベルのチームのプレーを見るということは、地域のスポーツ振興にも大いに役立つことだと考えていますので、いろいろなかかわりを持つ方。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも組織作りを区の音頭で行っていただきたい。では最後に、防災関係、防災対策ですけれども、公園があって、防災倉庫があるんですけれども、あれはなぜ公園の平米数によって防災倉庫を置ける置けないという違いがあるんでしょうか、教えてください。","respondent":"中山防災課長","answer":"要するに５m2の資機材倉庫だったのを７m2ぐらいまでは認めようじゃないかということです。","id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"一つ目の職員の方々のやる気、組織の活性化という点ですが、特に職員の方々が区政に取り組んでいただける、大変頑張ってもらいたいんですが、いろんな要素があって、例えば収入の面で頑張れる、あるいは仕事自体が本当に好きでやっていただける、あるいはすばらしい上司にめぐり合えて、その上司とともに仕事していただける、そういったことがあると思うんですが、その中で。","respondent":"榎本人事課長","answer":"それは採用を抑えていた時期がありまして、その関係で新規の受験資格者がなかったということで、かなり少ない時期だったんですけれども、平成２１年度につきましては受験資格者がかなり増えてきまして、それに応じて合格者も増えてきたという状況です。","id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"平成２１年度は１５人のうち人事課７人、総務課３人、税務課１人ということで１１人。そのことについてどうお考えか。逆に見ると、直接総務部の方がそうでないという意味ではありませんが、直接区民の方々と接する機会の多い地域センターの方、あるいは庁内でも福祉の相談や障害者の方の相談をされる、そういった方々からの合格者が少ないことについてどうお考えで、どんな分析をされているのかお願いします。","respondent":"榎本人事課長","answer":"今委員がおっしゃられたのは、事務系の区分という形なんですけれども、例えば保育園の方は福祉系の区分に入っていますので、当然事務系のところでは合格できないという形、それからあと技術職、土木・建築の技術職も別区分で試験をやっていますので。","id":"exchange-080"},{"speaker":"高橋委員","kind":"質問","question":"だから合格と、そういう意味ではなくて、例えばそれ以外の部の方が受験をしようとされて努力されたりとか、もちろん今のお話はちょっと置いといて、総務部の方々に優秀な人材がたくさんいて、そうやって合格する、あるいは区長もそちらのご経歴をお持ちとお聞きしておりますけれども、そういった形で、そういった数を見て今お話を伺えばそういった状況があるんですが、ほかの部署の方がやる気といいますか。","respondent":"榎本人事課長","answer":"そういった意味では、各所属長を通じて受験の通知を出すときについても積極的に受けるようにということで周知を徹底しています。その周知とは別に各所属長の中から優秀な人には個別に声をかけていただくという形で、特にその辺の部分は丁寧にやっているところです。","id":"exchange-081"},{"speaker":"高橋委員","kind":"質問・要望","question":"その話はそこまでで、事務事業評価等の経費についてのお話なんですが、今年度行うということなんですが、まず、すぐに４月から行うのかということと、これまで事業評価をされてきたわけですが、それまで行われてきたのと、手法といいましょうか、観点といいましょうか、さらに基準でしょうか、そういうことの違いはどのように出して、事務事業評価をされていくのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価につきましては、現在最後の詳細な仕組みを検討しているところでございまして、平成２３年、次年度の予算編成に反映させていきたいということで考えておりますので、それに合わせて実施をしていきたいというふうに考えてあります。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"各事業ごとに縦ですね、例えば団子が縦に串に刺さっているように、そういった形の事務事業評価とともに、それを横から刺して、横串の事務事業評価というんですか、そういった形を行っていただければと思うんですが、いかがでしょうか。例えば、シルバー大学や品川文化振興事業団でいろんな講座をやったりしていますが、そういった横串的なことに関してはいかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価を行っていく上では、当然ながら縦の系列だけではなくて、横串といったものも重要なことだと考えていますので、そのような視点で企画部のほうでも考えているところです。","id":"exchange-083"},{"speaker":"市川委員","kind":"質問","question":"私のほうから１５５ページの男女共同参画センターについて、それから１７３ページの近隣セキュリティシステムについて、それから同じページの歩行喫煙防止について、それから１９１ページの地域防災スクール助成金について伺います。まとめて伺っていきます。男女共同参画センターについてなんですけれども、きゅりあんの３階に交流室があるんですけれども、まずこの交流室の目的についてお聞きします。","respondent":"中山人権啓発課長、矢部生活安全担当課長、佐藤防災安全担当課長","answer":"今回改修をさせていただいた目的なんですが、２点ほどあります。今考えているものにつきましては、大井町、五反田、大崎で４人、２組で入っていただきまして、これを週５日。その１点目としては、少なくとも２カ所の小学校区の範囲での事業実施であること。","id":"exchange-084"},{"speaker":"市川委員","kind":"質問","question":"現場ではどんな声が上がっているのかということをちょっとお聞きします。それから、歩行喫煙防止のほうですけれども、この６,０００万円すべてがこの巡回の強化というところにまず使われるのかということをお聞きしたいのと、それから区が目指しているのはどこなのかということを知りたいんです。金額についてもわかりました。そういう申し出を受けたということがあるのかどうか、その辺をお聞かせください。","respondent":"中山人権啓発課長、佐藤防災安全担当課長、矢部生活安全担当課長","answer":"ただ、団体の方たち、いろいろなお声を持っていらっしゃると思いますので、今後もそういった団体の方々とのお話し合いを通じながら。ミニポンプについては、小中学校に配置するという予定ですので、これを契機に、例えば児童引き渡し訓練。これからも喫煙者の方のマナーアップの向上に努めることを目標としたいと考えています。","id":"exchange-085"},{"speaker":"市川委員","kind":"質問・要望","question":"ちょっとここはお考えを伺います。ちょっと唐突な考え方なんですけれども、受益者負担とかというような考え方もあるかと思いますが、このことについて区はどんな見解をお持ちなのかということを伺うのと、それからほかの自治体でこのようなシステムの導入の動きはあるのかということ、ちょっとこの辺をお聞かせください。","respondent":"矢部生活安全担当課長","answer":"映画とかの上映については、またちょっとこれも検討の余地をいただきたいと考えています。現在まではちょっと映画までは今のところはキャンペーンの中には考えておりません。","id":"exchange-086"},{"speaker":"市川委員","kind":"質問・要望","question":"これが本格導入されて６年という年月がたっていますので、このシステムが子どもの育ちの中にどう影響しているかとか、それから子育て家庭への影響とか、あとは地域にどんな影響を与えているのか、こういうことはきちんと検証して今後の進め方の材料にしていただきたいなというふうに思っておりますが、この辺について見解をお願いします。","respondent":"矢部生活安全担当課長","answer":"今後につきましても、そういったところに活用できるとかという場面がありましたら検討していきたいと考えています。","id":"exchange-087"},{"speaker":"伊藤委員","kind":"質問","question":"そういうことを踏まえながら継続することが大切だと私たちも思っているわけでありますが、私も登録させていただいて何年かたつんですが、区から具体的に登録に対する対処の仕方というんでしょうか、こうしてくださいということについて話があったのが２回だけです。そしてしかもここ数年それは行われていないということ。それから、いろんな理由でメールアドレスが変わります。","respondent":"矢部生活安全担当課長","answer":"講習会の話ですけれども、これにつきましては、１月に３Ｇに移行しましたので、１０月から１２月にかけて講習会を実施したいと考えているところです。","id":"exchange-088"},{"speaker":"伊藤委員","kind":"確認","question":"メールアドレスの変更について答弁がなかったので改めてお願いしたいのと、それから当然毎年４月の小学校、中学校の入学のときに、多くの保護者が登録になると思われますね。ですから、確認したいのが、その働きかけ、つまり新しい保護者の方々に対して学校現場でどのようにされているかということをもう一度確認したいと思いますので、ご答弁をお願いします。","respondent":"矢部生活安全担当課長","answer":"失礼しました。答弁漏れがありました。メールアドレスの変更ですけれども、実際電話番号と違って、確かにメールアドレスの変更をされる方というのは多いと承知しております。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"質問","question":"名簿をしっかり管理された上で、例えば年に１回ぐらい再登録のお願いをするとか、もう少し能動的な対処をしてみてはいかがでしょうかということの質問と、それから自分の、要するに子どもが卒業された保護者がいらっしゃいますよね。そういう方々についても引き続き協力員として協力していただけるシステムをつくっていけば、毎年毎年自動的に増えていくわけじゃないですか。","respondent":"矢部生活安全担当課長","answer":"年に１回再登録につきまして、３Ｇに移行した機会ということもありますので、これについては再登録のお願いを一斉にしていきたいと考えております。","id":"exchange-090"},{"speaker":"堺委員","kind":"質問","question":"私のほうからは、１７１ページにあります協働推進経費、それから同じく１７１ページのふれあいサポート推進経費に関連をいたしましてお伺いをします。最初の協働推進経費に関連してです。この辺についてちょっと教えていただけますか。","respondent":"伊勢総務課長","answer":"区も地域の一事業所として社会貢献活動をやってはどうかというようなことで、そういう形で区も参加するような形でこの協議会を今後立ち上げると、こういうような予定にしています。","id":"exchange-091"},{"speaker":"堺委員","kind":"提案","question":"今年度の新たな取り組みについて成果を期待したいところですが、まずその前に、昨年度もこの協働につきましては、区民提案事業が７件、それから区から課題を提起する事業として１件、合計８件、これについて取り組むですが、決算のときにはこの件につきましてどういう成果があったのか、効果があったのかということについて明らかになってくるかと思いますが、現時点でこれらの件について。","respondent":"秋山協働・国際担当課長","answer":"委員ご指摘の協働事業提案制度ですけれども、この制度につきましては、区民の自由な発想や専門性を生かして事業を公募して、区民と区が協働で事業を実施することで基本理念の先ほどもおっしゃられましたけれども、基本構想の基本理念の一つである区と区民の協働で私たちのまち。","id":"exchange-092"},{"speaker":"堺委員","kind":"質問","question":"認知症についても早期受診、早期診断、早期治療は非常に重要であります」。そういう中で、一生懸命こういうことに取り組んで頑張っておられる方について、その労苦にこたえるというんでしょうかね、さっきも広報紙とかホームページで、いろんなところで取り上げていくというお話がございましたが、例えばケーブルテレビでありますとか、いろんなところでこうした人たちをたたえていただければありがたいなと。","respondent":"秋山協働・国際担当課長","answer":"協働事業で多くの事業をやられております西品川三ツ木会さんなどは、町会の会員の方からアンケートをとって、先ほどご紹介があった介護の支援の仕組みですとか、健康と食の安全ですとか、そういうような講座をやっておられますので、この辺。","id":"exchange-093"},{"speaker":"堺委員","kind":"質問・要望","question":"続いてふれあいサポート推進、この件ですが、これにつきましても、時間がなくなっちゃって申しわけありません。今年の２月３日、午後１時半から区役所の第３庁舎６階の講堂でふれあいサポート活動体験発表会というのがございました。こういうことについても、先ほどと同じように広くＰＲをしていただきたいなと思うんですが、出席されたときの感想と今後の対応について、ちょっと教えていただけますか。","respondent":"秋山協働・国際担当課長","answer":"出席させていただいて、それぞれの地区でいろんな活動をされているということを発表いただきました。その中では、聞いていらっしゃる方の感想としては、こういう活動があるんだということを喜んで聞いていただきました。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこで、質問します。この大きな二つの意義、公契約労働者に適正な賃金を、雇用安定を保障するということ、そして２番目として、公共サービスの質を担保すること、公契約条例を定めることの意義、この二つそれぞれについて、区はどのような見解を持っておりますでしょうか。あわせて、自治体レベルで動きが広がっている中、国待ちにせず、区としても条例制定を目指すべきだと思いますが、いかがでしょうか。","respondent":"阿部経理課長","answer":"この総合評価というのは、価格面だけではなくて、施工能力、いわゆる品質の確保をどうやっていくかという面からも評価をしているということですので、必ずしも公契約条例によらなければ確保できないというものではございません。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、野田市の条例制定の意義について、野田市長がこういうことを述べております。実際どうなっているか、調査をしないのにこれは問題ない、そういう実態がないというのはおかしいと思いので、私はそれは指摘したいと思いますが、区長にも聞きたいんですが、どのように区長あてに届いた資料を受けとめたのか、私は野田市長のような姿勢こそ市長としてあるべき姿だと考えますが、いかがでしょうか。","respondent":"阿部経理課長","answer":"先ほど申しましたとおり、私どもとしても、まずはこういう労働法制については国の問題だと、国で解決すべき、全国一律に解決すべきことだというふうに思っておりますので、これが区の見解です。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこの違いというのは、私は野田市の姿勢こそ今求められるべきだというふうに思って、ぜひその立場に立っていただきたいんですね。これは今の状況を打開してほしいという願いが区内の労働者の中にあるということですよ。それについて、こうした品川区としては現状としては公契約条例の制定の必要がある、こうした実態が存在するとお考えなんでしょうか、いかがでしょうか。","respondent":"阿部経理課長","answer":"今委託の金額の件がございましたけれども、もし、例えばの話ですけれども、そういう現場で払われている賃金が国で定められている最低賃金法を下回っているということが明らかになっていれば、それは法律違反ですので、私どもとして委託契約を行っている者に対して。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"何か非常に痛みを自分のものとしていないというか、そういう事例が耳に入ってこないから、何というか、待っているわけでよすね。二つお伺いします。それがあるんじゃないかと言っているわけですから、じゃあないと言うんだったら、調査なしにないということは言えないと思うんですけども、ぜひ調査を求めますけどもいかがでしょうかというのが１点。その点もお伺いします。","respondent":"阿部経理課長","answer":"もう一点、賃金の話ですけれども、先ほど申し上げましたとおり、全国の賃金をどういう法律でやっていくか、これは極めて国の問題ですので、私どもとしてそういう認識です。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"そうしたら改善するんだと、そういう姿勢ですけども、最低賃金を下回らなければ問題ないと考えているのかどうかをもう一回明確に伺いたいと思います。国も今動いていますよね。品川区はこの国の公共サービス基本法を何だと考えているんですか、何かやらないんですか。","respondent":"阿部経理課長","answer":"公共サービスを確保するために、だからこそ先ほど申し上げているような施工能力がどうなのかという面を含めた総合評価を実施しているものです。その結果として最適の業者を選考していて、それで公共サービスを提供しているというふうに考えております。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"それをいい仕事ができるということですよ。そうしてこそ。だから公契約のそこが大事な点だと思うんですが、労働者の、公務労働者の環境の質、労働条件、待遇の改善なしに、私は公共サービスの質の向上はあり得ないと思うんですけども、区のお考えをお伺いします。","respondent":"阿部経理課長","answer":"そういう意味では、十分お支払いをしているというふうに、不当に安い価格をお支払いしているという考えはございませんので、その結果として働いている方も十分満足して働いているというふうに思っています。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ孫請け、下請け、実際に労働者にどういう環境が整っているのかぜひ見て調査していただきたい。公契約条例の制定を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"本間委員","kind":"質問","question":"いつも取り次ぎは翌週月曜日に何でも相談の区民相談室をご紹介するわけですが、最近の相談の件数について、およそで結構ですから、増減はどのようになっているでしょうか。それから、話し合いは１回３０分ということで、特に法律相談、税金相談等はなっておりますが、ほかの区民相談については時間等の制限があるのかどうかについてお尋ねします。","respondent":"中川原広報広聴課長","answer":"スタッフの増員はということで、今の稼働率を見ましても、８０％から９０％でやらせていただいていますので増員の予定はございません。区民相談員の時間ですが、専門相談員ではない、毎日行う区民相談につきましては、基本的には時間の制限はございません。","id":"exchange-102"},{"speaker":"本間委員","kind":"質問・要望","question":"その際に、雇用問題、労働問題、生活福祉、社会福祉協議会等々いろんなところにまたがる部分がありますけれども、その場合にはきちっとしたご指南をしていただくようにお願いしたいと思います。和室の中に入らない。周りの役員さんの要望では、何とかこれを最近の傾向としての新しい時代にマッチしたいす、テーブルを用意できないかということがありますので、この件についてお答え願います。","respondent":"梶戸籍住民課長","answer":"ただし、今後またいろいろなご意見を聞いてまいりまして、今後の改修とかそういったものについては検討材料とさせていただきたいと思います。","id":"exchange-103"},{"speaker":"本間委員","kind":"意見","question":"できる限りのことをやって改善しているということは承知しております。いずれ周辺が大きな立会川の立坑の工事等々が結末を迎える段階に、周辺に目が行くかと思いますが、そのような目配せもしながらひとつ新たな対応をしていただければというふうに思いますのでよろしくお願いします。次に、２０７ページ、統計調査費の部分です。","respondent":"中山地域活動課長","answer":"今回基本的には郵送を基本とするということで、手渡しで説明の上、渡したいということで行っていただくんですけれども、３度ほど訪ねて会えなければ、ポスティングをしてもらって結構である。その後郵送で期日までに出していただきたいです。","id":"exchange-104"},{"speaker":"本間委員","kind":"質問","question":"ほっとしている部分もありますけれども、きちんとした集約の形がとれるのかどうか心配をする部分もあります。いろんな場面があろうかと思いますけれども、今、３度やってだめだったらというお話を聞きましたものですから、その辺は多少心配な点もありますけども、新たな取り組みの部分でご配慮されたと受けとめておきたいと思います。それで、１５９ページの水と緑の市町村との交流事業です。","respondent":"中山地域活動課長","answer":"ただ、非常に心のこもる交流ということで、事業を超えて差し入れがあるとか、これは本当に早川ならではの交流があるというのは、一つここの町との交流の特徴かなと考えています。","id":"exchange-105"},{"speaker":"本間委員","kind":"意見","question":"最近ここ３年目ですが、午前中にも出ておりましたようにマウントしながわ活用事業というのも出てきておりまして、山に登るための道の整備だとか、あるいは仮設のトイレだとかというのも着々と整備はされているという話も聞いておりますし、あの周辺にはオートキャンプ場というのが民間のでありまして、これからシーズンになりますと。","respondent":"中山地域活動課長","answer":"とにかく山の中というのは逆に言えば本当にそこにしかない、本当に雄大な自然の中ですので、いろいろ工夫しながら雄大な自然を多くの人により味わっていただくような工夫はしていきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-106"},{"speaker":"本間委員","kind":"意見","question":"私は先ほど子どもの例を挙げましたけれども、お年寄りですね、高齢者のほうに目を向けてもさまざまな受け皿になり得る素地があるような気がします。そのような意味で、非常に恵まれた環境の、あるいはロケーションのあるところをフルに利用できるような今後の力強い前向きな取り組みについて、これからもよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"１６９ページの地域活動基盤整備についてお尋ねします。区長の施政方針にも地域のいわゆる会館というのは地域にあるのが理想。だが、なかなかできないのでマンションの１室を云々というような話がありますように、その地域に会館がというのは必要だと思うんですが、区がその地域に土地を持っていたりなんかして、そういうことの有効活用みたいなことは場合によっては考えられないでしょうか。","respondent":"中山地域活動課長","answer":"おそらく、例えば町会会館等の要望については、制度充実といってもなかなか土地の部分が一つの課題であるという部分がありますけれども、直接町会会館での利用というのは、今までいろいろご苦労されて確保している町会との関係からいうと難しいかなと考えていますが。","id":"exchange-108"},{"speaker":"須藤委員","kind":"質問","question":"町会活動をやるときに、会館が基盤であるというのはいろんなことがやりやすいので、今担当課長がお話のように地域によってうまく活用できるところがあったら工夫をしてあげていただければと思います。それから１７５ページ、品川区民芸術祭なんですけども、これはどんな内容で、どんなことをやられるのか教えてください。","respondent":"堀越文化スポーツ振興課長","answer":"品川区民芸術祭のお尋ねですが、こちらは中身といたしましては、区にゆかりのある音楽家の方のご協力を得ながらコンサート等を行うということと、それから区のほうで今現在まで行っております区民の皆様のいろいろな音楽ですとかダンスですとか。","id":"exchange-109"},{"speaker":"須藤委員","kind":"質問","question":"聞くところによると、６月にフジコ・ヘミングさんというピアニストがきゅりあんの大ホールで、本来来ないような場所へ来てくれる。秋には日本浪曲協会のメンバーがやっぱりきゅりあんでやったり、武士道などいろいろなイベントがあると思うんだけど、そのあたりはいかがでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"そのほか、さまざま今ご紹介いただいたようなそういった浪曲の部分ですとか、そういったものも幅広く視野に入れて検討を進めていきたいというように考えてあります。","id":"exchange-110"},{"speaker":"須藤委員","kind":"質問・要望","question":"時間がないので最後に、２０１ページの選挙人名簿調製のときの選挙人名簿管理システムというのと、１０３ページの国庫補助委託金で、国民投票投票人名簿システム構築交付金というのは、同じところへ使うのか、名前が何で違っているのか、そこだけ、入りのときの名前と出るときの名前が違うんだけど、国のほうが出すのは目的が何かあってそういう仕組みにしているので。","respondent":"早津選挙管理委員会事務局長","answer":"これは同じものでございまして、国民投票にかかる選挙人名簿ということで、２０１ページのほうは、東京都の補助金制度のタイトルをそのまま持ってきている関係でこのようになっておりますが、内容的には今申し上げたとおり同一のものです。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"やらないわけではないと思うんですが、どうしてでしょうというところをまずお聞きします。しかしながら、１カ月とか２カ月前でしかとれないという形になってしまうと、なかなか計画が立たないということがあるわけですが、２カ月というところ、２カ月以内というところの予約というのはどういうところがあるのか。それが３カ月前からということにはならないだろうかということに対してのお考えをお聞きします。","respondent":"堀越文化スポーツ振興課長、中山防災課長","answer":"それとももう一つ、地域のスポーツ、地域スポーツ推進の事業の中で、体育指導委員会。ただ、自衛隊に関しましては、昨年職員防災訓練のときに練馬の第１普通科連隊の協力を得まして、職員防災訓練は天王洲球場でやったんですけれども。利用者カードですが、スポーツ団体の件でご回答しますと、スポーツ団体の場合には利用団体、いろいろな施設のご利用抽選等の関係もございまして。","id":"exchange-112"},{"speaker":"西本委員","kind":"提案","question":"方針もいろいろ、議員提案の条例もありますし、そういうことも受けますと、やはりすべての区民がという中には、やはり障害者というところのくくりもきちっと位置するべきではないかなというふうに思っております。昼間行けない方たちなんかはそこでつくって再発行ができるんじゃないですかという話です。そこを延ばせないですかという話です。これは、やはりもっと宣伝してほしいです。","respondent":"中山地域活動課長、堀越文化スポーツ振興課長、中山防災課長","answer":"システム上、３か月にできないのかというものは、プログラムを変えればできるかと思います。それが地域スポーツの振興のあり方であるというふうに思っておりますし、そのような考えで進めております。ただ、今年も自衛隊のヘリコプターを飛ばしていただくということになってありますので、連携はさらに深まっているです。","id":"exchange-113"},{"speaker":"武内委員","kind":"提案","question":"個々のそういった要援護者に対しての個別の支援プラン、これを策定してもらいたいと、こういう提案、要望をさせていただいて、これは区長からご答弁いただいて、名簿については登録後数年が経過したので、改めて全体調査の実施を検討と、そういうお答えをいただいて、また個別支援プランの策定についても個別の避難訓練の実施と、また支援プランの策定について検討に入る予定と、平成２１年度にと。","respondent":"中山地域活動課長、中山防災課長","answer":"結婚サポート事業の改めて目的ですけれども、きっかけとしては、少子化対策の中でいろいろ考えたというのがあるんですけれども、改めてみますと、ご夫婦の中で産まれる完結出生児数という数字らしいんですが。地震ハザードマップの件ですけれども、浅野委員にお答えしましたとおり、前向きに検討してまいりますということで、決して後ろ向きになってはございません。","id":"exchange-114"},{"speaker":"武内委員","kind":"質問・要望","question":"要援護者については、今２,９２６名ということですが、昨年の第１回定例会で大体どれぐらいいらっしゃるんでしょうかと質問したら、約１万人ぐらいいらっしゃるというお話だったので、その上で５年経過したので、全体的にやっていくんだというお話をいただいていたので、少し前進したかなと思っていたんですけど、またこれもしっかりお願いしたいと思います。要望します。","respondent":"中山地域活動課長","answer":"現在月２回の相談をやっておりますけれども、先ほどもちょっと申し上げましたように、来年度は月１回の相談のほうに切りかえていくという形で見直していきたいと考えております。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問","question":"私は１８５ページ、応急活動対策費、そして１５３ページ、国際交流事業について、あと１７７ページ、地域センター等管理運営費についてお聞きしたいと思います。例えば年中無休のコンビニ等と共同でやっていくような、そういう心づもりはあるのかないのかお聞かせください。派遣も公式訪問団の受け入れ等も両方ともやっているんですが、これについてご説明ください。","respondent":"山岡健康課長、秋山協働・国際担当課長","answer":"現在までのところは、コンビニの運営会社、特に推進する予定はないということですけれども、何らかの形で我々のほうから働きかけていきたいというふうには考えております。ただし、協会の事業その他について、区は支援をし、助成をしていますし、また公式の訪問団につきましては、区が実施をしています。協会も自主事業というものをやっているところです。","id":"exchange-116"},{"speaker":"須貝委員","kind":"意見","question":"やっているということは、きちんとやっているというのはよくわかるんですね。でも、ほぼ同じような内容でやっていると、例えば区のほうは普及啓発事業費と項目で書いてあるんですが、国際友好協会は、啓発普及事業ということで、何か逆にしているだけで、あと中身というのはほぼ変わらない。なぜそこで分ける必要があるのか、そこをもう一度だけちょっと納得できるように説明してください。","respondent":"秋山協働・国際担当課長","answer":"繰り返しになりますが、車の両輪という形で、区と協会と一緒になって国際交流は進めていくですし、協会は協会で啓発普及事業、その他広報という事業もやっておりますので、そういう形で役割分担はしっかりしているというふうに考えております。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"やっていることはきちんと私はわかります。ですが、やはり区民から見て同じ内容をやって、同じ事業をやって、そしてまして８,６９５万円の補助金を国際友好協会のほうに出していると。それは終わります。続いて、地域センター等管理運営費なんですが、区内にある１３ある地域センターなんですが、区民の相談窓口として活用されているんでしょうか。","respondent":"中山地域活動課長","answer":"相談のですけれども、いろんな数字に出てくる申請等以外に、やはり身近に足が運べる場所ということで、結構手続はどうしたらいいでしょうか、あるいは本庁かもしれないけれども窓口はどうなんでしょうかと、このようなご相談が出ておりますので。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"じゃあそのときに、相談事の入り口という話になるんですね。ですが、地域センターというのは、本来地域の、書いてありますが、コミュニティ活動の核として、地域活動に関する業務のほか、各種の証明書の発行業務をしているのはわかるんですが、私は今多くの方が本当にいろんなさまざまな悩みをお持ちならば、そこの地域センターを地元の人は認識されているんですから、もっと活用すべきじゃないか。","respondent":"中山地域活動課長","answer":"事務分掌とは別に、先ほど申し上げたのは、いろいろお尋ねが身近なところに来ているですので、これはある意味で職員が所管事務以外にもきちんと、適切に案内できるようにというふうなことは日ごろから言っているところですけれども、今ご質問があったような。","id":"exchange-119"},{"speaker":"須貝委員","kind":"意見","question":"今民間ではスーパーがお宅に訪問して、ご自宅に商品を届けるとか、とあるチェーン店では、ビール１本でもお宅に届けるというような仕組みを構築しております。まして銀行や保険会社はご存じのとおり集金に来るわけですよね、きちんとね、お金をお預かりして。そういうことも民間ではやっている。それで、さまざまな人たちがさまざまなやっぱり生活環境、そういうのが変わっています、勤務状況も。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"町会・自治会館建設補助７,０００万円、区長は施政方針の中で、会館取得助成、マンションなどの土地付建物の購入まで拡大いたしまして、上限額を引き上げますというふうに述べておられますけれども、品川区町会・自治会館建設補助金交付要綱の中では、土地は非対象としていますけれども、どのような改定を考えているのか、また、上限、今までですと葬祭が可能な場合は１,５００万円上限。","respondent":"中山地域活動課長","answer":"ただし、逆に言えば２分の１補助ですから、４,０００万円の物件を購入、こういう場合には２,０００万円まで区が助成できますけれども、町会のほうで２,０００万円ご負担いただくと、ご用意いただくと、こういうことになるわけです。","id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"マンションを購入できるということになると、町会会館をつくりたいというところが増えると思います。そんな意味では大変楽しみにしておきたいと思いますけれども、今回この予算額で７,０００万円というふうになっていますけれども、昨年は３,３００万円でしたかね、そうしますと、どこかに２件ぐらい会館をつくるという予定があるんでしょうか、その辺をお聞きしたいと思います。","respondent":"中山地域活動課長","answer":"そのほかに修繕等も含めるという形で、これは具体的な予定が、その件数があるわけではございませんけれども、申請に耐えられるよう予算化したものです。","id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"予算の立て方として、これからたくさん出てきた場合には補正という考え方もあるわけですから、予定がないのに昨年より倍以上予算をつけるというのは、何となく予算の立て方としてはおかしいと思うんですね。まして、景気が悪くて大変だという中で、ここにじゃぶっと３,７００万円余分にあるような気がするんですが、その辺の考え方はいかがでしょうか。","respondent":"中山地域活動課長","answer":"全く予定がないということではございません。","id":"exchange-123"},{"speaker":"松澤委員","kind":"質問・要望","question":"相談を受けているというので、まだまとまっていないからというふうに理解をいたします。次は、地域食事サービスですけれども、１,４７２万６,０００円、この事業内容というのはどうなっているのかお知らせいただきたいと思います。","respondent":"秋山協働・国際担当課長","answer":"地域食事サービスの事業内容ですけれども、これは昼食の配食をボランティアに今、学校給食からお願いしておりますので、それの謝礼であるとか、それから学校給食の材料費であるとか、それから夏期の休業中。","id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"これは区内在住の６５歳以上の外出、調理が困難な高齢者を対象にボランティアの協力および区内業者を活用して、週２回学校給食等を配食するというふうになっていますけれども、これの対象人数というのは６５歳以上の外出、調理が困難な方、高齢者、どれくらいいるんでしょうか。","respondent":"秋山協働・国際担当課長","answer":"それに該当する方の総数というのは、ちょっと私どもでは把握はしてございません。","id":"exchange-125"},{"speaker":"松澤委員","kind":"質問・要望","question":"私が聞きたかったのは、６５歳以上の外出、調理が困難な高齢者、これが品川区でどれぐらいいるんだろうか。相当数いると思うんですよ。それで、実際にここで対象としているのが２００人ちょっとですよね。あるいは、その中で希望者だけだからこんな数になっているんだろうか、その辺、ちょっとしっかりとお答えいただきたいと思います。","respondent":"秋山協働・国際担当課長","answer":"配食につきましては、高齢者福祉課等で在宅介護支援センターを経由して行っているサービスもあります。それから、民間のサービスもありますので、私どもの地域食事サービスだけということではなくて、全体の中でサービスが行われているというふうに考えてあります。","id":"exchange-126"},{"speaker":"松澤委員","kind":"質問","question":"防災対策費のほうですけれども、６,８５４万８,０００円、これだけの金額ですけれども、これは新たに購入するのと、廃棄になってまた購入するのもあると、両方だろうと思いますけど、これはどのような被害想定で行っているのか、年次改革をやっていると思うんですが、いつごろに備蓄が完了するんでしょうか。それを聞きたいと思います。","respondent":"中山防災課長","answer":"総計しますと６,８００万円以上になるです。","id":"exchange-127"},{"speaker":"川西委員","kind":"質問","question":"３点伺います。一つは、食堂の変更の件、もう一つは、今までも質問がありましたが、１７３ページ、歩行喫煙防止に関連して、それからもう一つ質問したいのは、自転車のことについては、安全安心でよろしいんでしょうか。そんなことです。あるいは、山北町や早川町と交流しているのだから、季節によってはその交流先からの野菜を仕入れることについてはどうかとか、そういう質問が入っていたかどうか。","respondent":"榎本人事課長、矢部生活安全担当課長、冠木指導課長、諸石交通安全担当課長","answer":"生活習慣病、メタボリック対策、もしくは個別栄養相談、セミナーの実施ができるかどうかとか。ただ、ほかの指定区域以外の駅につきましては、現在検討中なんですけれども。自転車の乗り方についての指導ですけれども、すべての小学校で区内の４警察のご協力をいただきまして、自転車の乗り方の指導の授業をしています。指導課長のほうからお話がありましたとおり、区では年に４回今年度からスタントマンを活用した自転車の安全教育を始めました。","id":"exchange-128"},{"speaker":"川西委員","kind":"質問・要望","question":"一つは自転車の研修教育のことですけれども、事故の多いのが比較的パートに出ている女性、多いです。この人たち、こういう年齢の方を対象に研修をしていただくことを今後考えていただきたいと思います。入り口に喫煙所を設ける、そういうような予算を使っていただきたいというふうに思います。マナーというのは、やはりいろんな方に守っていただく、そして研修していただくということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは１７５ページの品川区民芸術祭経費と品川文化振興事業団助成金について、品川区と区民１人ひとりの芸術活動の関係についてを中心に伺いたいと思います。芸術祭が開催されるわけですけれども、区民一人ひとりの芸術活動における品川区といいますか、行政の役割をどう考えているのか、今回の芸術祭にどうそれが反映するのか、ご説明いただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"先ほどのご質問にございましたように、コンサート事業のほか、区民の皆様が参加されるいろいろな活動、そのような形も一体的に運営をしまして、そのようなにぎわいづくりという観点で進めていきたいというように考えているところです。","id":"exchange-130"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中に既に活動している人だけではなくて、文化や芸術やスポーツに参加の意欲はありながらも、心身の健康状況、家庭や仕事の事情などさまざまな制約があって活動できない人も、参加できるような仕組みづくり、楽しさ、生きがいを感じられるような仕組みづくりが重要だと、そういう答申がされたわけですけれども、ここで言っているさまざまな事情があって活動ができない人というのは。","respondent":"堀越文化スポーツ振興課長","answer":"そのようななかなか参加できない、今まで活動されていない方についても観賞していただけるような、そしてまたそれを参加につなげるような、そういった機会を広げていくような、そういう考え方で芸術祭を進めていきたいと、このように考えているところです。","id":"exchange-131"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日の議論の中で、７月１日ですか、区民の優待の話が出ておりましたけども、所得の少ない人や障害者や日ごろ生活で忙しい方にどう参加を保障していくのか、権利としての文化芸術・スポーツをどう保障していくのか、その具体的な位置づけをご説明いただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"区民に開かれた文化芸術の振興という観点で私ども考えておりまして、皆様のこのようなさまざまな活動、今回の芸術祭の部分でいきますと、区民の皆様のいろんな活動の発表の場というのも設けておりますので。","id":"exchange-132"},{"speaker":"中塚委員","kind":"質問・要望","question":"計画しているコンサート、クラシックやポピュラーやジャズ、いろいろプレス発表にもありましたけれども、料金設定というのはどういう形になっているのでしょうか。気軽にとおっしゃるんであれば、所得が少ない人も、また障害を持っていてなかなかそういう場に聞いたり参加したりする機会がない方々をどう位置づけられているのか、その具体的な中身が見えないので、ぜひそこは説明していただきたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"そういった中で、皆様に愛されるような芸術祭としてのにぎわいの創造につなげるようなさまざまな事業を取り入れた形で進めていきたいというふうに考えているところです。","id":"exchange-133"},{"speaker":"中塚委員","kind":"質問・要望","question":"コンサートだけでなく、練習場所やまた発表場所や、そういうところもしっかりやる必要があると思います。指定管理者の更新も近づいていると伺っているんですけれども、現在文化振興事業団が行っている事業について、今後どのような事業を求めていくのかご説明いただけますでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"今後とも文化振興事業団のほうでいろいろな財団の目的であります区民の文化的な要望にこたえると、そして文化の振興を通してゆとりと潤いのある地域社会づくり、これが財団の設立の目的ですので、これに寄与するようにいろんな事業に努めていただく。","id":"exchange-134"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、「三味線に合わせて唄う」というのがありましたけど、全５回で１万２,５００円。とても金額的に気軽に参加できるという料金ではとても私はないと思うんですけれども、こうした料金設定について条例や今度答申が出て芸術祭も含めて具体化するわけですけれども、どのような姿を事業として求めていくのか、区の姿勢をご説明いただけますでしょうか。","respondent":"堀越文化スポーツ振興課長","answer":"料金を安くすれば、それでいいのか、個人的な充足をするためだけに料金を安くするのではなくて、適正な料金で、良質な文化のいろいろなものを提供していく、それが区の役割であり、また文化振興事業団の役割ではないかと、このように認識しています。","id":"exchange-135"},{"speaker":"中塚委員","kind":"質問・要望","question":"一人ひとりの文化活動や芸術活動を保障するためには、もちろん料金というのが一つのハードルになりますから、そこをしっかりとだれにでも保障させるという役割こそが品川区にあると思いますし、文化芸術・スポーツ振興ビジョンの冒頭にも権利として文化芸術・スポーツを掲げておりますけれども、それをどう保障していくのか、現状でよしというわけでは、これではみんなに。","respondent":"堀越文化スポーツ振興課長","answer":"こういった文化・スポーツ振興を通じて、それをにぎわいにつなげていく、それが品川らしさだというふうに思っていますし、これは文化芸術・スポーツ振興ビジョンの策定委員会においても、委員の多くの方からこのような品川の特性を踏まえて。","id":"exchange-136"},{"speaker":"三上委員","kind":"確認","question":"４点にわたってお伺いいたします。最初は１５５ページ、職員研修、それから１７９ページの荏原第三地域センター移転・改修、それからちょっと午前中に山元委員が質問いたしました１８３ページのなぎさ会館と１７１ページの八潮南小学校跡区民活動交流施設活用経費ということで伺います。先ほど確認してもらったら、無料です。どうなっているんでしょうか、とりあえずこの２点、お願いします。","respondent":"梶戸籍住民課長、堀越文化スポーツ振興課長","answer":"ご意見の中では、やはり畳がいいというご意見もありまして、そういったところで今調整していますけれども、何分和室の部屋を洋間に変える場合については、工事が何カ月かかかりまして。八潮の駐車場の件ですが、今八潮南中学校跡と両方あわせた段階で、管理用の車両の部分も含めて１８台程度を想定しております。それで、駐車場のご利用についてはその中でどのようなやりくりができるかということがまず一つあります。","id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"でも、そういう要望が多くなってきているという現実を考えていただいて、それは早急にやっぱり取り組む、そういう姿勢で臨んでいっていただきたいと、こう思いますよ。人が出入りする、自分の身内のところに訪問すると、こういうことも大事なことですから、そういった点での駐車場確保についての課題として検討しますと言っている以上は、これは検討していただきたいと思います。職員のほう、お願いします。","respondent":"榎本人事課長、吉岡保育課長","answer":"職員の研修ですけれども、あくまでも職員団体というのは区とは別の団体です。そういった意味で、新人に対しても別団体だということをきちんと明確になるように入区式の説明会等でも行っているところです。そういうことをもろもろ勘案した上で、園の運営に支障のある場合については、来園についてお断りをするようにという指示を青少年育成課長、子育て支援課長、そして保育課長の３名連名で出したということがございました。","id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"保育園部会の方が、区職労執行部とともに旗開きへのお誘いを兼ね、各園に年始のごあいさつに伺いました。勤務時間中ですよ。どちらかが勤務時間、保育園の場合は、子どもが寝ていようが何しようが、職員は交互にやっぱり子どものことを考えたら仕事をずっと朝から夕方、夜まできちっと仕事をやっているはずですよね。同じ仲間内じゃないですか、区の職員というのは。そう思いませんか、どうですか。","respondent":"榎本人事課長","answer":"職員団体の活動に関しては、制限の特例の条例を設けております。その中で、基本的に勤務時間外であること、なおかつ、職務に支障のない範囲ということで、明確に職員団体にも申し入れているところですので、そのルールを守るよう今後徹底していきたいというふうに思います。","id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"もう時間がありませんから、八潮の駐車場の件に関しては宿題にいたします。もう一つ、職員の研修については、十分そういった点で組合とのことについてもやっていっていただきたい。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"鈴木委員","kind":"質問","question":"その２点でお聞きしたいと思います。１点目の退職手当の件なんですけど、ここに具体的に数字が示されていますが、平成２２年度退職予定者１０８名の中で、２４億６,８００万円、この金額というのは、実際に計算、定年退職の方ですから、実際に数字がわかっている中で、具体的な数字が出ているというふうに判断してよろしいんでしょうかというのが１点。それだけちょっと先に。","respondent":"榎本人事課長","answer":"こちらに出ている退職手当１０８名分につきましては、定年退職者１０５人および特別職の任期満了者３人ということで、あわせて２４億余円を計上しております。定年退職者につきましては、勤務年数等が想定できますので、その積算に基づいてここに計上しているものです。","id":"exchange-141"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。その中で退職金の計算方法が何年か前に変わったというふうにたしか聞いているんですが、役職手当が加算されるということで、その目的、当時の記憶がなかったので、増やしていった目的とか、それから数字的には退職金に影響を及ぼしているんでしょうか。そこの２点を教えてください。","respondent":"榎本人事課長","answer":"退職手当条例の改正が平成１９年４月に行われております。その中で、ポイント加算制という形で入っております。要は、職層に対しての最終的に退職手当に加算するというもので、退職前２０年間にどういう職層にいたかということで、それぞれ金額で加算するというものです。","id":"exchange-142"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。これは今までちょっと記憶になかったので、今回はおもしろい企画だなというふうに読ませてもらいました。それと同時に退職する方が、常勤で再任用ということがどこかで出ていたと思ったんですけど、その方たちは常勤の再任用になった方、例えば係長の方が再任用になったときは、役職は変わってしまうという形になるんですか、そのまま役職を引き継いでいくのか。そこら辺はどうでしょう。","respondent":"榎本人事課長","answer":"とはいえ、下から来る４０歳代、３０歳代が係長になる人数というのも限りがありますので、その中で係長級の方で常勤になる場合については、係長ポストとして残ってもらうということで、実際には再任用で残っている方のほとんどが。","id":"exchange-143"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。今なる方が少ないということの中で、逆に言うと、なりやすいのに試験をもっと受けてもらいたいなという気持ちもありますし、どっちがいいのかちょっと私も判断がつきかねているんですけど、若い人にとっては係長の仕事を引き継いでノウハウをつかむというのが一番大事だと思うんですけど、その辺で人事課長としてどういうふうに判断していくのか、ちょっと教えてください。","respondent":"榎本人事課長","answer":"そういった中で、なるべく順調に係長として育っていくような形の期間も一定程度必要かなということで、再任用の場合には最大５年までしかいられませんので、その中で実際には５年間全部がフルタイムというのはなかなか難しいところですので、そのバランスをとりながら。","id":"exchange-144"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、例えば事務事業評価をやることによって、評価することはもちろんいいと思っているんですけど、スタート時の思いがそこに入れるべきなのか、それともそういうものは抜きにして、ゼロベースで考えていくのか、どう考えていったらいいのかなというのは、その辺は事務事業評価を進めていく上で考え方を教えてください。","respondent":"久保田行財政改革担当課長","answer":"事務事業評価についてですけども、施設、今委員からもお話が出ましたように施設の当初の設置目的というものがありますので、これはこれで必要があって施設を設置したものですから、これは継承していかなければいけないというところは考えております。","id":"exchange-145"},{"speaker":"鈴木委員","kind":"意見","question":"施設はわかります。それと同時に、品川の政策として施策事業を展開していく中で、その事業の展開についてどう考えていくのか、そっちのほうが私は気になるんですけど。","respondent":"久保田行財政改革担当課長","answer":"今施設のお話をさせていただきましたけれども、政策の面におきましても同様な形で、やはり当初の目的は尊重しながら、継承していきながらも、その時代に応じた、時代の区民ニーズに応じた形で施策も柔軟に対応していきたいというふうに考えているところです。","id":"exchange-146"},{"speaker":"鈴木委員","kind":"質問・要望","question":"わかりました。最初に立ち上げたときの担当の方の思いもあると思うんですよね。その辺もだんだん担当がかわってしまうと、引き継ぎがどこまでされていくのか、ちょっとその辺が気になっているところなので、うまく伝えていっていただきたいなということをお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861914?Template=document&Id=932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":122464,"voices":374}},{"id":"h22-20100311-3","meetingId":"h22-c-budget","date":"2010年3月11日","dateIso":"2010-03-11","committee":"予算特別委員会","time":"午前１０時０２分～午後６時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"私から２１５ページの地域福祉計画の改定、まずこれを伺いたいと思います。それから、経費が約１,０００万円ということなんですが、この内訳を教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"これにつきまして、今後の予定では、各地域でそれぞれの特性に応じた課題等を、こちら側で地域に入ることによって抽出しながらまとめてまいりたいというところで、中身につきましては、区民との協働による形で、地域特性に合わせた仕組みということで。","id":"exchange-001"},{"speaker":"山内委員","kind":"確認","question":"協働というのが非常に大事な部分だと思います。民生委員、それから町会の方々と役所の方々とが連携をし合って、地域の福祉というものを計画していくということで、確認の意味でこれは質問させていただきました。基本的には大幅に何かが変わるんだということではなくて、今まで培ってきたものをどこか手直しをする部分があれば、そこを手直しをしていくというような形での認識でよろしいのでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"助け合いと支え合いを進めていくということには変わりありませんが、前計画から後に、いろいろさまざまなこと、先ほどございましたような、認知症の方が増えているということも含めまして、さまざまな地域の課題が増えています。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問・要望","question":"了解いたしました。続きまして、同じく２１５ページの紙おむつの支給についてを伺いたいんですが、社会福祉協議会が要介護３から５の方には支給をしているということで、紙おむつの種類が４種類支給をされておりますね。その辺の確認と、この数ですね。これは決まっていますけれども、その辺は、先ほど申し上げたように、人それぞれだと思うんですけれども、それについて伺いたい。","respondent":"冨岡高齢者福祉課長","answer":"枚数につきましては、まとめてお渡しするとか、そういう形でやっているところです。２カ月に一遍でいいとか、そういうところの部分はまとめてお渡ししている。連絡をいただければ、そういう形で柔軟に対応しています。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"２４３ページの幼児の二人同乗用自転車のレンタル事業なんですけれども、今期からということなんですけれども、台数等々の数を伺いたいというのがあるんですけれども、新政権で子ども手当が支給されるというところで、こういう意見もあったということを聞いておいていただきたいんですが、子育てのために政府は手当を支給するというところで、この自転車、確かに高額なんですよ。それはわかっています。","respondent":"安井子育て支援課長","answer":"何台かですけれども、初年度については１５台を予定しております。","id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"交通安全という部分で、もう理解はしているんですよね。最後に、２５８ページの生活保護費に関連して質問をします。支援の条件が、ちょっとここはどうかなというのがあるのは、離職後１年以内である方が支援の事業を受けられるというところがある、そういう難しい部分もあるのかなと思うんですけれども、この事業に対して品川区としてはどのように周知をしていくかというところを伺いたいと思います。","respondent":"平澤生活福祉課長","answer":"ハローワークでやっているのは４つの事業がございまして、それぞれ対象ごとに区分けしてということになっているわけですが、ご指摘のとおり、支給条件が、例えば委員がお話しになりました就職活動困難者支援事業、こちらにつきましては、事業主都合による解職。","id":"exchange-005"},{"speaker":"金野委員","kind":"提案","question":"よろしくお願いします。こうしたときに、町会の会館へのこうした地域の協力要請をしていただく体制は、今現時点ではどのようになっていますでしょうか。それから、協働という観点から、こういう町会の会館を活用するに当たって、今後こういったところへの支援体制というんでしょうか、そのお考えを、あったらいいのではないかなと、このように提案をするものですが、ご見解を伺いたいと思います。","respondent":"中山防災課長","answer":"第一義的には親族のところへ行く。それがなかったら、ソレイユ戸越のほうに避難していただくと考えています。","id":"exchange-006"},{"speaker":"金野委員","kind":"質問・要望","question":"それは理解をしております。次にまいります。空き店舗の活用保育サービスですけれども、これとあわせて家庭福祉員制度、両方お聞きしたいと思います。そうしたときに、こういう空き店舗のこういったところで、保育施設が整ったところであるならば、やれるかなという人はいるのではないかなと考えるんですけれども、いかがでしょうか。","respondent":"吉岡保育課長","answer":"まさに文字どおりの昔からある保育ママの形ですけれども、その形ももちろん視野には入れておりますけれども、さまざまなお話にございました空き店舗ですとか、あるいは区の施設の有効活用というような中で。","id":"exchange-007"},{"speaker":"金野委員","kind":"質問・要望","question":"北品川のほうでの空き店舗活用は、私も理解をしております。となると、これをどうまとめていくかというところであるのかなと思うと、空き店舗の活用というところでの考え方も少し違うのかなという感じがしたので、この問題を、問題というか、課題を改めて確認をする意味でも挙げさせていただきました。","respondent":"吉岡保育課長","answer":"ご自宅で見ていただくような場合ですと、当然普通のご家庭では、子育てはご家庭でもされるわけなので、基本的な設備はあるかと思うんですけれども、保育ママとして仕事として預かっていただく場合には、一定家の中の改造ですとか、あるいは設備の改修ですとか。","id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"時間がなくなりましたので、最後の幼児二人同乗用自転車でお聞きしたいところなんですが、シルバー人材センターに委託をされていることだと思いますので、レンタルの手続、簡素化というんでしょうか、簡単に皆さんが借りられるようなシステムをよろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは２２４ページから始まります障害者福祉につきまして、特に障害がある人とその家族の高齢化について、その支援策を中心にお伺いしたいと思います。２年前に質問したとき、この考えについて重要な課題だと。具体的にどう実現するのか、今検討しているとご答弁がありましたけれども、改めてどういった課題だと認識しているのか、今どういう検討状況なのか、ご説明いただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"私どもは、できる限りグループホーム、例えば入所ができるところとかということで考えているところです。来年度検討ということで、ライフサイクルということで、在宅の支援を強化していかなくてはならないかということで、その中でさらに検討を進めていくという状況です。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"先日、グループホーム森前が開設して、これ自体は歓迎したいと思うんですけれども、親なき後の子どもたち、娘、息子たちの生活について、どういう理念で支えていくのかというところをご説明いただきたいなと思います。そのためにはどんな支援が必要なのかというのを伺いたいなと思います。悲しいという思いをどう受けとめていらっしゃるのか、基本的な理念をご説明いただきたいと思います。","respondent":"高橋障害者福祉課長","answer":"住宅改修が必要であれば、軽減ということで、そういうことのサポートをしていくということで、さまざまな在宅支援もありますので、ご本人の障害、または家族の状況に応じまして、ケアマネジメントする中で、その方をどうやって支えていくかというのが重要かと思いますので。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"親もずっと子どもと接することはできませんから、そこの不安にどうこたえていくのか、どう理解しているのか伺いたいなと思います。そのための体験や経験ができる、そんな仕組みを整えてほしいとおっしゃっていました。親が元気なうちに子どもたちが自分の生活をしていく、グループホームへの体験入所ができる、こうした検討が私も必要ではないかと思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"グループホームでの体験ルームですが、まず初めに、知的障害者の場合、１人でまず最初宿泊できるのか、どうなのかというところから、ショートステイを利用なさるとかというところの段階的なことが必要かと思います。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ＮＰＯがやっているというお話がありましたけれども、どういった規模で、何床というのか、ちょっとよくわからなかったので、どんな事業なのか教えていただきたいと思います。子どもの自立や独立、その形はいろいろあると思います。１カ月間という体験ができるグループホーム、そういうのをしっかりと検討していく必要があるのではないかと思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"実際上グループホームに入っている方については、基本的には、手帳でいいますと、３度、４度の方が多いんですが、２度の方も、そういうことでは親の支援がかなり重要でして、そういう方も実際上入所しながら生活しているという状況ですので。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のＮＰＯがやっているもの、これはどういう整備状況なのかよくわからないですけれども、これで十分だとお考えなのか。今後どういう方向を考えていらっしゃるのかお考えを聞かせていただきたい。これは何週間いられるのかよくわからないですけれども、しっかり１カ月間、体験ができるような体験グループホームの整備が必要だと思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"この辺につきましては、施設がどうだとかではなくて、一人一人の状況に応じて対応してまいりますので、その辺についてご相談いただければ、ケアマネジメントを進めさせていただきたいと思いますので、よろしくお願いします。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど伺ったのは、今の２所という、この状況で十分なのかと。それについての答弁がありませんでしたので、ご答弁していただきたいと思います。１カ月間という体験グループホームが必要だと思いますし、親にも必要だと。こうした仕組みは、障害者、親の当事者参加で意見を聞きながら進める必要があると思うんですけれども、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"入ってからそこの世話人がサポートするのではなく、その辺も含めまして、家庭生活のところから支援してまいりたいと思いますので、よろしくお願いします。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"ほかに方法があるのなら教えてほしいですけれども、もう１回認可保育園というのも１つの選択肢として入ってくるんじゃないかと思いますが、これから出てくる待機、これ以上の余剰分というのを、足りない分というのをどう考えているか、教えてください。それに関連して、家庭福祉員制度、保育ママも１つの受け皿になると思うんですけれども、これ、いつから、何人分ぐらい使えるかということを教えてください。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長、高橋障害者福祉課長、吉岡保育課長","answer":"こちら、区のほうといたしましても、こういう筋力を鍛えるというのは非常に重要なことなので、広げたいなという気持ちはあるんですけれども、ただ。お話の都市型のケアハウスの創設ということで、どういうふうに考えておるかということだと思いますけれども、区では、在宅介護を中心に。グループホームそのものは、知的障害者ということで、知的の特性もありますので、ご本人のご希望、家族のご希望、それから自立が可能かということで。","id":"exchange-016"},{"speaker":"阿部委員","kind":"質問・要望","question":"出てきたばかりの話ですから。今の段階で考えていることがあれば教えていただきたいと思ったので、教えてください。それから、グループホームは、選考の基準について聞いたのではなくて、公募したかどうかについて伺ったので、それを端的に教えてください。まだ建物が新しければ、ほかに転用できるような形できちんと受け皿をつくっていくという発想も必要なのではないかと思って伺いました。","respondent":"永尾高齢者いきがい課長、冨岡高齢者福祉課長、高橋障害者福祉課長、吉岡保育課長","answer":"区のほうといたしましては、参加された方が、将来的にはボランティアになって、地域で活動できるような。おっしゃるとおり、こういうケアハウスにつきましては、東京都のほうのモデルということで。先ほど基準を申し上げましたが、知的障害者の特性から、従来から私どものケースワーカー、福祉士等にご希望があった方等を含めまして。保育園の入園のご要望の受け入れとして、期間を限定して、公、区が受け入れを図ってはどうかというご質問ですけれども。","id":"exchange-017"},{"speaker":"阿部委員","kind":"質問","question":"もちろん仲間内でやっていれば、ある程度安心感のある中で、気持ちも通じ合って、スタートしやすいという面もあるかもしれませんけれども、やはり行政なのですから、手続的にはきちんと公募をして、その中で結果的に、そこになれている人、人になれている方が入ったとしても、手続としては、行政としての責任として、またほかの方、入所した後から、入った方の気持ちからいっても。","respondent":"高橋障害者福祉課長","answer":"公募ですが、知的障害者の状況を、従来から私どもに寄せられている希望を踏まえまして、今回やったものです。公募の件につきましては今後検討します。","id":"exchange-018"},{"speaker":"原委員","kind":"質問・要望","question":"２１３ページ、ホームレス対策、それから２５８ページ、民生費の中の扶助費ですかね、特に母子加算、その辺を関連してお聞きしていきたいと思います。初めに２１３ページのホームレス対策。ですから、その辺のところで、まず人数的なものを含めまして、人、それから、対策について、品川区で具体的に特にとっているような方法があればお教えいただきたいんですけれども、よろしくお願いいたします。","respondent":"平澤生活福祉課長","answer":"ホームレスのことに関するご質問だと思います。私どものほうで、年２回、目視による確認というのをやらしています。去年の２月が３５人、去年の８月が４４人でございまして、今年のデータは、ちょっと申しわけございません。後でご答弁さしあげます。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"扶助費ということではないんですけれども、全体的に国も地方も数字的に上がってきておりますので、考え方としては、行革面ですとか、これはお金の問題になってくれば、企画のほうでしょうし、その辺のお考えと、また、これは実際には民生のご担当のほうのセクションからの、大きく、そういった形、１００億円近くになってきているという、この扶助費についてお話をいただければと思います。","respondent":"平澤生活福祉課長","answer":"こういったところで、扶助費全体としましては、１７％強増やさせていただいているですが、これは来年度の増を見込んだ数字ということでお願いしている次第です。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"質問的には、担当セクションだけではなくて、すいません、その辺をお願いできればと思うんですけど。","respondent":"金子企画財政課長","answer":"ただ、社会的にそういうものが必要性として出てくる限りは、当然私どもも対応しなければなりませんので、そういう意味では、所管課は所管課なりの工夫、また私どもとしては、全体的な工夫をしながら、これに当たっていきたいと考えています。","id":"exchange-021"},{"speaker":"原委員","kind":"質問・要望","question":"そうしますと、その辺のところで、当然に今までセクションと全体とのバランスを見て、品川区の場合にはバランスのとれた運営をされているので、ここにおいても、運営はバランスをとっていただきたいという形です。そうしましたら、次に、母子加算についてお伺いいたします。その辺のところの２点についてお聞きできればと思うんですけれども、いかがでしょう。","respondent":"平澤生活福祉課長","answer":"ただ、自立の援助についてのところなんですけれども、自立の援助につきましては、私どものほうで就労支援の相談員、今回の予算編成の中でも充実するということでご審議いただいているところですけれども、そういったところを使いまして。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"答弁を伺いまして、安心しました。ですから、その辺の受けとめを、十分に両方の意見を聞いて、今後の対処をしていっていただきたいという考えでおります。ですから、品川区においても、これは国のもともとの基準なのかもわかりませんけれども、品川区として父子家庭についてどう思われているかを一言いただければと思います。","respondent":"平澤生活福祉課長","answer":"初めに、私どものほうで、母子加算という名前なんですけれども、母子家庭というふうに誤解を受けてしまう名称、ネーミングなんですが、対象児に当たる父子のところにも出ております。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"当然に法律上のルールはわかるんですが、意外と男女平等の問題ですとか、言葉上の問題で、理論のところでの闘いというか、そういう言い回しの部分が出てくるものですから、私のほうで質問させていただきたかったのは、そこの部分ではなくて、実際に、これは来年度なるかどうかという、今話をされていますけれども、児童手当の問題ですとか、要は、男親とお子さんと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"２４０ページ、児童福祉費なんですが、児童福祉といいますか、子ども未来事業部全般について伺いたいと思います。例えば船頭がいっぱいになっちゃっているような感じはないのかなという疑問がありますので、その部分に関して。今回、船頭がたくさんになっちゃっていないか、指示系統が複雑になったりしてないかという部分についてお教え願えますでしょうか。","respondent":"古川子ども未来事業部長","answer":"３人の課長が地域を割りながら、それぞれの児童センター、保育園、そして幼稚園も含めまして、日々には職員を管理する。最終的には品川区の方針をそれぞれの所管する保育課、あるいは子育て支援課が、児童センター、保育園を集中的な形で、一定の方針を持っていく。","id":"exchange-025"},{"speaker":"渡部委員","kind":"確認","question":"例えば児童福祉全般と言ったら変ですが、支援をいただくための相談に行くのであれば、子育て支援課に行けばいいというようなことだと確信していますが、その確認と、例えば保育園に通っている方とかに、地区によって、文書は当然園長名で出てくると思うんですけれども、行政から何か出る文章については、それぞれの保育園に対して課長名で出ることがあるのか。その辺の確認、２点お願いします。","respondent":"古川子ども未来事業部長","answer":"こういう形です。窓口につきましては、従来からそうでありますけれども、各施設が基本的には窓口を１つ構成しています。もう一つは、３つの課がそれぞれまた対応できます。最終的には、例えば保育園の入園でありますと、保育課の入園相談の中にすべて集約されてまいります。","id":"exchange-026"},{"speaker":"山元委員","kind":"質問・要望","question":"最初に２２５ページのサポしながわ支援事業について、また２点目には、２４５ページの病児保育についてお伺いします。昨年の７月に２カ所目の病児保育、東大井に開設されたわけですけれども、周知の方法とか、また今現在わかっている段階で構わないんですけれども、利用数というんですか、それとまた、どの辺の地域の方が来られているのか、教えていただきたいと思います。","respondent":"吉岡保育課長","answer":"事業者のほうも、インターネット等を通じて周知を図ったところです。それから、利用の数ですけれども、２月の末の数字ですが、２月末までで延べ人数２３４人のご利用をいただいているところです。地域別の分析まではまだしてございませんので、申しわけございません。","id":"exchange-027"},{"speaker":"山元委員","kind":"質問・要望","question":"私も実はご近所なんですけれども、それで保育園のところにちょっと立ちどまって、病児保育、立会川というところにあるんですが、できたんだけど、知っていますかと何人かの人にお聞きしましたら、病児保育のあることは知っているし、また開設されたのも知っているんだけれども、場所は知らないということで、そういう意味では、周知の方法をもう少しご努力をしていただきたいなと思いましたので。","respondent":"吉岡保育課長","answer":"病児保育の利用の要件みたいなものということかなと思いますけれども、利用できる状況というのは、入院の加療が必要になるような重い病気ですとか、あるいはほかのお子さんに病気がうつってしまうような感染性の強い感染症などの場合はご利用できないんですけれども。","id":"exchange-028"},{"speaker":"山元委員","kind":"質問","question":"ホームページを見ますと、利用できる対象といいますか、まずは品川区内に住んでいる人、そして保育園とか幼稚園に通っている人というふうになっております。そして、困ってしまうのは、品川区で預かっていただければ一番仕事がスムーズにいくんですけれども、その辺が、他区で住んでいながら、お仕事は品川という、その方たちは、こういうところの病児保育に預けることというのはいかがなんでしょうか。","respondent":"吉岡保育課長","answer":"考え方としては、病児保育については、基本保育にプラスアルファといいますか、いわば特別保育というか、基本保育にさらにつけ加えた付加のサービスですので、基本的には区内在住の方ということで考えているところです。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問","question":"今、２,０００円のお話も伺いました。やはり利用なさっている方は、パートでお仕事をなさっている方がおりまして、タクシー代を使って何回か利用するのは大変負担がかかるということで、その辺の２,０００円というのをお考え直す、また変更するようなことというのはございませんでしょうか。","respondent":"吉岡保育課長","answer":"利用料につきましては、現在のところ見直す予定はございません。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問","question":"これ、最後の質問です。場所が１つはキッズベル品川は戸越のほう、そして今回の酒寄医院は東大井二丁目にあります。そうしますと、小山とか荏原のほうにそういう施設がないんですが、何か予定といいますか、何かお考えはありますか。","respondent":"吉岡保育課長","answer":"基本的に病児保育につきましては、やむを得ずお子様を預けて仕事に行かなければならない方の受け皿と考えてございまして、基本的には病気のお子さんについては、病気のときぐらいは親が看病できるような体制ができなければいけないかな。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問・要望","question":"サポしながわについてご質問します。サポしながわは５５歳以上の方が求職をするわけですけれども、実際今、登録されている方の人数ですかね、また、平均というのは変ですが、人数的に、登録している方の中で、何歳ぐらいの方が一番登録されている方が多いのか、その辺を教えていただきたいんですけれども。","respondent":"福島ものづくり・経営支援課長","answer":"サポしながわに関するお尋ねですが、求職者、登録者ですが、平成２２年の２月現在で１,１０５人です。これは前年度に比べまして、１０％以上増えているという状況です。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問","question":"何回か合同就職面接会等開催なさっておりますけれども、参加企業数とか、またそこで成立した、就職が決まったというんですかね、決まった方たちというのは、具体的に人数はおわかりになりますか。","respondent":"福島ものづくり・経営支援課長","answer":"今年６月に行いました第１回の合同面接会、来場者が４０８名でございました。ちなみに前回が２２５名ですので、倍増しているというものです。実際に採用された方が３９名という実績でございました。第２回の就職面接会につきましては、１１月に行いました。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"２２１ページ、介護予防・シニア活動拠点なんですけれども、ここは介護予防を必要としている方の大体２割ぐらいしか受けていないということですけれども、その数字をどう分析しているかということと、受けている２割の方の８割は満足をしているというようなことを伺っていますが、その辺の数字的なことについてもどういうふうに理解しているか教えてください。","respondent":"永尾高齢者いきがい課長、吉岡保育課長","answer":"介護予防事業を受けている方、２割程度というような結果ですが、特定高齢者の把握ということが課題になっている部分がございまして、特定高齢者というふうにご自身のほうでなかなか認めてないという意識もありますので。保育園の職員の２次募集を行った理由ですけれども、昨年の決算特別委員会において、既存の保育園における定員の拡大等を皮切りに、さまざまな待機児解消のための施策を検討してまいったわけですけれども、年が明けた段階になりまして。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"どんどんどんどんやって、いろんな公園で、全部の公園とは言いませんけれども、せっかくいい、やる場所があるのですから、その辺も生かしていけないかなという思いがあるので、その辺について教えてください。待機児対策だけではなくて、品川区の保育園というのは、質もいいわけですから、その辺の実際にやっていらっしゃる職員の方たちの質を保つためにも、また新しい意見とかいうのも入ってくるわけですね。","respondent":"永尾高齢者いきがい課長、吉岡保育課長","answer":"ただ、区といたしましては、協働の仕組みを生かしながら、声かけとか、またＰＲするとか、そういうことで広げていくように考えていきたいと思います。そういう中で、０歳から５歳までのいわばフルスケールの保育園と、それから４歳、５歳の幼稚園が一緒に共存する形での幼保一体施設という形になってありますので、今までとちょっと違った新しい施設、幼稚園。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"今残っている伊藤、浜川、城南、八潮に関しては、今後どういう展開をしていくのかということと、それともう１点は、部長とのやりとりの中でよく、さまざまな、さまざまなという形で、ずっと待機児に関してよくやってくださっていると思いますけれども、それでも待機児はいなくならないという現実がありますけれども、午前中ちょっと出ておりましたけれども。","respondent":"吉岡保育課長","answer":"伊藤、浜川、城南、八潮、幼稚園ということだろうと思うんでけれども、単独の園につきましては、従来からそれぞれの園においても預かり保育を実施するなど、一定の就労のご支援も行ってまいりました。同じような考え方に基づいて今後も十分な幼児教育をしてまいりたいと思います。","id":"exchange-036"},{"speaker":"渡辺委員","kind":"質問・要望","question":"私は、２２３ページ、先ほど来出ておりますが、介護予防事業費、それと２５５ページ、すくすく赤ちゃん訪問事業、この２点で伺わせていただきます。違いがあれば教えていただきたいと思います。訪問事業、訪問の方法の確認を伺いたいのと、もう一つ、対象の家庭が、年度単位でいいんですが、どのくらいあって、その中でどれぐらい実際応対できていて、できないのがどれぐらいか教えてください。","respondent":"永尾高齢者いきがい課長、安井子育て支援課長","answer":"それとあと、かわら版についてですが、こちらについては、在宅介護支援センターのほうと、保健所、地域センターに配布しておりますので、あと、何かイベントのときに配布などできればと考えているところです。平成２１年度につきましては、１月末現在ですが、保健センターのほうが１,６４２件、児童センターのほうが１５７件となっております。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"さきの介護予防事業、まず本当に今の施策が中心的になって、これから広く広がっていくんだろうと思いますので、しっかり応援したいと思います。それと、訪問事業のほうなんですが、孤立化の先にいろんなトラブルが全国ニュースでも流れます。これはやはり未然に防ぐ努力というテーマで、今おっしゃられたと思います。やむを得ないケースもあるのかどうか、最後教えてください。","respondent":"安井子育て支援課長","answer":"児童センター等で親子サロン等をやっているとか、そういったものについてもあまりよくご存じないという方もいらっしゃいますので、そういった方をすくい上げるというような形でやっているということで、さらには、すくすく赤ちゃん訪問の際には。","id":"exchange-038"},{"speaker":"本間委員","kind":"質問","question":"２１５、２１９ページに出ておりますが、品川介護福祉専門学校ならびに福祉人材確保・定着事業について、２２１ページ、高齢者生きがい対策事業、２２３ページから２２４ページ、高齢者就業支援についてお尋ねしたいと思います。その中の１つとして、住宅手当緊急特別支援事業というのが７,７１３万円余という形で計上されておりますけれども、この中身についてお尋ねしたいと思います。","respondent":"平澤生活福祉課長","answer":"住宅手当についてのお尋ねです。大きく分けまして、住宅手当の相談員の人件費、それと、こちらの実際の手当のほうの扶助費、こちらが主なものです。扶助費のほうの金額だけを申し上げますと、６,６００万円ほどとなっております。","id":"exchange-039"},{"speaker":"本間委員","kind":"意見","question":"結局国からお金が出ている部分がかなりな金額ということで報告されておりますが、その中で、今のような扶助費のほうにほとんど使われていた６,６００万円という形でございました。この件で、その次にいきますけれども、その隣といいますか、その下のほうに、中国残留邦人等支援事業費というのがあります。昨年もちょっと触れたかと思いますけれども、この具体的な内容と対象人数についてお知らせください。","respondent":"平澤生活福祉課長","answer":"実際の事業といたしましては、こちらにつきましては、自立の支援ということで、例えば日本語学校に行かれる方の交通費や受験料や何かの保護、そういったところが主なもので、あとは、通訳の方が要りますので、そちらの手当、そういったところになっております。","id":"exchange-040"},{"speaker":"本間委員","kind":"意見","question":"この件につきましては、結局国からの補助金がついている。国を挙げての支援ということで、世帯数は２６世帯ということで、少ないようですけれども、自立支援のためにそのように国のほうで援助をするということが出ておりましたので、お尋ねさせていただきました。団体や個人、登録者の数について、あるいは、利用者の料金はいかほどになっているのか、そして、利用者の評判についてお尋ねします。","respondent":"冨岡高齢者福祉課長","answer":"協力は、東京都理容生活衛生同業組合にお願いをして、行っていただいているところでございまして、実施の回数は年に６回ということで、理美容券をお渡しして、理容につきましては、平成２０年度の数値ですが、３９４件でございまして、平成２１年度は１２月末で３１３件です。","id":"exchange-041"},{"speaker":"本間委員","kind":"質問","question":"利用者の評判についてお答えがなかったんですけれども、これは全くのボランティアなのかどうかということをお尋ねしたかったんですね。しかし、受けとめ方としては、喜ばれているような事業のように聞こえてきましたものですから、ボランティアという部分の意味合いについて、今、お尋ねさせていただきました。","respondent":"冨岡高齢者福祉課長","answer":"これにつきましては、ご本人からも半額の負担をいただいていまして、ボランティアではございません。こちらからは委託費でお願いをしています。ご本人からも半額負担をいただいております。","id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"次に行きます。これは介護福祉専門学校との兼ね合いだと思いますけれども、既に十数年が経過しておるかと思いますが、卒業生が区内にどの程度定着をしているのか。まさに今回のこの中では、福祉人材スキルアップ事業ということが大きな金額の中で、７,３２０万円ですか、計上されておりますが、これまではマンパワーの拡大ということで、人材の育成を急いでいる。簡単で結構です。","respondent":"冨岡高齢者福祉課長","answer":"今回の福祉人材の確保といいますのは、国の事業ですが、今就職されてない方を雇うことによって、現在お勤めの方に研修に行っていただくということで、その部分の経費というのが福祉人材の確保事業の経費ですが、一番最初にお尋ねの介護福祉専門学校につきましては。","id":"exchange-043"},{"speaker":"本間委員","kind":"質問・要望","question":"介護基盤整備が急務な昨今、特養ホーム、グループホーム等々の整備にこれからも品川区は力を入れていくわけですから、人材の確保、そして質的向上に向かって、ぜひとも力を入れて、取り組みをさらに進めていただきたいと思っています。２２１ページの高齢者生きがい対策事業の中に幾つか事業がありますけれども、この中には、いきいきマージャンだとか、そういうのが入っていないのかどうか、お尋ねします。","respondent":"永尾高齢者いきがい課長","answer":"いきいきマージャンのほうは、こちらの表示には表に出していないんですけれども、高齢者の趣味・健康づくり事業の中に入っております。","id":"exchange-044"},{"speaker":"本間委員","kind":"質問","question":"結構最近では、脳の面で、認知症防止とかということで、非常にはやっているようですが、いきいきマージャンについての部分がちょっと見えないので、お尋ねさせていただきました。そうしますと、いきいきマージャンの件につきましては、助成的な部分はここに表現されていないんですか。ほかにあるんですか。","respondent":"永尾高齢者いきがい課長","answer":"予算上は５万３,０００円ということで、登録カードの用紙代と郵送料ということで、あとは、すべて日本健康麻雀協会のほうでやっていただいているという状況になっております。","id":"exchange-045"},{"speaker":"本間委員","kind":"質問・要望","question":"８割５分から９割近くが健康な人が多いわけですから、一方では困った高齢者の手助けということと同時に、生きがいの対策にも力を、さまざまなメニューを出しながら、ひとつ駆使していただきたいと思います。最後に、２２３ページの件ですが、高齢者の就業対策費ということで、シルバー人材センターとサポしながわの件が出ておりました。","respondent":"福島ものづくり・経営支援課長","answer":"シルバー人材センターにおきましては、来年度からは就労につながるような学習、そういったものも取り上げていこうと計画しているものです。","id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"大変大事な部分だと思います。６５歳以上、あるいは５５歳から６４歳までのこの部分は、本当に常勤の仕事でなくても、何かお役に立ちたいという部分がありますものですから、その辺のメニューを増やしながら、ひとつこれからも取り組みを進めていただきたいということを申し上げて終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"今回の予算、１,０００万円強となっておりますけれども、この予算の根拠についてもお示しをいただきたいと思います。それから、続きまして、５２６ページの介護保険の主に介護予防についてお聞きしたいと思います。ここら辺についての事務事業、今回どのようにされたのか、端的にお聞きしたいと思います。これについて現状、品川区の対応について一言、現状と対応を確認させていただきたいと思います。","respondent":"冨岡高齢者福祉課長、永尾高齢者いきがい課長、安井子育て支援課長","answer":"こういうものの予算を計上しまして、平成２２年度中に、策定委員会の設置ということを当然考えておりますが、その経費も含めまして。平成２２年度につきましては、いきいきうんどう教室というのを、平成２０年度からやっていた部分を少し拡充いたしまして。そういった対応で虐待の防止、虐待死が絶対起こらないように、さらにもっと一生懸命やるということで、具体的なケースで検討しながら。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"時間がありませんので、端的に質問しますけれども、ここら辺、例えば地域福祉計画、そもそもの対象者というのを改めて伺っておきたいなと思います。この考え方を教えていただきたいと思います。特に、今在宅でも２人に１人が、転倒を２度も３度も経験するという実態がありますので、転倒防止について、ぜひまた力を入れていただきたいなと考えています。以上、よろしくお願いいたします。","respondent":"木下健康福祉事業部長、永尾高齢者いきがい課長","answer":"この目標は非常に高いので、容易に到達することはできないかと思いますけれども、このことを今回出発点にしていくことが大事じゃないかなと考えています。ウォーキングの部分でインターバル速歩というお話がありましたけれども、私の聞いている限りでは、数分間速く歩いて、数分間ゆっくり歩く、そういうのを繰り返していくことによって、足の筋力を高めて、筋力をつけることによって。","id":"exchange-049"},{"speaker":"井桁委員","kind":"質問・要望","question":"私は２１３ページ、１目社会福祉総務費の福祉ショップ運営費についてと、２２７ページ、３目障害者福祉費の知的障害者ふれんどりー事業についてお伺いいたします。福祉ショップ運営費ということなんですけれども、この事業というのは、私が間違っていたら教えていただきたいんですが、福祉ショップのテルベの経費なのでしょうか。それとも、また別にやられている経費なのかというのを１点お願いいたします。","respondent":"高橋障害者福祉課長","answer":"これは福祉ショップテルベということで、大井町のイトーヨーカドーのご好意によって、平成９年から開始した、それの事務費ということで補助金を出しているものです。","id":"exchange-050"},{"speaker":"井桁委員","kind":"質問","question":"素朴な疑問だったんですけれども、２１５ページに社会福祉協議会の助成金ということで書いてあるんですが、なぜ福祉ショップの運営費だけは、前の２１３ページに載っているのかなという素朴な疑問で、そこのあたりを１点お伺いしたいのと、あと、平成９年からやられていて、年々売り上げというのは、かなり認知されて、いろいろ積極的に出ているとは思うんですけれども、収支を見た限り、報告を見た限りでは。","respondent":"高橋障害者福祉課長","answer":"ただ、売り上げを伸ばすということでは、例えば数年前から二、三日程度、イトーヨーカドーを利用しまして、それをやっているものとか、いろんな形で努力はしていますが、まだまだというふうには考えております。","id":"exchange-051"},{"speaker":"井桁委員","kind":"質問・要望","question":"売り上げが伸び悩んで、新しい商品をつくるということなんですが、この事業の意味合いというのもさまざまだと思うんですが、やはりこれからは、生きがいと障害者の方の社会とのかかわりというのを考えたときになんですが、積極的に、そして利益を上げていくんだぞというぐらいの意気込みで臨んでいただきたいなという思いがあるんですが、区として現状維持というのはあまりにも後ろ向きな答弁だったので。","respondent":"高橋障害者福祉課長","answer":"それは区としても支援をしてまいりたいと思いますので、よろしくお願いします。","id":"exchange-052"},{"speaker":"井桁委員","kind":"質問","question":"そこで１つ疑問に思ったんですけれども、福祉ショップの中、テルベがあるんですが、いろいろな役所に行くと、福祉のショップがあったりですとか、あと、パンの工房があったりすると思うんですが、品川区として、今、福祉ショップの商品というのを、パンは販売されているのはお伺いをしておるんですが、その他の商品についてのお店の展開というのは、どのようにお考えでしょうか。","respondent":"高橋障害者福祉課長","answer":"もしくは売り上げの一覧表がありますので、それについて１年間の売り上げの状況をその委員会に提示しまして、製品を入れかえてもらうということをやっていますので、少しずつの売り上げの増で、急激な右肩上がりではございませんが。","id":"exchange-053"},{"speaker":"井桁委員","kind":"質問","question":"区役所内でのその他の商品の販売というのはいかがお考えでしょうか。","respondent":"高橋障害者福祉課長","answer":"区役所の中の販売につきましては、毎月、かもめ工房、精神障害者のところが月１回、昼休みを挟みまして、１日販売しています。売店でいろんな製品を販売させていただいています。","id":"exchange-054"},{"speaker":"井桁委員","kind":"質問","question":"売り上げアップのためには、露出、ＰＲというのが非常に大切になってくると思います。ぜひ区役所の庁舎内で、できれば常設という形が一番望ましいのかもしれないんですが、そこのあたり、多々商品がある中、また、販売方法、いろいろなことがあると思いますが、少しでも売り上げを伸ばしていくという意味では、区役所内の設置というのは前向きに検討というのはしていただけるのでしょうか。","respondent":"高橋障害者福祉課長","answer":"区役所内の販売ですが、昨年、今年ということで、ネットワーク事業ということで、障害者の施設作業所がネットワークを組みまして、販売の向上ということで検討を進めさせていただいてきたところです。","id":"exchange-055"},{"speaker":"井桁委員","kind":"質問・要望","question":"ぜひとも少しでもＰＲという意味では、ホームページ、品川区役所のホームページもあると思いますので、ぜひそこのあたりもリンクができるような形というのもとっていただきたいなと要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"私は、３３ページの介護保険特別会計で、特養老人ホームの増設計画について伺いたいと思います。実施計画をこれからつくるということになっていると思うんでけれども、どういうふうな計画の内容になっているのか、伺いたいと思います。昨年９月が入所申請５５０人ということでありましたけれども、３月はどういうふうな状況なのかというところを伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"計画の内容ですが、第１次の総合実施計画の中で、八潮南中については建設ということと、あともう１所、整備検討という形で３年間で挙げさせていただいているです。","id":"exchange-057"},{"speaker":"宮崎委員","kind":"質問","question":"今、長期計画のところ、実施計画のところでは、整備検討ということで、３年間でつくるということなんですか。この１０年間でどこまで行くのかということですね。この間のやりとりを記録等で見てみますと、用地確保の見通しがないと計画ができないんだという説明なんですけれども、そうすると、用地確保をどういう方針でどういう考え方で今進めようとしているのかというところを伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"用地、一定規模の広さが必要であるということで、さまざまな用地情報を提供を受けながら、適地があれば、そういうところを政策化していくということで、整備検討に入っていければと考えていますが、残念ですけれども、現段階では、適地が見つかっていないという状況です。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"適地があればと、それは当然なんです。私はどういう基準でということを聞いているんですけれども、適地というのはどういうふうに考えているのかということを伺いたいと思います。厚生委員会で請願審査の記録を見ますと、例えば中延だと３,０００m2だと。","respondent":"冨岡高齢者福祉課長","answer":"小規模の特別養護老人ホームにつきましては、単独だと非常に運営が厳しいと聞いておりますので、場合によっては、ほかの施設の併設ということであればいいですが、これにつきましても、土地の問題というのはあるかなと考えております。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、今、具体的に１,０００坪だという想定だということであります。そうすると、大体１,０００坪の土地というと、かなり区内では相当広いなと私は思います。具体的に見当がついているのでしょうか。あるいは、中延程度、そこら辺まで来たらどうなるのか。あるいは１,０００m2だとどの程度になるのか。具体的な試算というのはやられたのでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"ほかの施設についても大体４,０００とか５,０００ぐらいですので。シミュレーションというのは、用地の大きさについて、現状のところではやっておりますけれども、具体的にシミュレーションの内容については、ちょっと今、申しわけありません。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"そうしたら、実際にこの程度の規模だったらどうなるのか。このぐらいの土地だとどういうふうな経営ができるのか。相手は、待っている方は、生きている人間ですからね。そして、特に高齢者の問題というのは、また重ねて急がなきゃいけないと言っているのに、ところが、特養に関しては、スピードだと区長は言っているのに、そういうふうになっていないと思いますが、どうでしょうか。","respondent":"木下健康福祉事業部長","answer":"そういうようなことも含めまして、具体的に用地の確保がついたときに、用地の容積率、広さ等も踏まえて、具体的にどういうものが検討できるのかということをその段階で精査するということになろうかと思います。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"質問","question":"私はそこがちょっと違うんじゃないかということを言っているんですよ。家族も本当に大変な思いなんですよ。一定規模がないとつくらないということではなくて、例えば２９人だったら、このぐらいの土地であるじゃないかとか。私は２９人ぐらいだったら、区内、かなり出てきていると思います。結局やれる範囲でやればいいじゃないかということになっていくんじゃないですか。そこのところはどうなんでしょうか。","respondent":"木下健康福祉事業部長","answer":"そういう点でいうと、高齢期が、要は完全に寝たきりに近いような状態になる方と、そうでない方と、在宅でいける方といろいろあるわけでありますから、区としてはそういう施設整備と同時に、大井林町で今度始める新しいタイプの高齢者住宅。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私、特養だけじゃないと。ほかのも大事だと思うんですよ。老健施設も足りないし、また住宅のほうも足りない。ここのところは重ねて、この１０年間、長期計画の間でどこまで行くのかというところ、目標をはっきりさせていただきたいと思います。この１０年間でどこまで何人の確保をするのか。そのために、小規模でもつくるという姿勢が必要だと思うんですけれども、改めて考え方を伺いたいと思います。","respondent":"木下健康福祉事業部長","answer":"計画化ということについては、この間もお答えしておりますけれども、やはりこれは区民に対する約束になりますから、具体的な目鼻がついている中で計画化するのが行政としては正しいやり方だと考えております。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、そうすると、結局、では、どういう土地を確保するのか。そういう考え方もはっきりしてこないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"地域福祉計画改定のところなんですが、先ほども議論になっておりましたので、策定経費なんかはお伺いしたところなんですけれども、この中で、２００３年に策定された地域福祉計画の、ここが重要だと思うんですけれども、達成度と課題をどういうふうに考えていらっしゃるのか。","respondent":"冨岡高齢者福祉課長、高橋障害者福祉課長、中山地域活動課長","answer":"これも区立の特養３カ所について実施をするという予定です。これにつきましては、障害者の方を安全に安心して任せるということの必要性というふうに私どもは考えております。在宅介護者の激励の研修ですけれども、これにつきましては、宿泊研修、日帰り研修ということで実施しているところでございまして。地域福祉の中で、地域センターの副所長をふれあいサポートの担当者とも位置づけてやっていることの効果ですけれども。","id":"exchange-065"},{"speaker":"井上委員","kind":"提案","question":"ガイドヘルプのところなんですけれども、要件で、２級ヘルパーということなんですが、安全にガイドをするということはわかるんですが、視覚障害者の方のガイドヘルプというのは、ヘレン・ケラーのところでもお伺いしているんですけれども、ここでは２級ヘルパーの研修も入っていますし、盲導犬と何がガイドヘルパーの人と違うのでしょうかといったときに、地域の状況とか。","respondent":"冨岡高齢者福祉課長、高橋障害者福祉課長","answer":"そういうのも含めまして、実際どういうふうに機能していくかということも踏まえまして、地域福祉計画の中で、そのありようについても一応考えていくという方向で進めてまいりたいと思います。ガイドヘルプのことですが、先ほども申し上げたとおり、区としましては、視覚障害者のガイドヘルプの質の確保をするということで、安心と安全を任せるということでは。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"福祉人材スキルアップのところなんですけれども、ここは３特養の２法人ということで、４,３００万円余の人件費ということなんですけれども、これは最終的には人件費だけでなく、何となく法人への補助という扱いになってしまうのかなという気がするんですが、そこのところは収支報告として、人件費ですよということで報告があるのかどうなのかということと。","respondent":"冨岡高齢者福祉課長、木下健康福祉事業部長","answer":"委託料ということで人材確保を、看護職、お願いするということでありますので、当然に実績については報告をしていただいて、成果を報告していただくということと、看護師についても、日勤、夜勤も含めた人件費的な部分ですので。いずれにしましても、地域の中の支え合いの主要メンバーというのは、地域の方の町会とかボランティアの方々ですので、その方々を今後どういう地域のニーズについてコーディネートしていくかということが大事になるわけでありますから。","id":"exchange-067"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうふうなトータルなところで施設と一緒に検討していく必要をここには盛り込んでいただきたい。それぞれの計画ではなくて、区全体で地域福祉を考えるというところに重きを置いてほしいという要望なので、その辺のことについて見解があれば、ぜひお伺いしたいと思います。","respondent":"木下健康福祉事業部長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"山路委員","kind":"質問・要望","question":"私のほうからは２１３ページ、成年後見制度利用支援事業について、２３９ページ、都営大井林町住宅跡高齢者住宅等工事の中から、実施設計委託について、２点目が、２２４ページ、障害者福祉費の内部障害者支援についてお伺いいたします。高齢者住宅と住み替え住宅との部屋は全く同じものか、あるいは変えていくのか、この辺について教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"高齢者住宅ですが、実施計画につきましては、今後詰めていくところです。部屋の広さについてのお尋ねがございました。","id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"大井林町住宅の部屋のことをお伺いしましたけど、私も知り合いから３人ほど相談を受けているんですね。もう１人は、アパートに住んでいる高齢者の方で、お子様が、新高齢者住宅ができたら、そこに自分が家賃を出すので入れてあげたいという、３つの相談があるので、非常に複雑なこの制度との絡みで、こういう方が入れるかどうか教えていただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"高齢者住宅につきましては、独自の基準を設けて、基本的には単身でお困りの方、借家にお住まいの方で、自立をされている方ですが、今、ご指摘の３つの例、非常に複雑な例ですけれども、ご相談いただければ、在宅介護支援センターを通じまして、さまざまなケアと。","id":"exchange-070"},{"speaker":"山路委員","kind":"質問・要望","question":"ちょっと、私、言葉が足りませんでしたけれども、申し込んで、入るということではなく、条件に当てはまるかどうかということを聞きたかったのです。そこで、八潮と密集住宅地域とアンケート調査をやられたということはお伺いしましたけれども、もっと広く調査してもいいのではないかと思っているんですけれども、今後そのような経過があったら、教えていただきたいと思います。","respondent":"柏原住宅担当課長","answer":"それ以外のところにつきましては、アンケートをとるという形では今のところは考えてはおりませんけれども、個別の中で対応する部分もあるかと思いますので、そういったところで考えていきたいと考えています。","id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"はい、わかりました。現在も非常に増えてきているですが、ほかにももう少し、地域センターとか、ハート・プラスマークを増やして、安心して出入りできるようなことを考えていただいてもいいんじゃないかと思いますが、どのようにお考えでしょうか。","respondent":"高橋障害者福祉課長","answer":"そのうち２つが警察で発行しているものです。そのほかにつきましては、各団体が行っているものですが、やはり内部障害ということではなかなかご理解いただけないということなので、この辺の普及につきましては、区内の所管課と検討しながら進めしますので、よろしくお願いします。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"財政規模の説明のところで、消費的経費ということで、子ども手当、そして生活保護が増大したということで、約１８２億円のプラスになっておりますけれども、消費的経費ということをお伺いしたいと思いますが、消費的経費、これはご存じのように、調べてみたんですが、ほとんど多くのところで、消費的という名目ではなくて、むしろ義務的経費ということで表示をされております。","respondent":"金子企画財政課長","answer":"投資的経費はご案内のとおりと思いますが、消費的経費の中に人件費であるとか、扶助費であるとか、あるいは物件費その他たくさんあるんですが、消費的経費の中の特に人件費と扶助費と交際費、この３つについては義務的経費と呼ぶというふうなのが一般的な呼び方ですので。","id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"私、今、増減のことを伺ったのではなくて、なぜ義務的軽費……。義務的経費はわかっています。人件費、交際費、そして今言った扶助費ということで、これは義務的経費とわかっております。なぜここで義務的経費という名前を使わないで、消費的経費という名目でここに出ているのか。それは書く上において、品川区の何かお考えがあると思うので、そのお考えは何かということで伺っています。","respondent":"金子企画財政課長","answer":"委員ご指摘のものは、議案説明会資料のことだと思いますが、これは少なくとも目的別分類という款別の分け方もありますし、先ほど来委員のご質問にもありましたとおり、投資的経費と消費的経費、あるいは義務的経費という分け方が性質別の分け方でありますので、私ども。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"これには消費的経費というものは含まれて書いてありますね。ところが、これには義務的経費という表示があって、扶助費のところで消費的経費と書いてないんですけれども、これは全国一律でということでのお話もいただいておりますけれども、ここのところの関係はどのように処理をされているのか教えていただきたいです。","respondent":"金子企画財政課長","answer":"決算の主要施策の成果報告書についてのお尋ねですけれども、これは、今、委員ご指摘のとおりですが、そのときにもご説明申し上げたとおり、全国一律で比較できるような形で書いてありますので、ここでは義務的経費という表現をしていますが、先ほど申し上げたとおり、この辺は。","id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"私も十分勉強してから聞きに行きますが、あくまでも私が思うには、扶助費、交際費がもろもろ入っているわけですから、消費的経費というより義務的経費に扱っていただいたほうがありがたい。なぜ私がこれを出したかというと、次の質問にかかわってくるわけでありまして、生活保護ということで、今期、民生費に占める割合は４０％です。今後の見通しと対策について教えていただきたいと思います。","respondent":"金子企画財政課長","answer":"そういう意味では、私どもとしましては、さまざま財源対策を講じながら、歳出についてもさまざま見直しをしまして、全体的な予算としてはバランスのとれたものにするべく努力してまいりたいと考えております。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、確認させていただきました。団塊の世代の方、退職をされて、なかなか決まらない。生活保護受給者に占める団塊の世代の割合が増えるのではなかろうかなと思うんですが、そこのところ、きちんとした数字をお持ちであれば、全体の先ほど、３,０００余ということで、２年間、聞いておりますけれども、いわゆる団塊の世代の方たち、その中に占める割合を教えていただきたいと思います。","respondent":"平澤生活福祉課長","answer":"４０人弱増えているところですが、一般的な年齢の階層が上がっていく中での増え方じゃないかなと思っておりまして、特に団塊世代等につきまして、年金制度の問題がありますので、予測ということは、申しわけないんでけれども、わかりかねる次第です。","id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"やはり社会保障制度、根本的に考えていかなきゃいけない時期に、既に遅きに失していると思いますけれども、真剣に考えていかなきゃいけないと思います。それと、記事で読んだんですけれども、団塊の世代の、今私がお話ししたように、その年代の受給者がかなり圧迫しているという記事を見たんですけれども、そのようなコメントは区から発したことはあるんでしょうか、教えていただけますか。","respondent":"平澤生活福祉課長","answer":"新聞記事の中身だとは思うんですけれども、将来的な予測ということで、団塊の世代の方が、失礼しました……。雇用対策というのは重要だという意味合いです。","id":"exchange-078"},{"speaker":"川西委員","kind":"質問・要望","question":"家庭あんしんセンターの利用状況と実績について伺います。ちょっと忙し過ぎるんじゃないかというマスコミ報道もありますし、それから、区民の皆さんの中では、相談しても中途半端に終わっちゃって、もうやめたなんていう、これは１つの意見ですから、意見として聞いていただきたいんですが、そういうご相談もありました。この２点を先に伺わせていただきます。","respondent":"冨岡高齢者福祉課長","answer":"福祉人材のスキルアップ事業の部分ですが、これにつきましては、ケアマネについては対象外ですけれども、ケアマネージャーの方１人で何人ぐらいの方をマネジメントしているかということは、個々の場合はわかりませんが、標準でまいりますと。","id":"exchange-079"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、さわやかサービスのほうなんですけれども、希望する区民の皆様からの要望にこたえられる人数であるかどうか、そこだけ伺います。","respondent":"冨岡高齢者福祉課長","answer":"なかなかうまく充足しているかどうかというところは難しゅうありますが、対応は何とかできているだろうです。","id":"exchange-080"},{"speaker":"川西委員","kind":"質問・要望","question":"ホームヘルパー２級のことなんですけれども、もっと多くの方、できれば若い人たちにこういう講座を受けていただいて、就労をしていただくというのを研究をしていただきたいと要望いたします。終わります。これは一緒の課ですので、親育ち支援事業は、今年、平成２２年度だけではなくて、もう既にやっている。親育ち支援事業の中身について伺います。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"就学前乳幼児教育事業につきましては、幼保一体施設の事業などとも関連してくるんですけれども、就学前の保育園児、幼稚園児がそれぞれ充実した乳幼児教育を受けることによって。父親にとっても子育てが重要だということについて理解していただくために実施しています。","id":"exchange-081"},{"speaker":"川西委員","kind":"質問","question":"家庭あんしんセンター相談窓口の報告がなかったように思いますが、いかがでしょうか。それから、就学前乳幼児教育事業のことなんですけれども、これは、私立の幼稚園、保育園にもお呼びかけがあって、講座に参加したりしておりますが、これは年間計画でホームページ等に掲載されるかどうか、そこだけ伺っておきます。すいません。今の答弁いいです。これからもそのように考えていらっしゃるんですか。","respondent":"吉岡保育課長","answer":"空き店舗活用事業については、内容的には子育ての支援です。","id":"exchange-082"},{"speaker":"高橋委員","kind":"質問","question":"２５５ページの児童センター事業のうちのチャイルドステーション事業と２２７ページの知的障害者ふれんどりー事業についてお尋ねいたします。具体的にどのあたりに設置する予定、あるいは区民の方々の反応、そして、プレス発表にもありましたけれども、周知の方法が問題になって、やっぱりＰＲが必要だと思うんですが、その点について、３点でしょうか、お尋ねいたします。","respondent":"安井子育て支援課長","answer":"公共施設のほうですけれども、そちらについても順次、図書館とか公共施設のほうにも、それぞれ各課に投げかけまして、場所の確保、設置等の進捗を図ってまいりたいと考えております。","id":"exchange-083"},{"speaker":"高橋委員","kind":"質問・要望","question":"積極的に進めていっていただきたいと思います。その中でまず１つ目として、契約についてお尋ねしたいのですが、ＮＰＯ法人との契約なんですが、契約の形態、それからほかの例も含めまして、この段階、つまり予算編成の段階で契約先が決まっているという点について、これは競争入札や指名入札が行われたのでしょうか。","respondent":"高橋障害者福祉課長","answer":"親の会が長年続けてきたもので、その辺については、きちっとその辺の状況を踏まえた上で支援できるということで、区のほうの契約につきましては、指定の推薦をあげまして、ここと契約していただけるようにお願いするものです。","id":"exchange-084"},{"speaker":"高橋委員","kind":"質問","question":"ということは、随意契約ということになるんでしょうか。","respondent":"高橋障害者福祉課長","answer":"今のところ随意契約でお願いをするところです。","id":"exchange-085"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、このような形の契約の例というんでしょうか、いろいろなＮＰＯとの契約については、このような例が多いのか。それとも、例えばちょっと形態があれなのかもしれませんが、すまいるスクールなどは、プレス発表などによると、平成２２年度は区内ＮＰＯ法人との連携を拡大してというところで表現がとまっているんですが、これはちょっと款が変わってしまうんですが、どのような状況なのでしょうか。","respondent":"高橋障害者福祉課長","answer":"障害の部門では、思春期サポート事業ということで、例えば親の会として、パルレが長年やっていて、平成１９年度にＮＰＯ法人として立ち上げたものと単独で契約している例があります。","id":"exchange-086"},{"speaker":"高橋委員","kind":"質問・要望","question":"さまざまな点を考慮しながら、ＮＰＯとの関係づくりは進めていっていただきたいと思います。先ほどの移動支援のヘルパーの派遣経費１,１００万円等を入れると２,０００万円。例えばほかのＮＰＯ等がこのような事業等を受託された場合、このような手厚い支援をしていただけるのでしょうかというところと、それからあともう一つは……。ヘルパーの研修のことについてお伺いします。その点、いかがでしょうか。","respondent":"高橋障害者福祉課長","answer":"ただ、これについては、継続的にずっと続けるものではなくて、ＮＰＯ法人がある程度運営が円滑に行く段階では、なくしていくというような状況ですので、今回については、立ち上げ費用と考えていただきたいと思います。","id":"exchange-087"},{"speaker":"高橋委員","kind":"質問","question":"継続的にといったことではないわけですね。コーディネーターについてお伺いいたします。どのような方が想定されていて、何のため、だれのためのコーディネーターなのでしょうか。これも同じなのですが、来年度以降もコーディネーター経費、２人分７９４万円について、継続して支援していっていただけるのでしょうか。","respondent":"高橋障害者福祉課長","answer":"ただ、永続的、将来的にすべてということではございませんので、その辺については円滑に動いた段階では、なくなる予定です。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"とすると、例えば区の元職員の方が派遣されるなんていうこともあるのでしょうか。","respondent":"高橋障害者福祉課長","answer":"今のところ、予定はありません。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"確認","question":"先に保育施策全般についてでありますが、午前中の質疑を聞いておりまして、確認したいのが、子育てについて、最高の責任者は親であります。社会とか品川区がつくるということであると、非常に政策がおかしくなってくると私たちは思っていますので、これは部長にぜひお伺いしたいんですが、確認しますけれども、子育ての最高の責任者は親であって、行政はそのお手伝いをするべきであるということ。","respondent":"吉岡保育課長","answer":"子どもは大切な社会の宝ではありますけれども、まず一義的には子どもを子育てするのは親の責任と考えているところです。その子育てをなさるに当たりまして、行政としては、就労支援も含めたさまざまな子育ち、親育ちの支援をしてまいると、そのように考えているところです。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問","question":"だけれども、そういう方々に対して、１つのチラシ、もしくはものすごい簡素化したものでいいのかもしれないけれども、福祉政策全般が見渡せるチラシが１つでもあれば、いろんなことについて皆さん方の心配が解消されるということを実感しましたので、ほかの款で、町会の統合チラシの件がありましたので、福祉施策についても、障害者、高齢者、いろんな切り口があるかもしれないけれども。","respondent":"冨岡高齢者福祉課長、山田副区長","answer":"区民便利帳は、全体的な部分はありますが、現在あるものから、では、どういうものをつくっていったらいいのかということも含めまして、課題とさせていただきたいと考えています。ただ、伊藤委員がご提案されているのは、もう少しコンパクトな部分でということでご提案かと思いますから、それは抜粋型としてどういう形があり得るかという形で検討します。","id":"exchange-091"},{"speaker":"伊藤委員","kind":"質問","question":"２２３ページ、ひとり暮らし高齢者等生活支援に関連してなんですが、これはこの間も質問しました住宅用火災警報器に関連してです。この５０人のうち８８％のお宅に警報器がなかったということ。だから、そういうことを品川区は連携をとって、ピンポイントでもいいから、まずは高齢者の皆様方について推進する施策を検討してみてはどうかということの質問ですので、ご答弁をお願いいたします。","respondent":"冨岡高齢者福祉課長","answer":"火災警報器につきましては、高齢者の部分で助成をしているということで、ご案内のことだと思いますけれども、今年度、おかげさまで３,０００件を超える件数までご協力いただきまして、消防署とも町会ともお話をして、進めさせていただいた。","id":"exchange-092"},{"speaker":"伊藤委員","kind":"質問","question":"今現に進めているということはわかっていますけれども、このことについては、高齢者に対してはもっとピンポイントで対処できるはずなんですよ。すべての部屋につけなきゃいけないことになっているわけですからね。恐らく課長が思っている考えは違うかもしれないけれども、我々はすぐに助成せいということは言いません。それだけお願いしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうから３点、確認をさせていただきたいと思いますが、まず、２４１ページの児童相談事業に関連をして、まず１つ、最初に、こども家庭あんしんねっと協議会、ここで２２７万５,０００円計上されてありますが、これの事業内容を簡単にご説明いただければと思います。最初に、先ほど申し上げましたこども家庭あんしんねっと協議会の事業内容を簡単にご説明いただけますでしょうか。","respondent":"安井子育て支援課長","answer":"次に、虐待への対応ですけれども、やはりこれは家庭あんしんねっと協議会ということで、対応については、子育て支援センターと児童家庭相談係のほうで調整等を行いながらやっていっているところなんですけれども、そこでは、まず通告があれば、先ほど申しましたように。","id":"exchange-094"},{"speaker":"堺委員","kind":"質問","question":"ご説明いただきまして、ありがとうございました。大変有意義な勉強になったわけですが、この辺について何か情報を得ておりますか。このような企画も含めまして、この協議会等でも地域分科会云々ということでございましたので、これの拡充というんでしょうか、どんどん推進していったほうがいいなと、こんな感想を持ちましたので、この辺についてご所見をお伺いしたいと思います。","respondent":"安井子育て支援課長","answer":"１３地域でそれぞれさまざまな講演会を開くことによって、委員たちの認識を高めていっていただくというようなことをやっているところです。","id":"exchange-095"},{"speaker":"堺委員","kind":"確認","question":"児童虐待の件です。これは現状の対応、取り組みだろうと思うんですが、今回、報道等によりまして十分ご存じかと思いますので、今回、表面化した主な児童虐待、これについて４件報道されてございましたが、これらについて、どこに問題点があったのかなという件について、区として検討されているのかどうか、分析されたのかどうか、その辺確認しておきたいと思います。","respondent":"安井子育て支援課長","answer":"その他の事件につきましても、報道等を通じて、あるいはそれぞれの自治体に情報を紹介するなどしながら、事件の問題点を他山の石としながら、より虐待防止のために頑張っていきたいと考えております。","id":"exchange-096"},{"speaker":"堺委員","kind":"確認","question":"このように法律は改正をされましたが、現にこのように４件、新たに幼い命が奪われるという大変痛ましい事件が発生してしまったわけですね。ですから、法律が整備されるだけ、あるいは４８時間以内に目視して連携をするというだけだったならば、また同じようなことが繰り返して行われてくるような気がしてならないんです。その辺も含めまして何かご見解がございましたら、教えていただけますでしょうか。","respondent":"安井子育て支援課長","answer":"その提言によってどのように進むかというようなところ、これから注意して、我々もその行方を見守っていきたい。それによって対応を考えていきたいと考えています。","id":"exchange-097"},{"speaker":"堺委員","kind":"質問・要望","question":"その面で、要するにどこが責任を持って、大事なお子さんの１人の命を救うのかという、だれがということを明確にきちっとした上で、連携を保って、大事なお子さんの命を守ってほしい。こういう思いから、この件について確認をさせていただきましたので、ぜひひとつ万全な体制でお取り組みをお願いしておきたいと思います。「中学生も居場所、よりどころを求め、毎日来館する子もいます。","respondent":"安井子育て支援課長","answer":"児童センターは、０歳から１８歳までご利用できる、異世代交流も図れる貴重な場所だと考えています。特に中高生の方たちの居場所というのが重要になっております。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"５４４ページ、介護保険特別会計、認定調査等費について伺いたいと思います。介護給付費抑制を目的として、去年の４月に認定制度が改悪されました。質問なんですが、区はそのように思っているのでしょうか。この間、そういった事態、必要なサービスが受けられなくなってしまったような、そういった事態というのは区内で起こっているのかどうか、現状はいかがでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"それぞれに自己の負担額というのがございまして、サービスの限度というのは、サービスに１割の負担がありますので、ケアマネージャーと一緒にケアプランをつくって、サービスをお受けになるということでありますので、それに即して申し上げますと、制度が変わっても。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"質問の趣旨に全然答えてないような気がしたんですが、認定制度の変更によって、それまで受けていた必要なサービス。さまざまな問題が指摘されている中で、変わることで必要なサービスが以前と比べて受けられなくなってしまうような事態が私はあってはならないと思いますが、区はそのような事態があってもいいと思っているのか、ないと思っているのかをもう一度お伺いしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"認定におきましても、サービスのケアマネジメントにおきましても、適切なケアマネジメントがされていますので、そういった形のことはないと理解しております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"常に電動の車いすでの生活なんですね。この方、Ａさんは、筋力も落ち、６４歳の方ですから、震えも強くなり、むせることが多くなってきた。そこで伺いたいんですが、車いすご利用の方は、要介護３から要介護１に下がることにより、受けられる介護サービスにどのような変化があるのでしょうか。介護サービスの種類、訪問日数について具体的にお答えいただきたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"その方が車いすをどのように利用されていて、どういうことで３から１になったかというのは、これは個々のケースを見てみなければわかりませんが、これはコンピューターで１次判定というものを客観的にいたしまして、それから、審査会という手続を経まして認定を受けている。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"もっと具体的に聞けばよかったんですが、車いすの利用というのは、要介護３から１になったことによっても認められるのでしょうか。そこはどうでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"車いすの利用につきましては、要介護２以上ですけれども、それ以下の場合につきましても、個々の内容を判断させていただいて、対応可能の場合があります。そういうふうに扱わせていただいております。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"個々の状況を勘案するとありますが、基本的には１になると使えないということなんですよ。私が伺いたいのは、今回の改悪により、本人の状態がほとんど反映されなくなってしまったと思うんですが、そして結果として車いすがないと生活できない方が車いすを使用できない要介護度に認定されてしまっているということ、このことについておかしいと区は思わないのでしょうか。認識をお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問","question":"これというのは、調査項目自体が、これに皆さんのっとってやるわけですから、この調査項目のあり方自体がおかしいから、そのように実態として現実に車いすがないと生活できない方が、なぜか車いすを認められない介護度に判定されるという現象が現実に起きているわけですよ。そのおかしさは感じていないんでしょうか。そこら辺、お伺いします。","respondent":"冨岡高齢者福祉課長","answer":"その改定をされたものがおかしいとおっしゃっているのか、ちょっとわからないんですが、改定をされた今、新しいテキストを使って、平成２１年度の審査をしているわけでございまして、それについては、厚生労働省で定めたものでもありますし、国で使っているものですので。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問・要望","question":"このテキストは、そうです、１０月に改正されたんです。そのテキストをもとに今回お話しした事例というのは、行われた判定で、調査したわけですね。これは区民の理解も到底得られないし、そして介護保険のもともとの制度の趣旨であった在宅介護を支えるというところの機能すら果たしていかないんじゃないかと思いますので、調査のあり方、よく分析、そして改善を求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"２つほど。２５５ページのしながわ子育てメッセ２０１０と２５３ページの児童センター運営の全般についてお聞きします。しながわ子育てメッセ２０１０、これは記憶違いだったら指摘していただきたいんですが、これはどういう事業だったでしょうか。協働事業の中のものではなかったのでしょうか。そこを先お聞きします。","respondent":"安井子育て支援課長","answer":"こちらのしながわ子育てメッセにつきましては、在宅の子育てをやっていらっしゃる方たちの支援ということで、本年度についても行われております。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"これ、協働事業だったはずですね。協働事業という意味合いですね。ここの民生費のところに入ってきてしまうと、事業としてどういうとらえ方をしているんだろうかと思います。ですから、地域の方たちの自主的な活動、それを品川区がバックアップするという意味合いであるならば、ここに載せるのはどうなんだろうなと非常に疑問があります。それに対していかがですか。","respondent":"安井子育て支援課長","answer":"ご支援というか、協働で立ち上げていくということで。こちらについては、子育て支援という形で、継続的にやっていらっしゃる団体ということで、引き続きやっていっていただく場合については、それぞれの所管のほうで支援をするような形になっていくと考えております。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"それは幾らでも支援していただきたいと考えています。そうなると、主体はどこにあるんですかと考えたときに、あくまでも協働事業をやる上では、住民サイドが主体になっていかなければいけないのではないか。そういう意味であると、この記載とか、予算の立て方とかについては工夫していただかないと、せっかくの協働事業という意味合いにならないんじゃないかということを思っているわけですが、いかがですか。","respondent":"古川子ども未来事業部長","answer":"ですから、協働の形はさまざまあろうかと思うんですが、平成２１年度はあくまでも協働の１つの施策の中に位置づけられたのは確かでありますけれども、今後とも私どもはこの団体とさまざまな形で地域における子育て支援の１つの場面を設定していきたい、そのように考えております。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"すいません。ですから、協働という中で、ちょっと時間がないので、あまりこれ以上突っ込みませんけれども、今後考えていただきたい区の支援の仕方、協働とある中で、どういう形をとると住民の自主的な行動として育っていけるのかということです。それで児童センターのほうに入りますが、児童センターの役割、非常に広がっております。それを整理していただきたいなと思いますが、いかがでしょうか。","respondent":"安井子育て支援課長","answer":"児童センター、一般的には児童館と言われているんですけれども、児童館という定義では、子どもに遊びを指導するというのが児童福祉施設としての法的な位置づけなんですけれども、品川区の場合は、地域の子育て支援センター機能みたいなところで、親子サロンであるとか。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"児童センターの役割が非常に多岐にわたっているんですね。多分地域の中の中核になる可能性もあるような内容のものが入ってきているんじゃないかなと思います。運営主体を今後どういうふうに考えられているのか。職員のノウハウというのは、今でもかなりあると私は思っていますけれども、継承していくにはどういうふうな考えをされているのか、お聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"こちらにつきましては、どうやって能力を伝えていくかということなんですけれども、日ごろの事業の中での育て方というのもありますけれども、これから研修体制もしっかりと敷いて、新人も入ってくるであろうということも含めまして。","id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"こちらでは、品川の福祉、事務事業概要のほうではこのように書いてありますけれども、要件、６５歳以上の外出・調理が困難な高齢者等を対象にボランティアの協力および区内商店を活用しと書いてありますが、６５歳以上の高齢者、６万８,０００人いる、１９.７８％もいると言われていますけれども、このひとり暮らし高齢者等給食サービスの対象人数、どれくらいいるのでしょうか、お聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"平成２０年度の実績ですけれども、学校給食の分が１０７人、夕食分が６０人ということで、１６７人です。","id":"exchange-111"},{"speaker":"松澤委員","kind":"質問","question":"実績じゃないんですよ。６５歳以上の高齢者というのは６万８,０００人もいるんですけれども、この高齢者給食サービスに該当する人数は何人いらっしゃるのですかということです。","respondent":"冨岡高齢者福祉課長","answer":"ひとり暮らし等高齢者の方の数は３万５,５４８名です。","id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"３万５,０００という数字がいいんだという仮定で話をしていきます。３万５,０００人もいる中で、この事業を行って、今お話がありましたよね、２００人ぐらいですか、これだけの方たちに給食サービスをしている。では、この人たちをどのような形でチョイスしているのでしょうか。どのような形で応募されているのか、その辺もお聞きしたいと思います。","respondent":"宮地地域振興事業部長","answer":"ただ、こうしたニーズをどうやって把握していくかというのは、まさに今テーマで、品川第二地区管内で、ニーズの拾い上げ方、それからマッチングの仕方、そういったことを今もっと積極的にできないかということで、ちょうどモデル実施をしているところですので。","id":"exchange-113"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。さらに漏れている方を救ってあげていっていただきたいと思います。地域振興事業部のほうでは、個人負担が、学校給食２９０円、夕食が４００円、ボランティア給食が２９０円と書いてあるんですけれども、品川の福祉のほうでは、学校給食３５０円、ボランティア給食が３５０円と書いてあります。これが何で違うのか。この点についてお聞きしたいと思います。","respondent":"秋山協働・国際担当課長、宮地地域振興事業部長","answer":"平成２１年度より学校給食に関しましては、昼食３５０円、夕食に関しては４５０円、ボランティア給食については３５０円ということで改定をしております。自己負担分ですけれども、２９０円だったのが値上がりして３５０円に平成２１年度からなっておりますので、ちょっと校正でミスがあったかもしれませんが、統一的にお昼は３５０円、夕食は４５０円という形になっております。","id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"はい、わかりました。２点目、ほっとサロンです。ほっとサロンとはどういうようなものなのかについてお聞きしたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"あるいはさまざまな催し物に参加していただく。そういった場所と講座の提供等です。","id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"ほっとサロン、今年度の予算では３カ所、昨年は２カ所でしたので、もう１カ所がどこかなということをお教えしていただきたいのと、このほっとサロン、先日ですかね、社会貢献活動見本市に行きましたら、何団体か活発に活動していました。ほっとサロン施策そのものは、私は大変に生きがいづくりでいいと思っているんです。その辺の整合性をどう考えているのか、お聞きしたいと思います。","respondent":"永尾高齢者いきがい課長","answer":"シルバーセンターのグループ利用の件だと思いますが、グループ利用というのは、ある固定したグループがその場所を使って活動するというやり方をしておりまして、ほっとサロンというのは、地域に開放してやるもので、グループのメンバーだけではなくて。","id":"exchange-116"},{"speaker":"松澤委員","kind":"意見","question":"それで結構です。３点目に行きます。住宅あっせん、これが毎年毎年あっ旋の数が減っています。何でなのかな。高齢者で希望する方はたくさんいると思うんですが、その辺について説明してください。","respondent":"永尾高齢者いきがい課長、秋山協働・国際担当課長","answer":"今年度、平成２１年度の状況を見ると、過去に比べて随分減っている状況になっておりますけれども、推測するには、立ち退き等が、経済状況の影響もあって、少なくなっているように見えます。先ほどの金額の件ですけれども、地域振興事業部の事務事業概要につきましては、平成２０年度の実績のほうを記入していますので、平成２１年度の金額を私のほうでご説明させていただきました。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"日本経済の悪化や高齢者人口の増により、社会福祉費などの扶助費の増加傾向は今後続くと思われますが、特に気になるのは、区長もおっしゃっていましたが、緊急対応策としてやむを得ない事情だと思いますが、児童に対する予算が５５億円と著しく今回伸びているということを考えますと、区民からいただいている税金でやる予算の使い方が偏っていないのかなと思うんですが。","respondent":"金子企画財政課長","answer":"子ども手当はご案内のとおり、国費ですので、国策として実施しているものを私どもが受託しているものであります。生保のほうに関しては、先ほど来出ていますとおり、社会情勢、社会経済情勢の反映で、やむを得ない部分があります。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"お話は、先ほどからもいろいろ出ていまして、お聞きしております。ですが、さまざまな年代の方が、区民がさまざまな生活環境において日常生活を送っているわけです。そうすると、考えますと、収入の多い方には、ある程度負担を増やすような考え方も必要じゃないかと思うんですが、その点についてご見解をお聞かせください。","respondent":"金子企画財政課長","answer":"国のほうで上限を定めておる関係がありますが、上限を伸ばすなど、個々の事業につきまして、そういった所得制限のあり方も考えながら、全体の政策について見直していきたいと考えています。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"品川区では、持っているデータでは、先ほどお話がありましたが、約３,８００人ほどの方がいらっしゃるということですが、彼らの相談相手になる、いろいろ指導したり、相談相手になるケースワーカーは品川区に何人ぐらいいるのでしょうか。それでその方は、全員区の職員でしょうか。そして、その方たちは、全員が社会福祉主事の資格を取っているのですか。その３点についてお聞かせください。","respondent":"平澤生活福祉課長","answer":"初めの数字なんですけれども、申しわけございません、私の申し上げ方が悪かったかと思うんですけれども、３,８７０世帯です。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"確かに大変な部署だと思います。扶助ということで、生活、教育、住宅、医療、介護、出産、生業、いろんな扶助制度があります。そうすると、実際基本的なケースワーカーの人数というのは、一応明記されているのは８０人。１人が大体８０人を見るのがいいんだよ。それが今、３８名で、相当の人数が品川区の中にいらっしゃるということですよね。それでいいんですか。","respondent":"平澤生活福祉課長","answer":"ケースワーカーの事務を補助するということで、例えば資産を調査する専門員、それから就労を支援する専門員、また心の病といったようなもののご相談に応じる専門員、こういったもののお力も借りながら行っているです。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問・要望","question":"今お話は聞きましたが、専門員ということですが、やっぱり対象者が多ければ、１人当たりの相談の日数、また対応、中には社会復帰していただきたい、生業についていただきたい、そういう相談、病気、それから買い物にも行けない、さまざまあると思うんですが、そういう方たちにも実際対応できる人数として区はしっかりやっていると考えてよろしいですか。","respondent":"平澤生活福祉課長","answer":"それこそ毎週のように電話がかかってまいりまして、相談がある者もおりますし、地域の中で比較的安定して生活を送っていらっしゃる方もいらっしゃいます。そういった意味、それから、先ほど申し上げました専門員との連携、そういったところで現在仕事を進めているです。","id":"exchange-122"},{"speaker":"武内委員","kind":"質問・要望","question":"初めに２２１ページのほうですけれども、今、見守りネットワークのほうが１１町会でやられているということですけれども、これについて、今後の目標というか、全町会、全自治会まで広げていきたいというご希望はあると思うんですけれども、それについてどのようにやっていくのかいうことと、それからあと、品川第二地区で、生活応援事業、モデル的にやっていらっしゃるということで、１２月ですか。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"どういうご希望のサービスがあるかということをいろいろ挙げていただきまして、内容を検討させていただいている、分析しているところでございまして、サロンとか、主なものとしましては、相談窓口。家庭あんしんセンターの中の子育て支援センターのほうで行っております養育訪問事業ですけれども、こちらのほうは、子どもの成長が懸念されるということで、特にネグレクトというようなケース、なかなか家の中を片付けられないとか。","id":"exchange-123"},{"speaker":"武内委員","kind":"質問・要望","question":"これが理想で、これが一番いいと思うんですけれども、そうこう言っている間に、そんなに救急車を呼ぶほどじゃない緊急じゃないけれども、どこかに相談したいとか、どこかに頼りたいという場合の緊急通報というか、ワンストップのそうした相談窓口みたいなものを私は要望したんですけれども、こういった今の取り組みですとか。","respondent":"冨岡高齢者福祉課長、安井子育て支援課長","answer":"地域の見守り、私ども、高齢者の方の見守りとか、それから、ちょっとしたニーズにどういうふうにお答えしていくかという、まさに２４時間の求められているものというのは、今、部分的ではありますけれども。具体的に緊急にさまざまな対応をしなければならないという判断をする場として、協議会のケース会議を開催しておりますが、今日現在、１４回、対象人数、対象児童数１８名、それについて。","id":"exchange-124"},{"speaker":"須藤委員","kind":"質問・要望","question":"２１７ページ、特別養護老人ホーム建設費助成についてお尋ねします。これでベッド数がどのくらいトータルであるのか教えていただきたいと思います。その後についてはどういうお考え、何か考えを持っているのかどうか。このあたりは、このままずっとここのベッドが借用できる状況になってくるのか。そのあたりを教えてください。","respondent":"冨岡高齢者福祉課長","answer":"この建設費助成によりまして、７０床のベッドを確保しています。それから、債務負担行為が徐々にどんどん終わってまいりますけれども、終わったところもあるわけですが、引き続きお願いをしていくというところで、この部分については考えているところです。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"平成２９年ぐらいまでに全部終わりますよね。ですから、まだ２０２５年までは高齢者が増えてくるよという状況にあるときに、こういう考え方で、区外のほうに老人ホームをつくっていくという考え方はお持ちなのかどうか。債務負担行為があと五、六年で終わってきますので、その件についてお聞かせください。","respondent":"冨岡高齢者福祉課長","answer":"これは相手方があることでもありますが、現実的にほかのほうからどうだという提案がございませんので、これ限りということで、今のところは考えているところです。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"２１９ページに障害者ライフサイクル総合支援検討委託とあります。新しい事業ということなんですが、これはどういうふうに流れていくのか、ご説明お願いします。","respondent":"高橋障害者福祉課長","answer":"背景としましては、障害者の施設サービスが平成２１年４月に移ったこととあわせて、新たな障害特性ということで、脳血管障害とか、事故による高次脳機能障害、難病、進行性疾病、発達障害ということで、新たとは言いませんが、障害者手帳の対象にならないんですが。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問","question":"検討委託というのは、委託先はどこかわかっていますでしょうか。","respondent":"高橋障害者福祉課長","answer":"予算が決定された段階で、それから選定ということになります。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"２２３ページの品川区シルバー人材センター支援事業、国の仕分けで予算が云々というので、請願もあがってきたところですけれども、予算書を見ると、昨年とほとんど同じような仕組みがつくられているんですけれども、今後ずっとシルバー人材センターについては支援していくというか、こういう形がとれるのかどうか教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"都からも補助金は来ているんですけれども、それは昨年と同様です。区の補助金も同様です。今後ですけれども、シルバー人材センター、地域にとって大切な事業ですので、区としては支援は続けていくということで考えてあります。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"予算的にはここにあるけれども、直接的にシルバー人材センターの事業に対して国の補助が減ると、そういったマイナス点は出てくるのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"実際には、国からの直接補助金が減っているです。それに対しまして、シルバー人材センターとしても、さまざまな節約の措置をとっていくということで、何とか耐えていこうということで、来年度は何とかもつかと考えています。","id":"exchange-130"},{"speaker":"須藤委員","kind":"質問・要望","question":"シルバーの方々の就労というのは、これから介護予防とかいう表現、これからまた質問するんだけど、そういった高齢者に対して非常に生きがいになるので、これもしっかり支援できる仕組みは区としも考えておいていただきたいと思います。よろしくお願いします。介護という言葉はいつごろつくられた言葉なんでしょうか。","respondent":"冨岡高齢者福祉課長","answer":"介護という言葉がいつつくられたか、申しわけございません、私、存じておりませんが、人をケアをする、お世話をするという意味の介護というふうに理解しています。","id":"exchange-131"},{"speaker":"須藤委員","kind":"意見","question":"広辞苑だと、介護というのが高齢者、病人などを介抱し、日常生活を助けること。古い大言海なんかには、介護という言葉は載っかってないんですね。この表記の仕方がどうなのかなと。２２３ページの介護予防事業というのが、むしろ老化予防事業とか、こっちはいきいきどうのと、いきいきという言葉を使っているんだけど、介護予防という言葉は使えるのかねと思うんだけど。そういう日本語があるのかなと。","respondent":"冨岡高齢者福祉課長","answer":"これは第３期の介護保険事業計画といいますか、その時期に合わせた国の制度の変更で、介護状態を予防するという意味で介護予防という表現が使われたというふうに、それから広く事業的にも展開されていったと理解しておりまして、介護という、本来的な意から。","id":"exchange-132"},{"speaker":"須藤委員","kind":"質問・要望","question":"高齢者のいろんないきがいの仕事を、高齢者クラブとか、いろいろやっていますよね。２３５ページの障害者福祉施設運営費についてお尋ねします。障害者福祉施設、いろいろできてきているんですが、この委託先については、先ほど来いろんな難病があったり、新しく認定されてきた障害があったりしてくるんだけど、こういう施設の振り分けというのは、どういう考え方でそれぞれの法人に託しているのでしょうか。","respondent":"高橋障害者福祉課長","answer":"多分委員がおっしゃっているのは、指定管理の話なのかなと思いますが、得意分野の施設に利用者を入所なり利用させるということは、その辺につきましては、ご本人のケアマネジメント、家族のケアマネジメントを含めまして、そういうことを含めて適切な施設なり。","id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは、大きくは３点にわたって聞かせていただきます。もう１点は、生活保護と、２５９ページですか、さらにひとり親家庭の母子家庭ですね、２４１ページ絡み、この辺のところで扱い等についてお聞かせいただきたいと思います。それがここでまた同じ名前だけれども、出てくるとなると、どう違うのか。なぜ今回ここに出てくるのかということをお伺いをしたい。この中ではやるわけですから。とりあえず１回。","respondent":"吉岡保育課長","answer":"今、保育ママ制度の再構築ということで掲げましたのは、従前のような家庭でやっていただくことも含め、また先ほど来のお話にもありましたように、いろんな施設を活用するとか、また空き店舗を使っていただくとか、いろんな形も考えられると思いますので。","id":"exchange-134"},{"speaker":"土井委員","kind":"質問・要望","question":"共同事業です。ミスはあることですから、構わない。今回もそれの余韻が残っていますよというようにご説明の中で聞こえたんですけれども、そうすると、その余韻の部分を消し取った残りの芯の部分はわかるようにならないんですかということなんです。移りますよね。こういう仕組み、要するに相談も含めて来ているわけですから、そういう仕組みにしてもらいたいと思うんですけれども、その辺についていかがか。","respondent":"吉岡保育課長、安井子育て支援課長","answer":"もう一つ、いろんなグループで、交代で見るとか、共同で見るとか、あるいは、空き店舗を活用したり、いろんな区の施設を活用したりという形は、厳密に言えば、国で言っている保育ママ制度。ただ、外国人登録の場合、職権消除みたいなことがございませんので、こちらについては、民生委員のほうに確認していただくという形をとっているんですけれども、こちらについては、民生委員のほうに連絡をとりまして。","id":"exchange-135"},{"speaker":"土井委員","kind":"質問","question":"国保があるんだけど、先に言いたいことを言っちゃいます。保育ママの件ですけれども、こういう状況となると、幅広くいろんなことを考えなきゃいけないので、その昔、大変なときには、みんな集まってお母さん同士で何とかしようというのがあったわけですから、そこら辺まで行くかどうかは別として、ちょっと範囲が広げられる方法を一生懸命考えておいてくださいということです。","respondent":"本城国保医療年金課長","answer":"先ほどの共同事業交付金の関係ですが、こちらのほう、補正の中でもご説明させていただきましたが、平成２０年度、平成２１年度にまたがる過誤であったものですから、平成２１年度分に影響する過誤につきましては、平成２１年度の補正の中で対応させていただきまして。","id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"だから、それを聞いているんです。精算分は幾らなのと。そういうのがここにまざっていますよというのは、これだけまざっているんですよとやらないと、芯のやつがわからない。本当のやつがわからない。そうすると、おととしのやつがまざっているということになるわけですね。それがわかりませんかとお伺いしているんです。","respondent":"本城国保医療年金課長","answer":"精算分ということで、内訳は書かせていただいてございませんでしたが、高額医療費共同事業につきましては、１億６,０００万円ほどの精算額、保険財政共同安定化事業のほうは、５億４,０００万円ほどの精算額となっているところです。","id":"exchange-137"},{"speaker":"南委員","kind":"質問","question":"２４６ページの児童福祉施設費について伺います。先だって本会議のときに定員拡大の問題で質問した際に、答弁された区長は、次のように答弁されました。平成２０年度に至るまで、定員拡大をしているが、昭和６２年に比べればまだ少ない。こういう答弁でした。この定員拡大とはいつから始まったのか、まず伺います。","respondent":"吉岡保育課長","answer":"それでその後、平成９年から平成１２年までは定員の変動はございませんで、平成１３年から定員の増が、例えば平成１３年度は対前年度比３３人、平成１４年が２６人というように上昇傾向に転じたものです。","id":"exchange-138"},{"speaker":"南委員","kind":"確認","question":"私も書類で確認をさせていただきました。その中身というのは、幼保一体施設を３カ所つくったことと大井保育園などのように学童保育施設のスペース部分が保育園の保育室として整備されたということで、それぞれ合わせて２８７人の定員拡大、平成１８年までの時点で２８７人増えたと、こういうふうに思うわけですけれども、その辺の確認をしたいと思います。","respondent":"吉岡保育課長","answer":"私立保育園ですけれども、現在の園数は、現在１０園です。それから、園児の定員につきましては、それぞれ変動はあるものと思ってあります。それから、平成１８年からの状況ということでいえば、年々定員としては、それぞれ四十数人から１００人以上増えているという状況です。","id":"exchange-139"},{"speaker":"南委員","kind":"確認","question":"私立保育園は、確かに１０園は１０園ですけど、定員が違っているということで、公立保育園のところだけを見て私は質問するという、そういう意味ですので、よろしくお願いいたします。昭和６２年当時の公立保育園は３７園で、当時の定員は３,５１６人でした。したがって、違うということを確認したいと思います。その辺についてはいかがでしょうか。","respondent":"吉岡保育課長","answer":"昭和６２年当時の定員については、３,５１６人ということでありますと、現在平成２１年度の定員が３,５００人ですので、ほぼ同じというのは間違っていないと思うところです。","id":"exchange-140"},{"speaker":"南委員","kind":"質問・要望","question":"本会議の答弁のことを言っているのですから、平成２１年度の数字を持ち出さないでくださいよ。昭和６２年のときの定員は３,５１６人ですけれども、在席は３,４２６人です。これは区が出されている資料に基づいてですから、間違いないと思いますので、それに比較をすると、５９人上回っているという、その確認をぜひしていただきたいと思います。","respondent":"吉岡保育課長","answer":"平成２０年度の定員は、３,４８５人で間違いございません。","id":"exchange-141"},{"speaker":"南委員","kind":"質問","question":"したがって、そういうきちんとした数字で答弁されずに、しかも当時の２２年前は定員割れ、今日は保育園の入園希望が殺到する、待機児が非常に続出しているという、こういう状況ですから、具体的な事実を見ないで、そういう数字でご紹介をしているということは正確性に欠けるということで、本会議でのそういう答弁は全くひどいなという印象を私は持ちました。豊かな保育環境を整備する。","respondent":"古川子ども未来事業部長","answer":"したがいまして、二十数年の中では、昭和６０年当時と平成２０年当時の中では、まだまだ昭和６０年当時のほうが定員としては大きいものを持っていたよ、こういう話でございまして、今、委員のほうでは、それを今度、公立の認可保育園でしょうか。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"そこは正確にしておかなくちゃいけないと思いましたので、私はあえて、本会議の区長の答弁の議事録を読み返して、そしてずっと経過を追って、先ほども冒頭紹介したように、資料をたぐって、見て、今の質問になっているわけですから、そこは違うということをはっきり申し上げたいと思います。この関係で見ると、１６１人、定員を超えて入園していると思いますけれども、この点についてはどうなんでしょうか。","respondent":"吉岡保育課長","answer":"平成２０年度の保育園在席数ですが、平成２０年４月１日現在で、公立が３,６４６人、私立が６７６人、合計４,３２２人となっています。","id":"exchange-143"},{"speaker":"南委員","kind":"質問","question":"私が質問しているのは、冒頭申し上げたように、公立保育園のことを質問していますので、私立はいいです。したがって、在席数は、公立は３,６４６人、そして……。私が聞いているのは公立園を聞いているんですからね。そして、公立保育園の定数についても教えてください。何人増えている状況なのかということも聞きましたので、正確に公立保育園の数字を言ってください。","respondent":"吉岡保育課長","answer":"平成２０年度の４月１日現在の公立保育園在席児３,６４６人です。なお、同じ時期、平成２０年４月１日の公立園の定員につきましては、３,４８５人、それから平成２１年４月１日現在の公立園の定員につきましては、３,５００人です。","id":"exchange-144"},{"speaker":"南委員","kind":"確認","question":"聞いてもいない平成２１年の数字も教えていただきました。しかし、聞いた、何人超えているのかという数字については答弁していませんから、私のほうであえて言いますけれども、平成２０年のときに１６１人を定員オーバーして、在席児数として措置をしているという、このことは確認をしたいと思います。最低基準を見て、余裕があるんだとなっているのですか。","respondent":"吉岡保育課長","answer":"面積につきましては、一応区の考え方は、日本全国同じですけれども、保育所の面積基準、それに基づいて考えているもので、０・１歳児については１人当たり３.３m2、２歳以上のお子さんについては１.９８m2と考えているというものです。","id":"exchange-145"},{"speaker":"南委員","kind":"確認","question":"そのことを確認したいと思います。平成２１年度の在席数は３,７７４人。定数は３,５００人ですから、この年も２７４人を超えて、定員より超えて保育園に入園を受け入れておられます。こういう事態の中で、キャパシティが増えていないのに、どういうふうな保育になっているかということを、詰め込みそのものだと私は思うんですけれども、この点についての見解はどうでしょうか。","respondent":"吉岡保育課長","answer":"初めに、メジャーではかったですけれども、私、昨年の４月からの着任で、そこまでは承知してございません。それからあと、詰め込みについては、基準以上の子どもがいれば詰め込みですけれども、現在はそうではございませんので、そのように考えてはございません。","id":"exchange-146"},{"speaker":"三上委員","kind":"質問・要望","question":"私は２４５ページ、区内私立保育園経費の移転整備費助成、ここのところで、宝保育園ということであったと思いますけれども、どういう形になっていくのか、お知らせいただきたい。それから、２４９ページの保育園運営費の中で、大規模改修等施設整備、この計画の内容について簡単にお教えいただきたい。それから、今年の保育士の採用された人数、何人の方がいらっしゃるのか。","respondent":"吉岡保育課長","answer":"あわせて、今現在、今日現在で９３名の採用を予定していますけれども、こちらは、退職の者も出ておりますので、退職の補充の部分、それから、保育園の定員の拡大とか弾力化に必要な部分、それからあと、保育園の５歳児を小学校と連携をして保育をするような部分等々含めまして。","id":"exchange-147"},{"speaker":"三上委員","kind":"質問","question":"宝保育園は、場所が変わるということですか。それから、今年の採用人数については９３名ということで伺いましたが、この人たちについて、新人の教育ということになってくると、どういう取り組みをしていくかということが最も大事になってくると思うんですね。そういったことについての取り組みについて、短い時間でいいですから、お願いしたい。","respondent":"吉岡保育課長","answer":"こちらはいずれも平成２３年度に耐震改修工事を実施する予定ということで、今、設計をやっているところです。","id":"exchange-148"},{"speaker":"三上委員","kind":"質問・要望","question":"宝保育園についてはわかりました。兄弟２人、小山台保育園とほかの園と、兄弟別々なところに行っているけれども、小山台保育園はもう古くなって、あそこに子どもを入れたくないわという、そういう感じのことをおっしゃる方が実はいらっしゃいます。時間がありませんから、ご答弁いただかないで終わりますけれども、この次は決算特別委員会のときにでも、また同じような質問をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問","question":"私は、ページでいくと２１５ページ、社会福祉協議会、ボランティアセンター関係、それと関連して２２３ページのひとり暮らし高齢者等生活応援事業、それから、２２７ページ、自立支援（更生）医療、それから、２４１ページの認証保育所関係でお聞きします。これは補正予算でも６,０００万円ぐらいたしか増えたんですけれども、この状況をお知らせください。","respondent":"高橋障害者福祉課長、市岡総務部長","answer":"自立支援医療のご質問ですが、実態としまして、当初予算で３億２,７００万円でした。それが平成２１年度。今年度につきましては、４億５,０００万円ということで、約１億２,０００万円の増になっております。虐待暴力についてですけれども、総務費の答弁でもありましたけれども、配偶者暴力対策基本計画の中では、安心しながわネットワークという、そういう概念をご説明いたしました。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"というのは、生活保護は、品川区として１００億円近くになる中で、こういう見えない部分、表に、生活保護に出てない部分がまだあるのかなという、ほかにはないでしょうねというのを確認したかった。その辺で、入り口が別だから、ここは別になってしまうよというのではなく、子どもに限らず、いろんな部分で出てくると思いますので、ひとつきちんとした計画を立てていただきたいなということをお願いします。","respondent":"高橋障害者福祉課長","answer":"平成２０年度で生保の方は８８人おりまして、平成２２年１月末現在で１００人ですので、１２人は確実に増えているものです。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問","question":"わかりました。４２０万円の１００人、要するに４億円ぐらいいくと思うんですけれども、そうすると、その金額が別に出ていた。一般の区民サービスが多少でも減ってしまう可能性を持っている中で、数字的なものは、だれがもらっているじゃなくて、品川区の予算の中として、これだけのものを占めているということは、もうちょっと知らせてもいいんじゃないかなと思うんですが、いかがでしょうか。","respondent":"金子企画財政課長","answer":"特に生保につきましては、先ほど来申し上げていますとおり、４分の１枠負担がありますので、そういった財政負担が増えているということは、私ども、財政状況の公表という形もありますので、何らかの形で区民の方にはきちっとお示しはしていきたいと考えております。","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問","question":"そこの中でどういうすり合わせをしていくのか。ボランティアをやろうとしている方は、お１人ですよね。ですから、今度の活動に対しての高齢者福祉課と地域活動課の連携、どちらが主体になってこれからやっていくのかというのが１点。それから、ボランティアの方の集約、社協で今度のブランチに関しては、ここがやるんでしょうけれども、全体的な集約をどういうふうにしていくのか、その２点をお答えください。","respondent":"冨岡高齢者福祉課長、宮地地域振興事業部長","answer":"品川第二地区で展開しようとしているのがモデルになるかと思いますけれども、これについては、あくまでも地域センターの中のふれあい活動会議の事務局というところに社協のブランチが入りまして。ふれあいサポート活動そのものは、平成７年にスタートしたわけですけれども、福祉のほうからスタートしまして、すぐ地域センターのほうに、それぞれの地区での活動ということで移ってきました。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861914?Template=document&Id=934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":122026,"voices":372}}]);
